def _portrait_cache_dir() -> str:
    d = os.environ.get("PORTRAIT_CACHE_DIR") or (
        "/tmp/mx_portrait_cache"
        if os.getenv("RENDER")
        else os.path.join(app.instance_path, "portrait_cache")
    )
    os.makedirs(d, exist_ok=True)
    return d


def _portrait_cache_paths(portrait_id: int, etag: str) -> tuple[str, str]:
    safe = etag.strip('"').replace("/", "_")[:40]
    base = os.path.join(_portrait_cache_dir(), f"{portrait_id}_{safe}")
    return base + ".bin", base + ".mime"


def _cached_portrait_file(portrait_id: int) -> tuple[str, str] | None:
    """Senast cachade fil för förare — undvik DB-läsning."""
    import glob

    pattern = os.path.join(_portrait_cache_dir(), f"{int(portrait_id)}_*.bin")
    files = sorted(glob.glob(pattern))
    if not files:
        return None
    bin_path = files[-1]
    mime_path = bin_path.replace(".bin", ".mime")
    mime = "image/jpeg"
    if os.path.isfile(mime_path):
        with open(mime_path, encoding="utf-8") as f:
            mime = (f.read() or mime).strip() or mime
    return bin_path, mime


def _portrait_file_response(bin_path: str, mime: str, etag: str | None = None):
    from flask import send_file

    resp = send_file(bin_path, mimetype=mime, conditional=True)
    if etag:
        resp.headers["ETag"] = etag
    resp.headers["Cache-Control"] = "public, max-age=2592000, immutable"
    return resp


@app.after_request
def add_cache_headers(response):
    """
    Reduce Render bandwidth: cache static assets hard in browsers/CDNs.
    Keep HTML and API responses uncached by default.
    """
    try:
        path = (request.path or "")
        # Don't override explicit cache policies set by routes.
        if "Cache-Control" in response.headers:
            return response

        # Static assets: let browsers reuse files aggressively.
        if path.startswith("/static/"):
            # Longer cache for images; shorter for everything else to avoid stale JS/CSS issues.
            lower = path.lower()
            is_image = lower.endswith((".png", ".jpg", ".jpeg", ".webp", ".gif", ".svg", ".ico", ".avif"))
            is_asset = is_image or lower.endswith((".js", ".css", ".woff", ".woff2"))
            max_age = 60 * 60 * 24 * (30 if is_asset else 7)
            cc = f"public, max-age={max_age}"
            if is_asset:
                cc += ", immutable"
            response.headers["Cache-Control"] = cc
            return response
    except Exception:
        return response
    return response


# Offentlig Facebook-sida / profil (Miljövariabeln FACEBOOK_PAGE_URL åsidosätter).
DEFAULT_FACEBOOK_PAGE_URL = "https://www.facebook.com/profile.php?id=61586769893903"


@app.context_processor
def inject_facebook_social():
    """FACEBOOK_PAGE_URL + inbäddad tidslinje (Page Plugin), på som standard."""
    from urllib.parse import quote

    url = (os.getenv("FACEBOOK_PAGE_URL") or "").strip() or DEFAULT_FACEBOOK_PAGE_URL
    feed_env = (os.getenv("FACEBOOK_SHOW_FEED") or "").strip().lower()
    show_feed = feed_env not in ("0", "false", "no", "off")
    iframe_src = None
    if url and show_feed:
        q = quote(url, safe="")
        iframe_src = (
            "https://www.facebook.com/plugins/page.php?"
            f"href={q}&tabs=timeline&width=500&height=420"
            "&small_header=true&adapt_container_width=true"
            "&hide_cover=false&show_facepile=true"
        )
    return {
        "facebook_page_url": url,
        "facebook_show_timeline_embed": bool(iframe_src),
        "facebook_timeline_iframe_src": iframe_src,
        "current_year": date.today().year,
    }


