def series_display_name(name: str | None) -> str:
    """User-facing series label (DB keeps short names like Motocross / Supercross)."""
    n = (name or "").strip()
    if n == "Supercross":
        return "AMA Supercross"
    if n == "Motocross":
        return "Pro Motocross"
    if n == "SMX Finals":
        return "SMX Finals"
    if n.upper() == "MXON":
        return "MXoN"
    if n == AMA_TOTAL_SERIES_NAME:
        return "Totalställning"
    return n or "Serie"


def _next_competition_for_picks(
    *,
    series: str | None = None,
    require_open: bool = True,
) -> Competition | None:
    """
    Nästa tävling utan resultat i DB. Med require_open=True: bara där picks inte är låsta.
    Ignorerar stale global_simulation.active_race_id.
    """
    today = get_today()
    q = Competition.query.filter(Competition.event_date.isnot(None))
    if series:
        q = q.filter(Competition.series == series)
    for comp in q.order_by(Competition.event_date.asc()).all():
        if getattr(comp, "is_cancelled", False):
            continue
        if comp.event_date and comp.event_date < today:
            continue
        if CompetitionResult.query.filter_by(competition_id=comp.id).first():
            continue
        if require_open and is_picks_locked(comp):
            continue
        return comp
    return None


def _next_competition_for_pick_reminders() -> Competition | None:
    """
    Nästa race för picks-påminnelse-mail — inkl. WSX.
    Väljer snartaste start bland race utan resultat; föredrar öppna picks.
    """
    from datetime import datetime

    today = get_today()
    comps = (
        Competition.query
        .filter(Competition.event_date.isnot(None))
        .filter(Competition.event_date >= today)
        .all()
    )
    usable: list[Competition] = []
    for comp in comps:
        if getattr(comp, "is_cancelled", False):
            continue
        if CompetitionResult.query.filter_by(competition_id=comp.id).first():
            continue
        usable.append(comp)
    if not usable:
        return None

    unlocked = [c for c in usable if not is_picks_locked(c)]
    pool = unlocked or usable

    def _start_key(c: Competition):
        try:
            sched = _competition_race_schedule(c)
            utc = sched.get("race_datetime_utc")
        except Exception:
            utc = None
        if utc is None:
            utc = datetime.combine(c.event_date, datetime.max.time())
        # Same calendar day: prefer WSX (e.g. Canadian GP over an AMA national)
        series_rank = 0 if (getattr(c, "series", None) or "").upper() == "WSX" else 1
        return (c.event_date, series_rank, utc)

    pool.sort(key=_start_key)
    return pool[0]


def _home_primary_competition(*, require_open: bool = False) -> Competition | None:
    """Homepage default race: AMA chain SX → MX → SMX. WSX is opt-in via series card."""
    for series_code in ("SX", "MX", "SMX"):
        comp = _next_competition_for_picks(series=series_code, require_open=require_open)
        if comp is not None:
            return comp
    return None


# Tippa-only series (no season team; excluded from AMA fantasy totals)
TIPPA_ONLY_SERIES = frozenset({"WSX", "MXON", "MXGP"})


def is_tippa_only_series(series: str | None) -> bool:
    return (series or "").strip().upper() in TIPPA_ONLY_SERIES


def ama_competition_clause():
    """SQLAlchemy filter: competitions that count on AMA / global boards."""
    return db.or_(
        Competition.series.is_(None),
        ~Competition.series.in_(tuple(TIPPA_ONLY_SERIES)),
    )


def _season_team_target_year() -> int:
    """AMA calendar year the season team is built for (upcoming SX/MX/SMX)."""
    today = get_today()
    upcoming = (
        Competition.query.filter(
            Competition.event_date.isnot(None),
            Competition.event_date >= today,
            Competition.series.in_(("SX", "MX", "SMX")),
        )
        .order_by(Competition.event_date.asc(), Competition.id.asc())
        .first()
    )
    if upcoming and upcoming.event_date:
        return int(upcoming.event_date.year)
    return int(_current_racing_season_year())


def _first_ama_race_of_season(season_year: int | None = None) -> Competition | None:
    """Earliest SX/MX/SMX race in the season-team target year (by event_date)."""
    year = int(season_year or _season_team_target_year())
    return (
        Competition.query.filter(
            Competition.event_date.isnot(None),
            db.extract("year", Competition.event_date) == year,
            Competition.series.in_(("SX", "MX", "SMX")),
        )
        .order_by(Competition.event_date.asc(), Competition.id.asc())
        .first()
    )


def season_team_transfers_are_free() -> bool:
    """Free roster changes until tippa locks for the season's first AMA race."""
    first = _first_ama_race_of_season()
    if first is None:
        return True
    # Deadline (not preseason): free while tippa is still open / not yet due.
    return not is_picks_deadline_passed(first)


def season_team_transfer_window_info() -> dict:
    """UI flags + lock race for season-team builder / info copy."""
    year = _season_team_target_year()
    first = _first_ama_race_of_season(year)
    free = True if first is None else not is_picks_deadline_passed(first)
    return {
        "free": free,
        "season_year": year,
        "lock_race_name": (first.name if first else None),
        "lock_race_date": (
            first.event_date.isoformat() if first and first.event_date else None
        ),
    }


def _home_default_countdown_series() -> str:
    """Default countdown series for homepage (never auto-select WSX/MXON)."""
    for series_code in ("SX", "MX", "SMX"):
        if _next_competition_for_picks(series=series_code, require_open=False) is not None:
            return series_code
    return "SX"


def _normalize_countdown_series(raw: str | None) -> str | None:
    if not raw:
        return None
    key = str(raw).strip().upper().replace(" ", "")
    aliases = {
        "SX": "SX",
        "SUPERCROSS": "SX",
        "MX": "MX",
        "MOTOCROSS": "MX",
        "SMX": "SMX",
        "SMXFINALS": "SMX",
        "WSX": "WSX",
        "MXGP": "MXGP",
        "MXON": "MXON",
        "MXONATIONS": "MXON",
        "MOTOCROSSOFNATIONS": "MXON",
    }
    return aliases.get(key)


def _current_picks_competition() -> Competition | None:
    """Nästa tävling utan resultat — inkl. låsta picks (t.ex. Hangtown efter deadline)."""
    return _next_competition_for_picks(require_open=False)


def _next_open_picks_competition() -> Competition | None:
    """Nästa tävling där picks fortfarande går att ändra."""
    return _next_competition_for_picks(require_open=True)


def _can_view_other_users_picks(comp: Competition) -> bool:
    """Tillåt visning när race-deadline passerat eller race är färdigt (inte preseason-lås)."""
    if is_picks_deadline_passed(comp):
        return True
    series = (getattr(comp, "series", None) or "").upper()
    if series == "MXON":
        try:
            from mxon_fantasy import mxon_has_official_results

            return mxon_has_official_results(int(comp.id))
        except Exception:
            return False
    return (
        CompetitionResult.query.filter_by(competition_id=comp.id).first() is not None
    )


def _competition_for_viewing_other_picks(
    *,
    upcoming: Competition | None = None,
) -> Competition | None:
    """Tävling som 'Se andras picks' ska visa — aktuell pick-race."""
    if upcoming:
        return upcoming
    return _current_picks_competition()


def _is_mx_season_started(today: date | None = None) -> bool:
    """True once the outdoor MX calendar has begun (first MX race day or any MX results)."""
    today = today or date.today()
    mx_comps = [
        c
        for c in Competition.query.filter(Competition.series == "MX").all()
        if c.event_date
    ]
    if not mx_comps:
        return False
    first_mx = min(mx_comps, key=lambda c: c.event_date)
    if today >= first_mx.event_date:
        return True
    return (
        db.session.query(CompetitionResult.result_id)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .filter(Competition.series == "MX")
        .first()
        is not None
    )


def build_sx_season_wrap_context(competitions: list, today: date) -> dict | None:
    """
    Homepage hero between SX finale (last SX has results) and the first MX race day.
    Hidden once the first Motocross round starts (today >= first MX event_date), e.g. after Fox Raceway.
    """
    try:
        sx_comps = [
            c
            for c in competitions
            if getattr(c, "series", None) == "SX" and c.event_date
        ]
        mx_comps = [
            c
            for c in competitions
            if getattr(c, "series", None) == "MX" and c.event_date
        ]
        if not sx_comps or not mx_comps:
            return None

        last_sx = max(sx_comps, key=lambda c: c.event_date)
        if last_sx.event_date > today:
            return None
        if not CompetitionResult.query.filter_by(competition_id=last_sx.id).first():
            return None

        first_mx = min(mx_comps, key=lambda c: c.event_date)
        if today >= first_mx.event_date:
            return None

        days = (first_mx.event_date - today).days
        return {
            "headline": "Supercrossen är i mål!",
            "tagline": "Inomhussäsongen är färdigspelad — utomhus väntar runt hörnet.",
            "last_race_name": last_sx.name,
            "last_race_date": last_sx.event_date,
            "season_year": last_sx.event_date.year,
            "next_mx_id": first_mx.id,
            "next_mx_name": first_mx.name,
            "next_mx_date": first_mx.event_date,
            "days_until_mx": int(days),
        }
    except Exception as e:
        print(f"build_sx_season_wrap_context: {e}")
        return None


