def _smx_entry_name_key(name: str | None) -> str:
    s = (name or "").strip().lower()
    s = (
        s.replace("ø", "o")
        .replace("ö", "o")
        .replace("ü", "u")
        .replace("ä", "a")
        .replace(".", "")
        .replace("'", "")
    )
    s = re.sub(r"\s+", " ", s).strip()
    return _SMX_ENTRY_NAME_ALIASES.get(s, s)


def _smx_entry_names_for_competition(comp: Competition | None) -> dict[str, set[str]]:
    if not comp or (getattr(comp, "series", None) or "").strip().upper() != "SMX":
        return {}
    return dict(_SMX_ENTRY_BY_COMP_NAME.get((comp.name or "").strip(), {}) or {})


def _smx_resolve_entry_rider_ids(comp: Competition | None) -> dict[str, set[int]]:
    """Map entry-list names → rider ids for 450/250."""
    names_by_class = _smx_entry_names_for_competition(comp)
    if not names_by_class:
        return {"450": set(), "250": set()}

    out: dict[str, set[int]] = {"450": set(), "250": set()}
    for class_key, class_name in (("450", "450cc"), ("250", "250cc")):
        wanted = {_smx_entry_name_key(n) for n in (names_by_class.get(class_key) or set())}
        if not wanted:
            continue
        riders = (
            rider_query_for_list_ui()
            .filter(Rider.class_name == class_name)
            .all()
        )
        by_key: dict[str, Rider] = {}
        for r in riders:
            by_key[_smx_entry_name_key(r.name)] = r
        for key in wanted:
            rider = by_key.get(key)
            if rider:
                out[class_key].add(int(rider.id))
    return out


def sync_smx_playoff_entry_list(comp: Competition | None) -> dict:
    """
    Align SMX tippa with provisional entry list for this round.
    Combined riders not on entry → OUT. Entry riders clear OUT.
    Also fixes known plate numbers (e.g. Dean Wilson #15).
    """
    if not comp or (getattr(comp, "series", None) or "").strip().upper() != "SMX":
        return {"skipped": True, "reason": "not_smx"}
    names_by_class = _smx_entry_names_for_competition(comp)
    if not names_by_class:
        return {"skipped": True, "reason": "no_entry_map"}

    entry_ids = _smx_resolve_entry_rider_ids(comp)
    entry_all = set(entry_ids.get("450") or ()) | set(entry_ids.get("250") or ())
    combined = smx_playoff_field_meta(limit=30, competition=None)
    combined_all = set((combined.get("450") or {})) | set((combined.get("250") or {}))

    # Plate fix: Dean Wilson races #15 in 2026 SMX
    wilson = (
        rider_query_for_list_ui()
        .filter(Rider.class_name == "450cc", Rider.name == "Dean Wilson")
        .first()
    )
    number_fixes = 0
    if wilson and int(wilson.rider_number or 0) != 15:
        wilson.rider_number = 15
        number_fixes += 1

    marked_out = 0
    cleared = 0
    for rid in combined_all:
        on_entry = rid in entry_all
        row = CompetitionRiderStatus.query.filter_by(
            competition_id=comp.id, rider_id=rid
        ).first()
        if on_entry:
            if row:
                db.session.delete(row)
                cleared += 1
            continue
        if not row:
            db.session.add(
                CompetitionRiderStatus(
                    competition_id=comp.id, rider_id=rid, status="OUT"
                )
            )
            marked_out += 1
        elif row.status != "OUT":
            row.status = "OUT"
            marked_out += 1

    # Entry-only fill-ins must not stay OUT
    for rid in entry_all:
        row = CompetitionRiderStatus.query.filter_by(
            competition_id=comp.id, rider_id=rid
        ).first()
        if row:
            db.session.delete(row)
            cleared += 1

    if marked_out or cleared or number_fixes:
        db.session.commit()

    # Drop OUT rows that belong to other series (e.g. WSX twin riders)
    stray_cleared = 0
    try:
        stray_rows = (
            db.session.query(CompetitionRiderStatus)
            .join(Rider, Rider.id == CompetitionRiderStatus.rider_id)
            .filter(
                CompetitionRiderStatus.competition_id == comp.id,
                CompetitionRiderStatus.status == "OUT",
                ~Rider.class_name.in_(("450cc", "250cc")),
            )
            .all()
        )
        for row in stray_rows:
            db.session.delete(row)
            stray_cleared += 1
        if stray_cleared:
            db.session.commit()
    except Exception as stray_err:
        print(f"[SMX-ENTRY] stray OUT purge skipped: {stray_err}")
        try:
            db.session.rollback()
        except Exception:
            pass

    try:
        prune_off_roster_smx_picks(int(comp.id))
    except Exception as prune_err:
        print(f"[SMX-ENTRY] pick prune skipped: {prune_err}")

    info = {
        "competition_id": int(comp.id),
        "entry_450": len(entry_ids.get("450") or ()),
        "entry_250": len(entry_ids.get("250") or ()),
        "marked_out": marked_out,
        "cleared": cleared,
        "stray_cleared": stray_cleared,
        "number_fixes": number_fixes,
    }
    print(
        f"[SMX-ENTRY] {comp.name}: out={marked_out} cleared={cleared} "
        f"stray={stray_cleared} entry={info['entry_450']}+{info['entry_250']} "
        f"number_fixes={number_fixes}"
    )
    return info





# WSX seed/roster/sync → wsx_fantasy.py (skiva 8)

def _race_prep_venue_label(comp: Competition | None) -> str | None:
    if not comp:
        return None
    loc = (getattr(comp, "location", None) or "").strip()
    if loc:
        return loc
    series = (getattr(comp, "series", None) or "").upper()
    if series == "WSX":
        return _WSX_VENUE_BY_NAME.get((comp.name or "").strip())
    if series == "MXON":
        return "Ernée — Circuit Raymond Demy · kval lör · race sön"
    return None


def _race_prep_start_label(comp: Competition | None) -> str | None:
    """Local start time label for Inför racet (e.g. 19:30 MDT)."""
    if not comp:
        return None
    st = getattr(comp, "start_time", None)
    hhmm = None
    if st:
        try:
            hhmm = st.strftime("%H:%M") if hasattr(st, "strftime") else str(st)[:5]
        except Exception:
            hhmm = str(st)[:5]
        if hhmm in ("None", "null", ""):
            hhmm = None
    # Seed fallback for known WSX rounds when DB start_time is still blank
    if not hhmm and (getattr(comp, "series", None) or "").upper() == "WSX":
        hhmm = {
            "Canadian GP": "19:30",
        }.get((comp.name or "").strip())
    if not hhmm and (getattr(comp, "series", None) or "").upper() == "MXON":
        hhmm = "14:30"  # MXGP Qual lör, lokal tid (Motoclub Ernée 2026)
    if not hhmm:
        return None
    tz = (getattr(comp, "timezone", None) or "").strip()
    tz_short = {
        "America/Edmonton": "MDT",
        "America/Los_Angeles": "PT",
        "America/Denver": "MT",
        "America/Chicago": "CT",
        "America/New_York": "ET",
        "Europe/London": "BST/GMT",
        "Europe/Paris": "CEST/CET",
        "Australia/Brisbane": "AEST",
        "Pacific/Auckland": "NZDT",
        "America/Argentina/Buenos_Aires": "ART",
        "Africa/Johannesburg": "SAST",
    }.get(tz)
    if tz_short:
        return f"{hhmm} {tz_short} (banans tid)"
    if tz:
        return f"{hhmm} lokal tid"
    return hhmm





