# Pages
# -------------------------------------------------
def _upcoming_competitions_without_results() -> dict[str, list[Competition]]:
    """Framtida tävlingar utan resultat, grupperade per series-kod (en DB-pass)."""
    today = get_today()
    result_comp_ids = {
        int(row[0])
        for row in db.session.query(CompetitionResult.competition_id).distinct().all()
        if row[0] is not None
    }
    comps = (
        Competition.query.filter(Competition.event_date.isnot(None))
        .filter(Competition.event_date >= today)
        .order_by(Competition.event_date.asc(), Competition.id.asc())
        .all()
    )
    grouped: dict[str, list[Competition]] = defaultdict(list)
    for comp in comps:
        if getattr(comp, "is_cancelled", False):
            continue
        if comp.id in result_comp_ids:
            continue
        code = (comp.series or "").strip()
        if code:
            grouped[code].append(comp)
    return grouped


def _pick_next_competition(
    candidates: list[Competition],
    *,
    require_open: bool,
) -> Competition | None:
    for comp in candidates:
        if require_open and is_picks_locked(comp):
            continue
        return comp
    return None


def build_series_status_list() -> list[dict]:
    """Seriekort för startsidan — cachad, undviker upprepade fullskanningar."""
    global _SERIES_STATUS_CACHE
    now = time.time()
    if _SERIES_STATUS_CACHE and _SERIES_STATUS_CACHE[0] > now:
        return _SERIES_STATUS_CACHE[1]

    from sqlalchemy import or_, and_

    current_date = get_today()
    all_series = Series.query.filter(
        or_(
            Series.year.in_((2026, 2027)),
            and_(Series.year == 2025, Series.end_date != None, Series.end_date >= current_date),
        )
    ).all()

    # Tie-break only — real card order is next-race / finished-last in _series_sort_key
    series_order = {
        "Supercross": 1,
        "Motocross": 2,
        "SMX Finals": 3,
        "WSX": 4,
        "MXGP": 5,
        "MXON": 6,
        "MXoN": 6,
    }
    all_series.sort(key=lambda s: series_order.get(s.name, 999))

    simulation_active = False
    try:
        simulation_active = (
            GlobalSimulation.query.filter_by(id=1, active=True).first() is not None
        )
    except Exception:
        simulation_active = False

    upcoming_by_series = _upcoming_competitions_without_results()
    series_data: list[dict] = []

    for s in all_series:
        # Synthetic AMA Total belongs on Finished series / totals — not homepage "Välj Serie".
        if (s.name or "").strip() == AMA_TOTAL_SERIES_NAME:
            continue
        # One MXGP homepage card only (2027 UC). Keep 2026 series in DB for calendar/admin.
        if s.name == "MXGP" and int(getattr(s, "year", 0) or 0) != 2027:
            continue
        # AMA tippa: once next year's Series exists, drop prior year from Välj Serie
        # (finished seasons live in Fantasy-arkiv — not as Avslutad/Startar-om twins).
        if s.name in ("Supercross", "Motocross", "SMX Finals"):
            sy = int(getattr(s, "year", 0) or 0)
            if sy and any(
                (o.name == s.name)
                and int(getattr(o, "year", 0) or 0) > sy
                for o in all_series
            ):
                continue

        series_code = None
        if s.name == "Supercross":
            series_code = "SX"
        elif s.name == "Motocross":
            series_code = "MX"
        elif s.name == "SMX Finals":
            series_code = "SMX"
        elif s.name == "WSX":
            series_code = "WSX"
        elif s.name in ("MXON", "MXoN"):
            series_code = "MXON"
        elif s.name == "MXGP":
            series_code = "MXGP"

        series_year = int(getattr(s, "year", 0) or 0)

        def _candidates_for_this_series(code: str) -> list:
            raw = upcoming_by_series.get(code, [])
            # Prefer series_id match so 2026 cards never steal 2027 races
            by_id = [c for c in raw if getattr(c, "series_id", None) == s.id]
            if by_id:
                return by_id
            if series_year:
                return [
                    c
                    for c in raw
                    if getattr(c, "event_date", None) is not None
                    and c.event_date.year == series_year
                ]
            return []

        next_race = None
        if series_code:
            candidates = _candidates_for_this_series(series_code)
            next_race = _pick_next_competition(candidates, require_open=True)
            if not next_race:
                next_race = _pick_next_competition(candidates, require_open=False)
        if not next_race:
            next_race = next(
                (
                    c
                    for c in (
                        Competition.query.filter_by(series_id=s.id)
                        .filter(Competition.event_date >= current_date)
                        .order_by(Competition.event_date)
                        .all()
                    )
                    if not getattr(c, "is_cancelled", False)
                ),
                None,
            )

        under_construction = False
        if series_code == "MXGP":
            try:
                from mxgp_fantasy import (
                    ADMIN_TEST_GP_NAME,
                    mxgp_public_play_enabled,
                )

                under_construction = not mxgp_public_play_enabled()
                # Public card: never advertise Admin Test GP as "next race"
                # (it sorted MXGP above live WSX while UC).
                if next_race and getattr(next_race, "name", None) == ADMIN_TEST_GP_NAME:
                    next_race = None
                if under_construction:
                    real_upcoming = [
                        c
                        for c in _candidates_for_this_series("MXGP")
                        if getattr(c, "name", None) != ADMIN_TEST_GP_NAME
                        and not getattr(c, "is_cancelled", False)
                    ]
                    next_race = _pick_next_competition(real_upcoming, require_open=False)
                    if not next_race:
                        next_race = next(
                            (
                                c
                                for c in (
                                    Competition.query.filter_by(series="MXGP")
                                    .filter(Competition.event_date >= current_date)
                                    .order_by(Competition.event_date)
                                    .all()
                                )
                                if not getattr(c, "is_cancelled", False)
                                and getattr(c, "name", None) != ADMIN_TEST_GP_NAME
                                and (
                                    getattr(c, "series_id", None) == s.id
                                    or (
                                        getattr(c, "event_date", None) is not None
                                        and c.event_date.year == series_year
                                    )
                                )
                            ),
                            None,
                        )
            except Exception:
                under_construction = True

        # Playable/active for UI: not past end_date, and either inside the window
        # or already has an upcoming race (so preseason tippa works — e.g. WSX before R01).
        if under_construction:
            is_currently_active = True
        elif not simulation_active:
            if s.end_date and current_date > s.end_date and next_race is None:
                is_currently_active = False
            elif s.end_date and current_date > s.end_date:
                # Season window over — only stay "active" if this series_id still has races
                is_currently_active = False
            elif next_race is not None:
                is_currently_active = True
            elif s.start_date and s.end_date:
                is_currently_active = s.start_date <= current_date <= s.end_date
            elif s.start_date:
                is_currently_active = current_date >= s.start_date
            else:
                is_currently_active = bool(s.is_active)
        else:
            is_currently_active = bool(s.is_active)

        days_until_next_race = None
        if next_race and next_race.event_date:
            days_until_next_race = (next_race.event_date - current_date).days

        days_until_start = None
        if s.start_date:
            days_until_start = (s.start_date - current_date).days

        picks_opens_on = None
        picks_preseason = False
        days_until_picks_open = None
        if next_race is not None:
            try:
                picks_preseason = is_picks_preseason_locked(next_race)
                opens = picks_preseason_opens_on(next_race)
                if opens:
                    picks_opens_on = opens.isoformat()
                    days_until_picks_open = (opens - current_date).days
            except Exception:
                picks_preseason = False

        # Finished seasons without upcoming races belong in Fantasy-arkiv, not Välj Serie.
        # Exception: MXoN stays selectable so the home topplista remains after archive.
        if (
            not under_construction
            and not is_currently_active
            and next_race is None
            and s.end_date
            and current_date > s.end_date
            and series_code != "MXON"
        ):
            continue

        series_data.append(
            {
                "id": s.id,
                "name": s.name,
                "year": series_year or None,
                "series_code": series_code,
                "is_active": is_currently_active,
                "under_construction": under_construction,
                "start_date": s.start_date.isoformat() if s.start_date else None,
                "end_date": s.end_date.isoformat() if s.end_date else None,
                "days_until_start": days_until_start,
                "days_until_next_race": days_until_next_race,
                "picks_preseason_locked": picks_preseason,
                "picks_opens_on": picks_opens_on,
                "days_until_picks_open": days_until_picks_open,
                "next_race": (
                    {
                        "id": next_race.id,
                        "name": next_race.name,
                        "date": next_race.event_date.isoformat(),
                    }
                    if next_race
                    else None
                ),
            }
        )

    def _series_family_key(item: dict) -> str:
        name = (item.get("name") or "").strip()
        if name in ("MXON", "MXoN"):
            return "MXON"
        return name

    def _prefer_series_card(a: dict, b: dict) -> dict:
        """One card per family: current season over finished, sooner next race over later."""
        if bool(a.get("under_construction")) != bool(b.get("under_construction")):
            return b if a.get("under_construction") else a
        if bool(a.get("is_active")) != bool(b.get("is_active")):
            return a if a.get("is_active") else b
        da = a.get("days_until_next_race")
        db_ = b.get("days_until_next_race")
        a_has = isinstance(da, int) and da >= 0
        b_has = isinstance(db_, int) and db_ >= 0
        if a_has and b_has and da != db_:
            return a if da < db_ else b
        if a_has != b_has:
            return a if a_has else b
        ya = int(a.get("year") or 0)
        yb = int(b.get("year") or 0)
        if ya != yb:
            # Prefer the season that hasn't started yet over a finished twin,
            # else the higher (upcoming) year.
            return a if ya > yb else b
        return a

    # Deduplicate SX/MX/SMX (and peers) when both 2026 and 2027 rows exist
    best_by_family: dict[str, dict] = {}
    for item in series_data:
        key = _series_family_key(item)
        prev = best_by_family.get(key)
        best_by_family[key] = item if prev is None else _prefer_series_card(prev, item)
    series_data = list(best_by_family.values())

    # Sort: soonest next race first; under-construction teasers next; finished last.
    def _series_sort_key(item: dict):
        d = item.get("days_until_next_race")
        name = item.get("name") or ""
        tie = series_order.get(name, 999)
        if isinstance(d, int) and d >= 0:
            return (0, d, tie)
        if item.get("is_active"):
            return (1, 0, tie)
        until_start = item.get("days_until_start")
        if isinstance(until_start, int) and until_start > 0:
            return (2, until_start, tie)
        if item.get("under_construction"):
            return (3, 0, tie)
        return (4, 9999, tie)

    series_data.sort(key=_series_sort_key)

    _SERIES_STATUS_CACHE = (now + _SERIES_STATUS_CACHE_TTL, series_data)
    return series_data


@app.route("/api/series_status")
def series_status():
    """Get status of all series for user interface"""
    try:
        return jsonify(build_series_status_list())
    except Exception as e:
        import traceback

        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


@app.get("/api/my_series_picks_status")
def my_series_picks_status():
    """Per-series pick completeness for the logged-in user's next race in each series."""
    uid = session.get("user_id")
    if not uid:
        return jsonify({})
    try:
        out: dict[str, dict] = {}
        for row in build_series_status_list():
            code = (row.get("series_code") or "").strip().upper()
            if not code or row.get("under_construction"):
                continue
            next_race = row.get("next_race") or {}
            comp_id = next_race.get("id")
            if not comp_id:
                continue
            comp = Competition.query.get(int(comp_id))
            if not comp or getattr(comp, "is_cancelled", False):
                continue
            status = _user_picks_status_code(int(uid), comp)
            out[code] = {
                "status": status,
                "competition_id": int(comp.id),
                "competition_name": getattr(comp, "name", None) or next_race.get("name"),
            }
        return jsonify(out)
    except Exception as e:
        import traceback

        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


@app.route("/")
def index():
    try:
        return _index_impl()
    except Exception as e:
        import traceback

        traceback.print_exc()
        print(f"index() failed (serving degraded): {e}")
        try:
            db.session.rollback()
        except Exception:
            pass
        try:
            db.engine.dispose()
        except Exception:
            pass
        try:
            return (
                render_template(
                    "index.html",
                    username=session.get("username", "Gäst"),
                    user_profile_picture=None,
                    upcoming_race=None,
                    view_picks_race=None,
                    can_view_other_picks=False,
                    upcoming_race_bg_url=None,
                    upcoming_races=[],
                    my_team=None,
                    team_riders=[],
                    season_team_count=0,
                    current_picks_450=None,
                    current_picks_250=None,
                    current_holeshot_450=None,
                    current_holeshot_250=None,
                    current_wildcard=None,
                    current_mxon_nations=None,
                    current_mxon_classes=None,
                    current_mxon_nations_by_pos=None,
                    new_bulletin_posts=0,
                    latest_post_author=None,
                    league_requests_count=0,
                    user_has_league=False,
                    picks_status="no_picks",
                    picks_locked=True,
                    home_pick_portraits={},
                    is_admin=False,
                    is_logged_in=bool(session.get("user_id")),
                    needs_email=False,
                    admin_message=None,
                    admin_message_priority=None,
                    admin_announcement_id=None,
                    user_total_points=0,
                    races_participated=0,
                    best_position=None,
                    sx_season_wrap=None,
                    series_status_data=[],
                    rider_spotlight_data=None,
                    power_ranking_data=None,
                    pit_pass_race_name="MX Fantasy League",
                    pit_pass_next_url=url_for("index"),
                    pit_pass_peek_key="mx_pit_pass_peek_home",
                    pit_pass_auto_show=True,
                    pit_pass_start_hidden=False,
                    pit_pass_guard_selectors=[],
                    pit_pass_initial_mode="login",
                    invite_share=None,
                    picks_cta_race_label=None,
                ),
                200,
            )
        except Exception as e2:
            print(f"index() degraded render failed: {e2}")
            return (
                "<!DOCTYPE html><html><head><meta charset='utf-8'>"
                "<meta http-equiv='refresh' content='2'>"
                "<title>MX Fantasy</title></head><body style='background:#141c2c;color:#e2e8f0;"
                "font-family:system-ui;padding:2rem;text-align:center'>"
                "<h1>MX Fantasy League</h1>"
                "<p>Sidan laddas om…</p></body></html>",
                200,
                {"Content-Type": "text/html; charset=utf-8", "Retry-After": "2"},
            )


def _index_impl():
    # Validate session AFTER DB reconnect path below — cold Postgres after idle
    # used to 500 here before schema retry could dispose the pool.
    uid = None
    is_logged_in = False
    today = get_today()

    # Ensure database is initialized (only once per worker).
    # Retry once on stale Postgres connections (common after idle → intermittent 500).
    global _INDEX_SCHEMA_CHECKED
    if not _INDEX_SCHEMA_CHECKED:
        from sqlalchemy.exc import OperationalError, DBAPIError

        for _attempt in range(2):
            try:
                # Check if tables exist, if not initialize
                from sqlalchemy import inspect

                if not inspect(db.engine).has_table("competitions"):
                    print("Tables missing, reinitializing database...")
                    init_database()

                # Add classes column if missing
                try:
                    exists = db.session.execute(
                        db.text(
                            """
                            SELECT column_name FROM information_schema.columns 
                            WHERE table_name='riders' AND column_name='classes'
                            """
                        )
                    ).fetchone()
                    if not exists:
                        print("Adding classes column to riders table...")
                        db.session.execute(
                            db.text("ALTER TABLE riders ADD COLUMN classes VARCHAR(50)")
                        )
                        db.session.commit()
                        print("Classes column added successfully")
                except Exception as e:
                    print(f"Error adding classes column: {e}")
                    db.session.rollback()

                # Add admin announcement columns to global_simulation if missing
                try:
                    exists = db.session.execute(
                        db.text(
                            """
                            SELECT column_name FROM information_schema.columns 
                            WHERE table_name='global_simulation' AND column_name='admin_message'
                            """
                        )
                    ).fetchone()
                    if not exists:
                        print("Adding admin announcement columns to global_simulation table...")
                        db.session.execute(
                            db.text("ALTER TABLE global_simulation ADD COLUMN admin_message TEXT")
                        )
                        db.session.execute(
                            db.text(
                                "ALTER TABLE global_simulation ADD COLUMN admin_message_priority VARCHAR(20) DEFAULT 'info'"
                            )
                        )
                        db.session.execute(
                            db.text(
                                "ALTER TABLE global_simulation ADD COLUMN admin_message_active BOOLEAN DEFAULT FALSE"
                            )
                        )
                        db.session.commit()
                        print("Admin announcement columns added successfully")
                except Exception as e:
                    print(f"Error adding admin announcement columns: {e}")
                    db.session.rollback()

                # Check if league_requests table exists
                if not inspect(db.engine).has_table("league_requests"):
                    print("Creating league_requests table...")
                    try:
                        db.session.rollback()
                        db.session.execute(
                            db.text(
                                """
                                CREATE TABLE league_requests (
                                    id SERIAL PRIMARY KEY,
                                    league_id INTEGER NOT NULL REFERENCES leagues(id),
                                    user_id INTEGER NOT NULL REFERENCES users(id),
                                    message VARCHAR(500),
                                    status VARCHAR(20) DEFAULT 'pending',
                                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                                    processed_at TIMESTAMP,
                                    UNIQUE(league_id, user_id)
                                )
                                """
                            )
                        )
                        db.session.commit()
                        print("league_requests table created successfully")
                    except Exception as e:
                        print(f"Error creating league_requests table: {e}")
                        db.session.rollback()

                _INDEX_SCHEMA_CHECKED = True
                break
            except (OperationalError, DBAPIError) as e:
                print(f"Database check connection error (attempt {_attempt + 1}): {e}")
                try:
                    db.session.rollback()
                except Exception:
                    pass
                try:
                    db.engine.dispose()
                except Exception:
                    pass
                if _attempt == 1:
                    # Do NOT call init_database() here — seeding on a cold homepage
                    # request can exceed gunicorn timeout and cause the intermittent 500.
                    print(f"Database check error (continuing without schema init): {e}")
                    _INDEX_SCHEMA_CHECKED = True
            except Exception as e:
                print(f"Database check error: {e}")
                try:
                    db.session.rollback()
                except Exception:
                    pass
                try:
                    db.engine.dispose()
                except Exception:
                    pass
                # Avoid heavy init_database() on the request path
                _INDEX_SCHEMA_CHECKED = True
                break

    # Session user lookup after pool reconnect above
    if "user_id" in session and "username" in session:
        try:
            user = User.query.get(session["user_id"])
            if user and user.username == session["username"]:
                uid = session["user_id"]
                is_logged_in = True
            else:
                session.clear()
                uid = None
                is_logged_in = False
        except Exception as e:
            print(f"index session user lookup: {e}")
            try:
                db.session.rollback()
            except Exception:
                pass
            try:
                db.engine.dispose()
            except Exception:
                pass
            uid = None
            is_logged_in = False

    _ensure_competition_result_moto_columns()

    # Get competitions with error handling
    try:
        competitions = Competition.query.order_by(Competition.event_date).all()
    except Exception as e:
        print(f"Error getting competitions: {e}")
        try:
            db.session.rollback()
            db.engine.dispose()
            competitions = Competition.query.order_by(Competition.event_date).all()
        except Exception as e2:
            print(f"Error getting competitions (retry): {e2}")
            competitions = []    
    # Homepage default = AMA chain (SX→MX→SMX). WSX only via series-card selection.
    try:
        upcoming_race = _home_primary_competition(require_open=False)
    except Exception as e:
        print(f"index upcoming_race: {e}")
        try:
            db.session.rollback()
        except Exception:
            pass
        upcoming_race = None
    view_picks_race = upcoming_race
    
    # Get user-specific data only if logged in
    my_team = None
    team_riders = []
    user_profile_picture = None
    current_picks_450 = []
    current_picks_250 = []
    current_holeshot_450 = None
    current_holeshot_250 = None
    current_wildcard = None
    current_mxon_nations: list[dict] = []
    current_mxon_classes: dict[str, dict] = {}
    current_mxon_nations_by_pos: dict[int, dict] = {}
    home_pick_portraits: dict[str, dict[str, str]] = {}
    picks_status = "no_picks"
    picks_locked = True
    league_requests_count = 0
    user_has_league = False
    
    needs_email = False
    if is_logged_in:
        # Get season team with error handling
        try:
            _ensure_season_team_created_at_column()
            my_team = SeasonTeam.query.filter_by(user_id=uid).first()
        except Exception as e:
            print(f"Error getting season team: {e}")
            try:
                db.session.rollback()
                _ensure_season_team_created_at_column()
                my_team = SeasonTeam.query.filter_by(user_id=uid).first()
            except Exception as e2:
                print(f"Error getting season team (retry): {e2}")
                my_team = None

        # Get team riders
        if my_team:
            try:
                rs = (
                    rider_query_for_list_ui()
                    .join(SeasonTeamRider, Rider.id == SeasonTeamRider.rider_id)
                    .filter(SeasonTeamRider.season_team_id == my_team.id)
                    .order_by(Rider.class_name.desc(), Rider.price.desc())
                    .all()
                )
                team_riders = [
                    {
                        "id": r.id,
                        "name": r.name,
                        "number": r.rider_number,
                        "brand": (r.bike_brand or "").lower(),
                        "class": r.class_name,
                        "image_url": r.image_url or None,
                        "portrait_url": f"/rider_portrait/{int(r.id)}",
                    }
                    for r in rs
                ]
            except Exception as e:
                print(f"Error getting team riders: {e}")
                team_riders = []

        # Get user profile picture
        try:
            user = User.query.get(uid)
            if user and hasattr(user, 'profile_picture_url') and user.profile_picture_url:
                user_profile_picture = user.profile_picture_url
            needs_email = not (getattr(user, "email", None) or "").strip()
        except Exception as e:
            print(f"Error getting user profile picture: {e}")
            user_profile_picture = None
            needs_email = False

        # Get user's picks for upcoming race
        picks_status = "no_picks"
        picks_locked = False
        
        if upcoming_race:
            try:
                # Use the unified picks lock check function
                picks_locked = is_picks_locked(upcoming_race)

                # Use the correct competition_id for picks lookup
                competition_id_for_picks = upcoming_race.id

                if (getattr(upcoming_race, "series", None) or "").upper() == "MXON":
                    from mxon_fantasy import get_user_class_picks, get_user_nation_picks

                    current_mxon_nations = get_user_nation_picks(uid, int(competition_id_for_picks))
                    current_mxon_classes = get_user_class_picks(uid, int(competition_id_for_picks))
                    current_mxon_nations_by_pos = {
                        int(p["position"]): p
                        for p in current_mxon_nations
                        if p.get("position") is not None
                    }
                    n_ok = len(current_mxon_nations) >= 5
                    c_ok = len(current_mxon_classes) >= 3
                    if n_ok and c_ok:
                        picks_status = "has_picks"
                    elif current_mxon_nations or current_mxon_classes:
                        picks_status = "partial_picks"
                    else:
                        picks_status = "no_picks"
                else:
                    # Get race picks for both classes
                    all_race_picks = RacePick.query.filter_by(
                        user_id=uid,
                        competition_id=competition_id_for_picks
                    ).order_by(RacePick.predicted_position).all()

                    # Remove duplicates - keep only the most recent pick for each rider (highest id)
                    seen_rider_ids = {}
                    race_picks = []
                    for pick in all_race_picks:
                        if pick.rider_id not in seen_rider_ids:
                            seen_rider_ids[pick.rider_id] = pick
                            race_picks.append(pick)
                        elif pick.pick_id > seen_rider_ids[pick.rider_id].pick_id:
                            # Replace with more recent pick
                            race_picks.remove(seen_rider_ids[pick.rider_id])
                            seen_rider_ids[pick.rider_id] = pick
                            race_picks.append(pick)

                    # Sort again after deduplication
                    race_picks.sort(key=lambda p: p.predicted_position)

                    # Get holeshot picks
                    holeshot_picks = HoleshotPick.query.filter_by(
                        user_id=uid,
                        competition_id=competition_id_for_picks
                    ).all()

                    # Get wildcard pick
                    wildcard_pick = WildcardPick.query.filter_by(
                        user_id=uid,
                        competition_id=competition_id_for_picks
                    ).first()

                    pick_rider_ids = {p.rider_id for p in race_picks}
                    pick_rider_ids.update(h.rider_id for h in holeshot_picks)
                    if wildcard_pick and wildcard_pick.rider_id:
                        pick_rider_ids.add(wildcard_pick.rider_id)
                    riders_by_id = {
                        r.id: r
                        for r in rider_query_for_list_ui()
                        .filter(Rider.id.in_(pick_rider_ids))
                        .all()
                    } if pick_rider_ids else {}
                    riders_by_name = (
                        _riders_by_name_for(list(riders_by_id.values()))
                        if riders_by_id
                        else {}
                    )

                    def _remember_pick_portraits(rider: Rider) -> dict[str, str]:
                        payload = _rider_portrait_payload(
                            rider, riders_by_name=riders_by_name
                        )
                        home_pick_portraits[str(rider.id)] = payload
                        return payload

                    current_holeshot_450 = None
                    current_holeshot_250 = None
                    current_wildcard = None

                    # Check if picks are complete (all required picks must be filled)
                    is_wsx = upcoming_race.series == "WSX"

                    # Always show user's own picks (they can see their own choices)
                    seen_rider_ids_450 = set()
                    seen_rider_ids_250 = set()
                    home_wc_names = _wsx_wildcard_names_for_competition(upcoming_race)

                    # Sort picks by predicted_position to ensure correct order
                    sorted_race_picks = sorted(race_picks, key=lambda p: p.predicted_position)
                    for pick in sorted_race_picks:
                        rider = riders_by_id.get(pick.rider_id)
                        if rider:
                            portraits = _remember_pick_portraits(rider)
                            pick_data = {
                                "position": pick.predicted_position,
                                "rider_id": rider.id,
                                "rider_name": rider.name,
                                "rider_number": rider.rider_number,
                                "class": rider.class_name,
                                "portrait_url": portraits["portrait_url"],
                                "image_url": portraits["image_url"],
                                "racerx_portrait_url": portraits["racerx_portrait_url"],
                                "bike_brand": portraits["bike_brand"],
                                "is_wildcard": (rider.name or "") in home_wc_names,
                            }

                            # Separate by class (map WSX classes to display classes)
                            if rider.class_name in ("450cc", "wsx_sx1"):
                                if pick.rider_id not in seen_rider_ids_450:
                                    current_picks_450.append(pick_data)
                                    seen_rider_ids_450.add(pick.rider_id)
                            elif rider.class_name in ("250cc", "wsx_sx2"):
                                if pick.rider_id not in seen_rider_ids_250:
                                    current_picks_250.append(pick_data)
                                    seen_rider_ids_250.add(pick.rider_id)

                    # Sort the lists by position after populating
                    current_picks_450.sort(key=lambda x: x["position"])
                    current_picks_250.sort(key=lambda x: x["position"])

                    # Count race picks by class (after populating lists and removing duplicates)
                    race_picks_450_count = len(current_picks_450)
                    race_picks_250_count = len(current_picks_250)

                    # Count holeshot picks by class
                    holeshot_450 = False
                    holeshot_250 = False
                    for holeshot in holeshot_picks:
                        rider = riders_by_id.get(holeshot.rider_id)
                        if rider:
                            if rider.class_name in ("450cc", "wsx_sx1"):
                                holeshot_450 = True
                            elif rider.class_name in ("250cc", "wsx_sx2"):
                                holeshot_250 = True

                    # Check if wildcard is complete (only for non-WSX series)
                    if is_wsx:
                        wildcard_complete = True  # Not required for WSX
                    else:
                        wildcard_complete = (
                            wildcard_pick
                            and wildcard_pick.rider_id
                            and wildcard_pick.position is not None
                        )

                    # Required: 6+6 race picks, 2 holeshots, 1 wildcard (if not WSX)
                    race_picks_complete = race_picks_450_count == 6 and race_picks_250_count == 6
                    holeshot_complete = holeshot_450 and holeshot_250

                    # Only mark as "has_picks" if ALL required picks are complete
                    if race_picks_complete and holeshot_complete and wildcard_complete:
                        picks_status = "has_picks"
                    elif (
                        race_picks_450_count > 0
                        or race_picks_250_count > 0
                        or holeshot_450
                        or holeshot_250
                        or (wildcard_pick and wildcard_pick.rider_id)
                    ):
                        picks_status = "partial_picks"
                    else:
                        picks_status = "no_picks"

                    # Process holeshot picks for display
                    for holeshot in holeshot_picks:
                        rider = riders_by_id.get(holeshot.rider_id)
                        if rider:
                            portraits = _remember_pick_portraits(rider)
                            hs_data = {
                                "rider_id": rider.id,
                                "rider_name": rider.name,
                                "rider_number": rider.rider_number,
                                "class": rider.class_name,
                                "portrait_url": portraits["portrait_url"],
                                "image_url": portraits["image_url"],
                                "racerx_portrait_url": portraits["racerx_portrait_url"],
                                "bike_brand": portraits["bike_brand"],
                            }
                            if rider.class_name in ("450cc", "wsx_sx1"):
                                current_holeshot_450 = hs_data
                            elif rider.class_name in ("250cc", "wsx_sx2"):
                                current_holeshot_250 = hs_data

                    if (
                        wildcard_pick
                        and wildcard_pick.rider_id
                        and upcoming_race
                        and upcoming_race.series != "WSX"
                    ):
                        rider = riders_by_id.get(wildcard_pick.rider_id)
                        if rider:
                            portraits = _remember_pick_portraits(rider)
                            current_wildcard = {
                                "rider_id": rider.id,
                                "rider_name": rider.name,
                                "rider_number": rider.rider_number,
                                "class": rider.class_name,
                                "position": wildcard_pick.position,
                                "portrait_url": portraits["portrait_url"],
                                "image_url": portraits["image_url"],
                                "racerx_portrait_url": portraits["racerx_portrait_url"],
                                "bike_brand": portraits["bike_brand"],
                            }

            except Exception as e:
                print(f"Error getting current picks: {e}")
                current_picks_450 = []
                current_picks_250 = []

    # Check for new bulletin posts (last 24 hours)
    new_bulletin_posts = 0
    latest_post_author = None
    try:
        from datetime import timedelta
        # Use current time (datetime) instead of today (date) for accurate 24-hour calculation
        current_time = get_current_time()
        twenty_four_hours_ago = current_time - timedelta(hours=24)
        
        new_posts = BulletinPost.query.filter(
            BulletinPost.created_at >= twenty_four_hours_ago,
            BulletinPost.is_deleted == False,
            BulletinPost.parent_id == None  # Only count main posts, not replies
        ).order_by(BulletinPost.created_at.desc()).all()
        
        new_bulletin_posts = len(new_posts)
        if new_posts:
            # Get the latest post author
            latest_post = new_posts[0]
            if latest_post.user:
                # Use display_name if available, otherwise fallback to username
                # Handle case where is_admin column might not exist yet
                try:
                    latest_post_author = getattr(latest_post.user, 'display_name', None) or latest_post.user.username
                except Exception:
                    latest_post_author = latest_post.user.username
            else:
                latest_post_author = "Okänd"
    except Exception as e:
        print(f"Error checking bulletin posts: {e}")
        new_bulletin_posts = 0
        latest_post_author = None

    # Check for league join requests (for league creators)
    try:
        # Get all leagues where current user is creator
        user_leagues = League.query.filter_by(creator_id=uid).all()
        league_ids = [league.id for league in user_leagues]
        
        if league_ids:
            # Count pending requests for user's leagues
            league_requests_count = LeagueRequest.query.filter(
                LeagueRequest.league_id.in_(league_ids),
                LeagueRequest.status == 'pending'
            ).count()
        else:
            league_requests_count = 0
    except Exception as e:
        print(f"Error checking league requests: {e}")
        league_requests_count = 0

    try:
        if is_logged_in and uid is not None:
            user_has_league = (
                LeagueMembership.query.filter_by(user_id=int(uid)).first() is not None
            )
        else:
            user_has_league = False
    except Exception as e:
        print(f"Error checking league membership: {e}")
        user_has_league = False

    # Get admin announcement message (popup + Pit Lane historik)
    admin_message = None
    admin_message_priority = None
    admin_announcement_id = None
    try:
        import pit_lane_service as pls

        pls.ensure_pit_lane_tables()
        ann = AdminAnnouncement.query.filter_by(is_active=True).order_by(
            AdminAnnouncement.created_at.desc()
        ).first()
        if ann and ann.body:
            admin_message = ann.body
            admin_message_priority = ann.priority or "info"
            admin_announcement_id = ann.id
        else:
            global_sim = GlobalSimulation.query.first()
            if global_sim and global_sim.admin_message_active and global_sim.admin_message:
                admin_message = global_sim.admin_message
                admin_message_priority = global_sim.admin_message_priority or "info"
    except Exception as e:
        print(f"Error fetching admin message: {e}")
        admin_message = None

    # Calculate user statistics for stats tab (only if logged in)
    user_total_points = 0
    races_participated = 0
    best_position = None
    
    sx_season_wrap = build_sx_season_wrap_context(competitions, today)
    if sx_season_wrap:
        sx_season_wrap = {
            **sx_season_wrap,
            "recap_url": url_for(
                "sx_season_recap", year=sx_season_wrap["season_year"]
            ),
            "race_results_url": url_for("race_results_page"),
            "finished_series_url": url_for("finished_series_page"),
            "next_mx_picks_url": url_for(
                "race_picks_page", competition_id=sx_season_wrap["next_mx_id"]
            ),
        }

    if is_logged_in:
        try:
            # AMA tippa only (same as highscore) — never mix WSX/MXON into sidebar SSR
            user_total_points = _user_pick_total_points(uid)
            user_scores = (
                CompetitionScore.query.filter_by(user_id=uid)
                .filter(CompetitionScore.competition_id.isnot(None))
                .all()
            )
            races_participated = len(
                [s for s in user_scores if s.total_points and s.total_points > 0]
            )
        except Exception as e:
            print(f"Error calculating user statistics: {e}")
            user_total_points = 0
            races_participated = 0
            best_position = None


