def compute_sx_rider_podiums_for_year(year: int) -> dict:
    """AMA Supercross top 3 per klass för ett kalenderår (samma coast-/poänglogik som championship totals)."""
    from collections import defaultdict

    sx_ids = [
        c.id
        for c in Competition.query.filter(Competition.series == "SX").all()
        if c.event_date and c.event_date.year == year
    ]
    if not sx_ids:
        return {"450": [], "250_east": [], "250_west": []}

    slot_450: dict[int, float] = defaultdict(float)
    slot_east: dict[int, float] = defaultdict(float)
    slot_west: dict[int, float] = defaultdict(float)
    rider_meta: dict[int, dict] = {}

    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(Competition.id.in_(sx_ids))
        .all()
    )

    for cr, comp, rider in rows:
        pts = float(get_smx_qualification_points(cr.position))
        rider_class = getattr(cr, "class_name", None) or rider.class_name
        rid = rider.id

        if rid not in rider_meta:
            rider_meta[rid] = {
                "rider_id": rid,
                "rider_name": rider.name,
                "rider_number": rider.rider_number,
                "bike_brand": rider.bike_brand or "",
                "image_url": _resolve_rider_headshot_for_display(rider),
            }

        if rider_class == "450cc":
            slot_450[rid] += pts
        elif rider_class == "250cc":
            rc = (rider.coast_250 or "").strip().lower()
            if rc not in ("east", "west"):
                continue
            cc = (comp.coast_250 or "").strip().lower()
            if cc in ("both", "showdown"):
                if rc == "east":
                    slot_east[rid] += pts
                elif rc == "west":
                    slot_west[rid] += pts
            elif cc in ("east", "west") and cc == rc:
                if rc == "east":
                    slot_east[rid] += pts
                else:
                    slot_west[rid] += pts

    def topn(counter: dict[int, float], n: int = 3) -> list:
        items = sorted(counter.items(), key=lambda x: (-x[1], x[0]))[:n]
        out = []
        for r_id, p in items:
            row = dict(rider_meta.get(r_id, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            out.append(row)
        return out

    return {
        "450": topn(slot_450),
        "250_east": topn(slot_east),
        "250_west": topn(slot_west),
    }


def compute_wsx_rider_podiums_for_series(series_id: int) -> dict:
    """
    WSX top 3 per klass (SX1 / SX2) över alla tävlingar i en Series.
    Poäng: rider_points om satt, annars AMA/SMX-skala från position — samma som race results.
    """
    from collections import defaultdict

    comp_ids = [
        c.id
        for c in Competition.query.filter_by(
            series_id=series_id, series="WSX"
        ).all()
    ]
    if not comp_ids:
        return {"wsx_sx1": [], "wsx_sx2": []}

    slot_sx1: dict[int, float] = defaultdict(float)
    slot_sx2: dict[int, float] = defaultdict(float)
    rider_meta: dict[int, dict] = {}

    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(Competition.id.in_(comp_ids))
        .all()
    )

    for cr, _comp, rider in rows:
        if cr.rider_points is not None:
            pts = float(cr.rider_points)
        else:
            pts = float(get_smx_qualification_points(cr.position))

        rider_class = getattr(cr, "class_name", None) or rider.class_name
        rid = rider.id

        if rid not in rider_meta:
            rider_meta[rid] = {
                "rider_id": rid,
                "rider_name": rider.name,
                "rider_number": rider.rider_number,
                "bike_brand": rider.bike_brand or "",
                "image_url": _resolve_rider_headshot_for_display(rider),
            }

        if rider_class == "wsx_sx1":
            slot_sx1[rid] += pts
        elif rider_class == "wsx_sx2":
            slot_sx2[rid] += pts

    def topn(counter: dict[int, float], n: int = 3) -> list:
        items = sorted(counter.items(), key=lambda x: (-x[1], x[0]))[:n]
        out = []
        for r_id, p in items:
            row = dict(rider_meta.get(r_id, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            out.append(row)
        return out

    return {
        "wsx_sx1": topn(slot_sx1),
        "wsx_sx2": topn(slot_sx2),
    }


def fantasy_supercross_leaderboard_for_year(year: int) -> list:
    """Summerad fantasy-poäng över alla SX-tävlingar under ett år."""
    from collections import defaultdict

    sx_ids = [
        c.id
        for c in Competition.query.filter(Competition.series == "SX").all()
        if c.event_date and c.event_date.year == year
    ]
    if not sx_ids:
        return []

    agg: dict[int, int] = defaultdict(int)
    for s in CompetitionScore.query.filter(
        CompetitionScore.competition_id.in_(sx_ids)
    ).all():
        agg[s.user_id] += int(s.total_points or 0)

    ranked = sorted(agg.items(), key=lambda x: (-x[1], x[0]))
    if not ranked:
        return []

    uids = [u for u, _ in ranked]
    users = User.query.filter(User.id.in_(uids)).all()
    uid_map = {u.id: u for u in users}

    out = []
    for rank, (u_id, pts) in enumerate(ranked, start=1):
        u = uid_map.get(u_id)
        dn = getattr(u, "display_name", None) or (u.username if u else "?")
        letter = (dn.strip()[:1] or "?").upper()
        pic = getattr(u, "profile_picture_url", None) if u else None
        out.append(
            {
                "rank": rank,
                "user_id": u_id,
                "username": u.username if u else "?",
                "display_name": dn,
                "points": pts,
                "avatar_letter": letter,
                "profile_picture_url": pic,
            }
        )
    return out


def _wsx_score_agg_for_comps(comp_ids: list[int]) -> dict[int, int]:
    """Dedupe CompetitionScore per (user, competition); sum total_points per user."""
    from collections import defaultdict

    if not comp_ids:
        return {}
    by_uc: dict[tuple[int, int], CompetitionScore] = {}
    for s in CompetitionScore.query.filter(
        CompetitionScore.competition_id.in_(comp_ids)
    ).all():
        k = (int(s.user_id), int(s.competition_id))
        prev = by_uc.get(k)
        if prev is None or int(s.score_id or 0) > int(prev.score_id or 0):
            by_uc[k] = s
    agg: dict[int, int] = defaultdict(int)
    for s in by_uc.values():
        agg[int(s.user_id)] += int(s.total_points or 0)
    return dict(agg)


def calculate_wsx_leaderboard_deltas(
    *,
    year: int | None = None,
    recent_comp_ids: set[int] | None = None,
) -> list[dict]:
    """
    WSX tippa-highscore med rank-delta vs poäng *före* recent_comp_ids.
    Används av WSX-leaderboard + Raket/Ankare (aldrig AMA/SMX-poäng).
    """
    year = int(year or _active_wsx_season_year())
    comps = _wsx_competitions_for_year(year)
    season_ids = [int(c.id) for c in comps]
    if not season_ids:
        return []

    recent = {int(x) for x in (recent_comp_ids or set()) if int(x) in set(season_ids)}
    totals = _wsx_score_agg_for_comps(season_ids)
    if not totals:
        return []

    recent_pts = _wsx_score_agg_for_comps(list(recent)) if recent else {}

    rows = []
    for uid, pts in totals.items():
        recent_week = int(recent_pts.get(uid, 0))
        baseline = max(0, int(pts) - recent_week)
        rows.append(
            {
                "id": int(uid),
                "total_points": int(pts),
                "baseline_total": baseline,
                "recent_week_points": recent_week,
            }
        )

    uids = [r["id"] for r in rows]
    users = User.query.filter(User.id.in_(uids)).all()
    uid_map = {u.id: u for u in users}
    teams = {
        int(t.user_id): t.team_name
        for t in SeasonTeam.query.filter(SeasonTeam.user_id.in_(uids)).all()
    }

    current = sorted(rows, key=lambda x: _leaderboard_sort_key(x, "total_points"))
    # Första avklarade racet i säsongen: alla baseline=0 → delta blir meningslöst.
    # Låt delta=0 så Raket/Ankare faller tillbaka till ren WSX-veckopoäng.
    use_baseline = bool(recent) and any(int(r.get("baseline_total") or 0) > 0 for r in rows)
    baseline_ranking = (
        _build_rank_map(rows, "baseline_total") if use_baseline else {}
    )

    out = []
    for i, row in enumerate(current, 1):
        uid = int(row["id"])
        u = uid_map.get(uid)
        dn = getattr(u, "display_name", None) or (u.username if u else "?")
        baseline_rank = baseline_ranking.get(str(uid))
        if use_baseline and baseline_rank is not None and baseline_rank > 0:
            delta = i - int(baseline_rank)
        else:
            delta = 0
        out.append(
            {
                "user_id": uid,
                "username": u.username if u else "?",
                "display_name": dn,
                "team_name": teams.get(uid),
                "rank": i,
                "delta": delta,
                "total_points": int(row["total_points"]),
            }
        )
    return out


def fantasy_wsx_leaderboard_for_year(year: int = 2026) -> list:
    """Fantasy tippa-highscore for one WSX season only (never mixes with AMA/SMX)."""
    from datetime import datetime, timedelta

    today_utc = datetime.utcnow().date()
    since = (datetime.utcnow() - timedelta(days=90)).date()
    comps = _wsx_competitions_for_year(int(year))
    window_ids = [
        int(c.id)
        for c in comps
        if c.event_date and since <= c.event_date <= today_utc
    ]
    recent_with_results: set[int] = set()
    if window_ids:
        recent_with_results = {
            int(row[0])
            for row in db.session.query(CompetitionResult.competition_id)
            .filter(CompetitionResult.competition_id.in_(window_ids))
            .distinct()
            .all()
        }
    return calculate_wsx_leaderboard_deltas(
        year=int(year),
        recent_comp_ids=recent_with_results,
    )


