@app.get("/supercross/sasong/<int:year>")
def sx_season_recap(year: int):
    """Säsongssammanfattning: AMA-pall + fantasy-leaderboard enbart Supercross."""
    today = get_today()
    sx_comps = [
        c
        for c in Competition.query.filter(Competition.series == "SX").all()
        if c.event_date and c.event_date.year == year
    ]
    if not sx_comps:
        flash("Ingen Supercross hittades för det året.", "warning")
        return redirect(url_for("index"))
    last_sx = max(sx_comps, key=lambda c: c.event_date)
    if not CompetitionResult.query.filter_by(competition_id=last_sx.id).first():
        flash("Sista rundan saknar resultat än — kom tillbaka snart.", "info")
        return redirect(url_for("index"))

    rider_podiums = compute_sx_rider_podiums_for_year(year)
    fantasy_leaderboard = fantasy_supercross_leaderboard_for_year(year)

    uid = session.get("user_id")
    is_logged_in = uid is not None
    current_username = session.get("username")

    competitions = Competition.query.order_by(Competition.event_date).all()
    wrap = build_sx_season_wrap_context(competitions, today)
    footer_links = None
    if wrap and wrap.get("season_year") == year:
        footer_links = {
            "race_results_url": url_for("race_results_page"),
            "finished_series_url": url_for("finished_series_page"),
            "next_mx_picks_url": url_for(
                "race_picks_page", competition_id=wrap["next_mx_id"]
            ),
            "next_mx_name": wrap["next_mx_name"],
            "next_mx_date": wrap["next_mx_date"],
        }
    if not footer_links:
        future_mx = [
            c
            for c in Competition.query.filter(Competition.series == "MX").all()
            if c.event_date and c.event_date > today
        ]
        if future_mx:
            nx = min(future_mx, key=lambda c: c.event_date)
            footer_links = {
                "race_results_url": url_for("race_results_page"),
                "finished_series_url": url_for("finished_series_page"),
                "next_mx_picks_url": url_for("race_picks_page", competition_id=nx.id),
                "next_mx_name": nx.name,
                "next_mx_date": nx.event_date,
            }

    return render_template(
        "sx_season_recap.html",
        year=year,
        last_race_name=last_sx.name,
        last_race_date=last_sx.event_date,
        sx_race_count=len(sx_comps),
        rider_podiums=rider_podiums,
        fantasy_leaderboard=fantasy_leaderboard,
        is_logged_in=is_logged_in,
        current_username=current_username,
        current_user_id=uid,
        footer_links=footer_links,
    )




@app.route("/leagues")
def leagues_page():
    if "user_id" not in session:
        return _redirect_to_login()

    uid = session["user_id"]

    # Ensure database is initialized
    try:
        from sqlalchemy import inspect
        if not inspect(db.engine).has_table('leagues'):
            print("Tables missing, reinitializing database...")
            init_database()
    except Exception as e:
        print(f"Database check error: {e}")
        init_database()

    try:
        _ensure_league_membership_unique()
        my_leagues = (
            League.query.join(LeagueMembership)
            .filter(LeagueMembership.user_id == uid)
            .distinct()
            .all()
        )
    except Exception as e:
        print(f"Error getting leagues: {e}")
        my_leagues = []

    public_leagues = db.session.query(
        League,
        db.func.count(db.func.distinct(LeagueMembership.user_id)).label('member_count')
    ).outerjoin(LeagueMembership).filter(
        League.is_public == True
    ).group_by(League.id).order_by(
        League.total_points.desc(),
        League.created_at.desc()
    ).all()

    user_league_ids = [
        lid[0] for lid in db.session.query(LeagueMembership.league_id).filter(
            LeagueMembership.user_id == uid
        ).distinct().all()
    ]
    pending_league_ids = [
        rid[0] for rid in db.session.query(LeagueRequest.league_id).filter(
            LeagueRequest.user_id == uid,
            LeagueRequest.status == 'pending'
        ).all()
    ]

    league_leaderboard = []
    try:
        leagues_with_members = db.session.query(
            League,
            db.func.count(LeagueMembership.user_id).label('member_count')
        ).select_from(League).outerjoin(
            LeagueMembership, League.id == LeagueMembership.league_id
        ).group_by(League.id).order_by(
            League.total_points.desc(),
            League.created_at.desc()
        ).all()
        for row in leagues_with_members:
            league = row[0]
            league_leaderboard.append({
                'id': league.id,
                'name': league.name,
                'member_count': row[1],
                'total_points': league.total_points or 0,
                'is_public': getattr(league, 'is_public', True),
            })
    except Exception as e:
        print(f"Error loading league leaderboard: {e}")

    initial_tab = (request.args.get("tab") or "mine").strip().lower()
    if initial_tab not in ("mine", "create", "join", "explore", "leaderboard"):
        initial_tab = "mine"

    my_league_cards = []
    for league in my_leagues:
        summary = _league_summary_for_user(league.id, uid)
        my_league_cards.append({"league": league, **summary})

    return render_template(
        "leagues.html",
        my_leagues=my_leagues,
        my_league_cards=my_league_cards,
        username=session.get("username", "Gäst"),
        is_logged_in=True,
        public_leagues=public_leagues,
        user_league_ids=user_league_ids,
        pending_league_ids=pending_league_ids,
        league_leaderboard=league_leaderboard,
        initial_tab=initial_tab,
    )


