def _user_pick_total_points(user_id: int) -> int:
    """Total pick points (AMA only), deduped per competition — tippa + transfer penalties only."""
    return int(sum(s.total_points or 0 for s in _user_ama_competition_scores(user_id)))


def _user_ama_competition_scores(user_id: int) -> list:
    """Live AMA tippa CompetitionScore rows for user (one per competition / NULL penalty)."""
    all_scores = (
        db.session.query(CompetitionScore)
        .outerjoin(Competition, Competition.id == CompetitionScore.competition_id)
        .filter(CompetitionScore.user_id == int(user_id))
        .filter(ama_competition_clause())
        .all()
    )
    scores_by_comp: dict[int | None, CompetitionScore] = {}
    for score in all_scores:
        comp_id = score.competition_id
        prev = scores_by_comp.get(comp_id)
        if prev is None or score.score_id > prev.score_id:
            scores_by_comp[comp_id] = score
    return list(scores_by_comp.values())


def _user_season_team_points(user_id: int) -> int:
    """SeasonTeam.total_points for user (0 if no team)."""
    team = SeasonTeam.query.filter_by(user_id=user_id).first()
    return int(team.total_points or 0) if team else 0


def _user_highscore_total(user_id: int) -> tuple[int, int, int]:
    """AMA highscore: tippa, season-team, and combined total (flag-aware).

    Returns (tippa_points, team_points, total_for_leaderboard).
    """
    tippa = _user_pick_total_points(user_id)
    team = _user_season_team_points(user_id)
    try:
        from season_team_combined import season_team_combined_live

        combined = season_team_combined_live()
    except Exception:
        combined = False
    total = tippa + team if combined else tippa
    return tippa, team, int(total)


def _user_avatar_fields(user: User | None) -> dict[str, str | int | bool | None]:
    """Profile picture + fallback initial for avatar UI."""
    if not user:
        return {
            "user_id": None,
            "profile_picture_url": None,
            "avatar_letter": "?",
            "has_profile_image": False,
        }
    dn = getattr(user, "display_name", None) or user.username or "?"
    pic = getattr(user, "profile_picture_url", None)
    has_pic = bool(pic and not str(pic).startswith("uploaded_"))
    return {
        "user_id": int(user.id),
        "profile_picture_url": pic,
        "avatar_letter": (dn.strip()[:1] or "?").upper(),
        "has_profile_image": has_pic,
    }


def _league_member_standings(league_id: int) -> list[dict]:
    """Individual race-pick standings for league members (excludes WSX)."""
    member_user_ids = [
        m.user_id
        for m in LeagueMembership.query.filter_by(league_id=league_id).all()
    ]
    if not member_user_ids:
        return []

    members = User.query.filter(User.id.in_(member_user_ids)).all()
    scored = [
        {
            "user_id": u.id,
            "username": u.username,
            "display_name": getattr(u, "display_name", None) or u.username,
            "total_points": _user_pick_total_points(u.id),
            **_user_avatar_fields(u),
        }
        for u in members
    ]
    scored.sort(key=lambda x: x["total_points"], reverse=True)

    standings: list[dict] = []
    for rank, row in enumerate(scored, start=1):
        standings.append({"rank": rank, **row})
    return standings


def _league_summary_for_user(league_id: int, user_id: int) -> dict:
    """Standings + current user's rank/gap for a league."""
    member_count = LeagueMembership.query.filter_by(league_id=league_id).count()
    standings = _league_member_standings(league_id)
    for s in standings:
        s["is_me"] = s["user_id"] == user_id

    my_entry = next((s for s in standings if s["user_id"] == user_id), None)
    my_rank = my_entry["rank"] if my_entry else None
    my_points = my_entry["total_points"] if my_entry else 0
    gap_above = gap_below = None
    rival_name = leader_name = None
    rival_user_id = chaser_name = chaser_user_id = None

    if my_entry and my_rank:
        if my_rank > 1:
            above = standings[my_rank - 2]
            gap_above = int(above["total_points"] - my_points)
            rival_name = above["display_name"]
            rival_user_id = above["user_id"]
        if my_rank < len(standings):
            below = standings[my_rank]
            gap_below = int(my_points - below["total_points"])
            chaser_name = below["display_name"]
            chaser_user_id = below["user_id"]
    if standings:
        leader_name = standings[0]["display_name"]

    return {
        "standings": standings,
        "member_count": member_count,
        "my_rank": my_rank,
        "my_points": my_points,
        "gap_above": gap_above,
        "gap_below": gap_below,
        "rival_name": rival_name,
        "rival_user_id": rival_user_id,
        "chaser_name": chaser_name,
        "chaser_user_id": chaser_user_id,
        "leader_name": leader_name,
    }


def _short_competition_label(comp: Competition, max_len: int = 14) -> str:
    """Compact label for race matrix column headers."""
    name = (comp.name or "").strip()
    if not name:
        return f"#{comp.id}"
    parts = name.replace("—", " ").replace("-", " ").split()
    if len(parts) >= 2:
        short = " ".join(parts[-2:])
    else:
        short = name
    if len(short) > max_len:
        return short[: max_len - 1] + "…"
    return short


def _completed_competitions_for_league(limit: int | None = None) -> list[Competition]:
    """Non-WSX competitions with results, newest first."""
    ids_with_results = [
        row[0] for row in db.session.query(CompetitionResult.competition_id).distinct().all()
    ]
    if not ids_with_results:
        return []
    q = (
        Competition.query.filter(Competition.id.in_(ids_with_results))
        .filter(ama_competition_clause())
        .order_by(Competition.event_date.desc().nullslast(), Competition.id.desc())
    )
    if limit:
        q = q.limit(limit)
    return q.all()


def _league_race_matrix(league_id: int, race_limit: int = 8) -> dict:
    """Members × recent races grid with per-cell points."""
    standings = _league_member_standings(league_id)
    races = _completed_competitions_for_league(limit=race_limit)
    member_ids = [s["user_id"] for s in standings]
    comp_ids = [c.id for c in races]

    score_map: dict[tuple[int, int], int] = {}
    if comp_ids and member_ids:
        for sc in (
            CompetitionScore.query.filter(
                CompetitionScore.user_id.in_(member_ids),
                CompetitionScore.competition_id.in_(comp_ids),
            )
            .order_by(CompetitionScore.score_id.desc())
            .all()
        ):
            key = (sc.user_id, sc.competition_id)
            if key not in score_map:
                score_map[key] = int(sc.total_points or 0)

    col_best: dict[int, int | None] = {}
    for comp in races:
        pts = [score_map.get((uid, comp.id)) for uid in member_ids]
        valid = [p for p in pts if p is not None]
        col_best[comp.id] = max(valid) if valid else None

    race_cols = []
    for comp in races:
        race_cols.append({
            "id": comp.id,
            "name": comp.name,
            "short_label": _short_competition_label(comp),
            "series": comp.series or "",
            "date": comp.event_date.strftime("%d/%m") if comp.event_date else "",
            "date_full": comp.event_date.strftime("%Y-%m-%d") if comp.event_date else "",
        })

    rows = []
    for s in standings:
        cells = []
        for comp in races:
            pts = score_map.get((s["user_id"], comp.id))
            best = col_best.get(comp.id)
            cells.append({
                "competition_id": comp.id,
                "points": pts,
                "is_best": pts is not None and best is not None and pts == best,
            })
        rows.append({**s, "cells": cells})

    return {"races": race_cols, "rows": rows}


def _upcoming_competitions(limit: int = 4) -> list[dict]:
    """Next races without results (non-WSX), as compact card data."""
    ids_with_results = {
        row[0] for row in db.session.query(CompetitionResult.competition_id).distinct().all()
    }
    upcoming = (
        Competition.query.filter(
            ama_competition_clause()
        )
        .order_by(Competition.event_date.asc().nullslast(), Competition.id.asc())
        .all()
    )
    cards = []
    for comp in upcoming:
        if getattr(comp, "is_cancelled", False):
            continue
        if comp.id in ids_with_results:
            continue
        cards.append({
            "id": comp.id,
            "name": comp.name,
            "series": comp.series or "",
            "event_date": comp.event_date.strftime("%Y-%m-%d") if comp.event_date else "",
            "date_short": comp.event_date.strftime("%d %b") if comp.event_date else "TBA",
            "coast_250": getattr(comp, "coast_250", None),
            "is_triple_crown": bool(getattr(comp, "is_triple_crown", False)),
        })
        if len(cards) >= limit:
            break
    return cards


def _user_competition_points(user_id: int, competition_id: int) -> int | None:
    """Points for one competition (latest score row if duplicates)."""
    score = (
        CompetitionScore.query.filter_by(
            user_id=user_id, competition_id=competition_id
        )
        .order_by(CompetitionScore.score_id.desc())
        .first()
    )
    if not score or score.total_points is None:
        return None
    return int(score.total_points)


def _assess_users_picks_on_comp(user_ids: list[int], comp: Competition) -> dict[int, str]:
    """Map user_id -> 'complete' | 'partial' | 'none'."""
    if not user_ids:
        return {}
    series_u = (comp.series or "").strip().upper()
    comp_id = int(comp.id)

    # MXoN tippa: 5 nations + 3 class winners (not AMA RacePick 6+6).
    if series_u == "MXON":
        nation_counts = dict(
            db.session.query(MxonNationPick.user_id, db.func.count(MxonNationPick.id))
            .filter(
                MxonNationPick.competition_id == comp_id,
                MxonNationPick.user_id.in_(user_ids),
            )
            .group_by(MxonNationPick.user_id)
            .all()
        )
        class_counts = dict(
            db.session.query(MxonClassPick.user_id, db.func.count(MxonClassPick.id))
            .filter(
                MxonClassPick.competition_id == comp_id,
                MxonClassPick.user_id.in_(user_ids),
            )
            .group_by(MxonClassPick.user_id)
            .all()
        )
        result: dict[int, str] = {}
        for uid in user_ids:
            n = int(nation_counts.get(uid, 0) or 0)
            c = int(class_counts.get(uid, 0) or 0)
            if n >= 5 and c >= 3:
                result[uid] = "complete"
            elif n > 0 or c > 0:
                result[uid] = "partial"
            else:
                result[uid] = "none"
        return result

    is_wsx = series_u == "WSX"
    is_mxgp = series_u == "MXGP"
    class_450 = "wsx_sx1" if is_wsx else ("mxgp" if is_mxgp else "450cc")
    class_250 = "wsx_sx2" if is_wsx else ("mx2" if is_mxgp else "250cc")

    race_picks = RacePick.query.filter(
        RacePick.competition_id == comp_id,
        RacePick.user_id.in_(user_ids),
    ).all()
    holeshots = HoleshotPick.query.filter(
        HoleshotPick.competition_id == comp_id,
        HoleshotPick.user_id.in_(user_ids),
    ).all()
    wildcards = {
        wc.user_id: wc
        for wc in WildcardPick.query.filter(
            WildcardPick.competition_id == comp_id,
            WildcardPick.user_id.in_(user_ids),
        ).all()
    }
    qual_by_user: dict[int, set[str]] = {}
    if is_mxgp:
        for qp in QualifyingPick.query.filter(
            QualifyingPick.competition_id == comp_id,
            QualifyingPick.user_id.in_(user_ids),
        ).all():
            if qp.rider_id:
                qual_by_user.setdefault(int(qp.user_id), set()).add(
                    (qp.class_name or "").strip().lower()
                )

    rider_ids = {p.rider_id for p in race_picks}
    rider_ids.update(h.rider_id for h in holeshots)
    riders_by_id = (
        {r.id: r for r in Rider.query.filter(Rider.id.in_(rider_ids)).all()}
        if rider_ids
        else {}
    )

    race_by_user: dict[int, dict[int, RacePick]] = {}
    for pick in race_picks:
        uid = int(pick.user_id)
        rid = int(pick.rider_id)
        bucket = race_by_user.setdefault(uid, {})
        if rid not in bucket or pick.pick_id > bucket[rid].pick_id:
            bucket[rid] = pick

    holeshot_by_user: dict[int, dict[str, bool]] = {}
    for hs in holeshots:
        uid = int(hs.user_id)
        rider = riders_by_id.get(hs.rider_id)
        if not rider:
            continue
        cls = (rider.class_name or "").strip().lower()
        flags = holeshot_by_user.setdefault(uid, {class_450: False, class_250: False})
        if cls in (class_450, "450cc", "wsx_sx1", "mxgp"):
            flags[class_450] = True
        elif cls in (class_250, "250cc", "wsx_sx2", "mx2"):
            flags[class_250] = True

    result = {}
    for uid in user_ids:
        picks_map = race_by_user.get(uid, {})
        n450 = n250 = 0
        for pick in picks_map.values():
            rider = riders_by_id.get(pick.rider_id)
            if not rider:
                continue
            cls = (rider.class_name or "").strip().lower()
            if cls in (class_450, "450cc", "wsx_sx1", "mxgp"):
                n450 += 1
            elif cls in (class_250, "250cc", "wsx_sx2", "mx2"):
                n250 += 1
        hs_flags = holeshot_by_user.get(uid, {class_450: False, class_250: False})
        wc = wildcards.get(uid)
        # Tippa-only series (WSX / MXGP): no wildcard required.
        wildcard_complete = True if (is_wsx or is_mxgp) else bool(
            wc and wc.rider_id and wc.position is not None
        )
        qual_ok = True
        if is_mxgp:
            qset = qual_by_user.get(uid, set())
            qual_ok = "mxgp" in qset and "mx2" in qset
        race_complete = n450 == 6 and n250 == 6
        holeshot_complete = hs_flags[class_450] and hs_flags[class_250]
        started = bool(
            n450
            or n250
            or hs_flags[class_450]
            or hs_flags[class_250]
            or (wc and (wc.rider_id or wc.position))
            or (is_mxgp and qual_by_user.get(uid))
        )
        if race_complete and holeshot_complete and wildcard_complete and qual_ok:
            result[uid] = "complete"
        elif started:
            result[uid] = "partial"
        else:
            result[uid] = "none"
    return result


def _league_picks_pulse(league_id: int, viewer_id: int) -> dict | None:
    """Who in the league has submitted picks for the next open race."""
    comp = _next_open_picks_competition()
    if not comp or (comp.series or "") == "WSX":
        return None

    member_rows = (
        db.session.query(User)
        .join(LeagueMembership, User.id == LeagueMembership.user_id)
        .filter(LeagueMembership.league_id == league_id)
        .all()
    )
    if not member_rows:
        return None

    member_ids = [int(r.id) for r in member_rows]
    status_map = _assess_users_picks_on_comp(member_ids, comp)

    def _member_row(u: User) -> dict:
        uid = int(u.id)
        return {
            "user_id": uid,
            "display_name": u.display_name or u.username,
            "is_me": uid == viewer_id,
            "status": status_map.get(uid, "none"),
            **_user_avatar_fields(u),
        }

    members = [_member_row(u) for u in member_rows]
    complete = [m for m in members if m["status"] == "complete"]
    partial = [m for m in members if m["status"] == "partial"]
    waiting = [m for m in members if m["status"] == "none"]

    hours_left = None
    deadline_display = None
    try:
        sched = _competition_race_schedule(comp)
        deadline_display = sched.get("pick_deadline_display")
        deadline_utc = sched.get("deadline_utc")
        if deadline_utc:
            now = get_current_time()
            if getattr(now, "tzinfo", None):
                now = now.replace(tzinfo=None)
            delta = deadline_utc - now
            hours_left = max(0, int(delta.total_seconds() // 3600))
    except Exception:
        pass

    viewer_status = status_map.get(viewer_id, "none")
    return {
        "competition_id": comp.id,
        "name": comp.name,
        "short_label": _short_competition_label(comp, max_len=22),
        "picks_url": (
            url_for("mxon_picks_page", competition_id=comp.id)
            if (comp.series or "").upper() == "MXON"
            else url_for("race_picks_page", competition_id=comp.id)
        ),
        "complete_count": len(complete),
        "partial_count": len(partial),
        "waiting_count": len(waiting),
        "member_count": len(members),
        "complete": complete,
        "partial": partial,
        "waiting": waiting,
        "deadline_display": deadline_display,
        "hours_left": hours_left,
        "viewer_status": viewer_status,
        "viewer_needs_picks": viewer_status != "complete",
    }


def _pick_points_map_from_detail(detail: dict) -> dict[str, dict]:
    """Rider name -> pick row from race results detail."""
    out: dict[str, dict] = {}
    sections = (detail or {}).get("sections") or {}
    for key in ("picks_450", "picks_250"):
        for row in sections.get(key) or []:
            if row.get("kind") == "pick" and row.get("rider_name"):
                out[str(row["rider_name"])] = row
    return out


def _rival_pick_highlights(
    user_id: int,
    rival_id: int,
    rival_name: str,
    competition_id: int,
    *,
    limit: int = 3,
) -> list[str]:
    """Biggest pick swings where rival outscored you on the same race."""
    try:
        me_detail = _build_race_results_detail(user_id, competition_id, dedupe_picks=True)
        rival_detail = _build_race_results_detail(rival_id, competition_id, dedupe_picks=True)
    except Exception:
        return []

    me_map = _pick_points_map_from_detail(me_detail)
    rival_map = _pick_points_map_from_detail(rival_detail)
    swings: list[tuple[int, str, int, int]] = []

    for rider in set(me_map) | set(rival_map):
        mp = int(me_map.get(rider, {}).get("points") or 0)
        rp = int(rival_map.get(rider, {}).get("points") or 0)
        diff = rp - mp
        if diff > 0:
            swings.append((diff, rider, mp, rp))

    swings.sort(key=lambda x: (-x[0], x[1]))
    lines = []
    for diff, rider, mp, rp in swings[:limit]:
        if mp == 0 and rp >= 20:
            lines.append(f"{rival_name} hade perfekt på {rider} (+{rp}p)")
        else:
            lines.append(f"{rival_name} +{diff}p på {rider} ({rp} vs {mp}p)")
    return lines


def _league_h2h(user_id: int, other_id: int, race_limit: int = 20) -> dict:
    """Race-by-race wins between two league members (by competition score)."""
    races = _completed_competitions_for_league(limit=race_limit)
    me_wins = rival_wins = ties = 0
    for comp in races:
        my_pts = _user_competition_points(user_id, comp.id)
        other_pts = _user_competition_points(other_id, comp.id)
        if my_pts is None and other_pts is None:
            continue
        my_pts = my_pts or 0
        other_pts = other_pts or 0
        if my_pts > other_pts:
            me_wins += 1
        elif other_pts > my_pts:
            rival_wins += 1
        else:
            ties += 1
    return {"me": me_wins, "rival": rival_wins, "ties": ties, "races": me_wins + rival_wins + ties}


def _league_rival_card(league_id: int, user_id: int, summary: dict) -> dict | None:
    """Rival / chaser comparison for the league detail page."""
    my_rank = summary.get("my_rank")
    if not my_rank:
        return None

    if my_rank > 1 and summary.get("rival_user_id"):
        opp_id = summary["rival_user_id"]
        opp_name = summary["rival_name"]
        opp_rank = my_rank - 1
        gap = summary.get("gap_above") or 0
        role = "rival"
    elif summary.get("chaser_user_id"):
        opp_id = summary["chaser_user_id"]
        opp_name = summary["chaser_name"]
        opp_rank = my_rank + 1
        gap = summary.get("gap_below") or 0
        role = "chaser"
    else:
        return None

    last_races = _completed_competitions_for_league(limit=1)
    last_race_block = None
    pick_highlights: list[str] = []

    if last_races:
        comp = last_races[0]
        my_pts = _user_competition_points(user_id, comp.id) or 0
        opp_pts = _user_competition_points(opp_id, comp.id) or 0
        last_race_block = {
            "competition_id": comp.id,
            "name": comp.name,
            "short_label": _short_competition_label(comp),
            "my_points": my_pts,
            "opp_points": opp_pts,
            "point_diff": my_pts - opp_pts,
        }
        if role == "rival" and opp_pts > my_pts:
            pick_highlights = _rival_pick_highlights(
                user_id, opp_id, opp_name, comp.id, limit=3
            )
        elif role == "chaser" and my_pts > opp_pts:
            pick_highlights = _rival_pick_highlights(
                opp_id, user_id, opp_name, comp.id, limit=2
            )

    h2h = _league_h2h(user_id, opp_id)
    opp_user = User.query.get(opp_id)
    viewer_user = User.query.get(user_id)
    return {
        "role": role,
        "opp_user_id": opp_id,
        "opp_name": opp_name,
        "opp_rank": opp_rank,
        "gap_points": gap,
        "h2h": h2h,
        "last_race": last_race_block,
        "pick_highlights": pick_highlights,
        "opp_avatar": _user_avatar_fields(opp_user),
        "viewer_avatar": _user_avatar_fields(viewer_user),
    }


def _league_last_race_digest(league_id: int, user_id: int, summary: dict) -> dict | None:
    """Post-race story: how the latest race shook up the league."""
    races = _completed_competitions_for_league(limit=1)
    if not races:
        return None

    comp = races[0]
    member_rows = (
        db.session.query(User)
        .join(LeagueMembership, User.id == LeagueMembership.user_id)
        .filter(LeagueMembership.league_id == league_id)
        .all()
    )
    uid_map = {int(u.id): u for u in member_rows}
    race_scores = []
    for u in member_rows:
        pts = _user_competition_points(int(u.id), comp.id)
        if pts is not None:
            race_scores.append({
                "user_id": int(u.id),
                "display_name": (u.display_name or u.username),
                "points": pts,
                **_user_avatar_fields(u),
            })
    if not race_scores:
        return None

    race_scores.sort(key=lambda x: (-x["points"], x["display_name"].lower()))
    for i, row in enumerate(race_scores, start=1):
        row["race_rank"] = i

    my_row = next((r for r in race_scores if r["user_id"] == user_id), None)
    winner = race_scores[0]
    winner_user = uid_map.get(winner["user_id"])
    highlights: list[str] = []

    if my_row:
        if my_row["race_rank"] == 1:
            highlights.append("Du vann racet i ligan 🏆")
        elif winner["user_id"] != user_id:
            gap = winner["points"] - my_row["points"]
            highlights.append(
                f"{winner['display_name']} vann liga-racet (+{gap}p mer än dig)"
            )

        rival_id = summary.get("rival_user_id")
        if rival_id and summary.get("my_rank", 0) > 1:
            rival_row = next((r for r in race_scores if r["user_id"] == rival_id), None)
            if rival_row:
                diff = my_row["points"] - rival_row["points"]
                rname = summary.get("rival_name") or rival_row["display_name"]
                if diff > 0:
                    highlights.append(f"+{diff}p före {rname} detta race")
                elif diff < 0:
                    highlights.append(f"{rname} slog dig med +{-diff}p detta race")

        try:
            detail = _build_race_results_detail(user_id, comp.id, dedupe_picks=True)
            secs = (detail or {}).get("sections") or {}
            perfects = [
                r["rider_name"]
                for r in (secs.get("picks_450") or []) + (secs.get("picks_250") or [])
                if r.get("status") == "perfect"
            ]
            if perfects:
                highlights.append(
                    f"Perfekt pick: {perfects[0]}"
                    + (f" (+{len(perfects)-1} till)" if len(perfects) > 1 else "")
                )
            hs_pts = int((detail.get("summary") or {}).get("holeshot_points") or 0)
            if hs_pts >= 20:
                highlights.append(f"Full holeshot-träff (+{hs_pts}p)")
        except Exception:
            pass

    return {
        "competition_id": comp.id,
        "name": comp.name,
        "short_label": _short_competition_label(comp, max_len=22),
        "trackmap_url": url_for(
            "trackmaps_competition_page", competition_id=comp.id, league_id=league_id
        ),
        "my_points": my_row["points"] if my_row else None,
        "my_race_rank": my_row["race_rank"] if my_row else None,
        "member_count": len(member_rows),
        "scored_count": len(race_scores),
        "winner_name": winner["display_name"],
        "winner_points": winner["points"],
        "winner_user_id": winner["user_id"],
        **_user_avatar_fields(winner_user),
        "highlights": highlights[:4],
    }


@app.get("/api/leagues/stats")
def api_leagues_stats():
    """API endpoint for user's league statistics (JSON)."""
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401
    
    try:
        uid = session["user_id"]
        
        # Get user's leagues
        my_leagues = League.query.join(LeagueMembership).filter(
            LeagueMembership.user_id == uid
        ).all()
        
        if not my_leagues:
            return jsonify({
                "leagues": [],
                "message": "Du är inte medlem i någon liga ännu."
            })
        
        # Get all competitions that have results
        competitions = Competition.query.join(CompetitionResult).distinct().order_by(
            Competition.event_date.asc()
        ).all()
        
        stats = []
        for league in my_leagues:
            summary = _league_summary_for_user(league.id, uid)

            # Calculate points per competition
            competition_history = []
            cumulative_points = 0
            
            for comp in competitions:
                # Calculate league points for this competition
                comp_points = calculate_league_points(league.id, comp.id)
                
                if comp_points > 0:  # Only include competitions with points
                    cumulative_points += comp_points
                    competition_history.append({
                        "competition_id": comp.id,
                        "name": comp.name,
                        "series": comp.series,
                        "date": comp.event_date.strftime("%Y-%m-%d") if comp.event_date else "",
                        "points": round(comp_points, 1),
                        "cumulative": round(cumulative_points, 1)
                    })
            
            standings = summary["standings"]
            my_rank = summary["my_rank"]
            my_points = summary["my_points"]
            gap_above = summary["gap_above"]
            gap_below = summary["gap_below"]
            rival_name = summary["rival_name"]
            leader_name = summary["leader_name"]

            stats.append({
                "league_id": league.id,
                "name": league.name,
                "total_points": league.total_points or 0,
                "member_count": summary["member_count"],
                "competitions": competition_history,
                "best_competition": max(competition_history, key=lambda x: x["points"]) if competition_history else None,
                "standings": standings,
                "my_rank": my_rank,
                "my_points": my_points,
                "gap_above": gap_above,
                "gap_below": gap_below,
                "rival_name": rival_name,
                "leader_name": leader_name,
            })
        
        return jsonify({
            "leagues": stats
        })
        
    except Exception as e:
        print(f"Error loading league statistics: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e)}), 500


def _resolve_power_ranking_competition(
    competition_id: int | None,
    *,
    series: str | None = None,
) -> Competition | None:
    """Resolve target competition for power ranking (match index logic, ignore stale admin active race)."""
    series_code = _normalize_countdown_series(series)
    if competition_id:
        c = Competition.query.get(competition_id)
        if c:
            # Reject stale countdown id from another series (e.g. MX id + series=WSX).
            if series_code:
                comp_series = _normalize_countdown_series(getattr(c, "series", None))
                if comp_series == series_code:
                    return c
            else:
                return c

    # Prefer upcoming race with open picks; fallback to next race without results.
    nxt = _next_competition_for_picks(series=series_code, require_open=True)
    if nxt:
        return nxt
    nxt = _next_competition_for_picks(series=series_code, require_open=False)
    if nxt:
        return nxt
    # Explicit series with no race → don't silently fall back to AMA.
    if series_code:
        return None
    return None


def _position_form_points(position: int | None) -> float:
    if position is None or position < 1:
        return 0.0
    return max(0.0, 26.0 - float(position))


def _past_races_for_form(target: Competition, limit: int = 5) -> list[Competition]:
    """
    Completed races (have results) in the same series as target, strictly before target date.
    If limit is None, return all prior completed races (season-to-date).
    """
    ids_with_results = [row[0] for row in db.session.query(CompetitionResult.competition_id).distinct().all()]
    if not ids_with_results:
        return []
    q = Competition.query.filter(Competition.id.in_(ids_with_results))
    if getattr(target, "series", None):
        q = q.filter(Competition.series == target.series)
    if target.event_date:
        q = q.filter(Competition.event_date < target.event_date)
    else:
        q = q.filter(Competition.id != target.id)
    q = q.order_by(Competition.event_date.desc().nullslast(), Competition.id.desc())
    if limit is None:
        return q.all()
    return q.limit(int(limit)).all()


def _form_scores_for_riders(
    rider_ids: set[int], past_comps: list[Competition], decay: float = 0.86
) -> dict[int, float]:
    scores = defaultdict(float)
    comp_ids = [int(c.id) for c in past_comps if c and c.id]
    if not comp_ids:
        return {}
    comp_weight = {int(c.id): decay ** idx for idx, c in enumerate(past_comps)}
    for res in CompetitionResult.query.filter(
        CompetitionResult.competition_id.in_(comp_ids)
    ).all():
        if res.rider_id is None:
            continue
        rid = int(res.rider_id)
        if rid not in rider_ids:
            continue
        w = comp_weight.get(int(res.competition_id), 0.0)
        if w:
            scores[rid] += w * _position_form_points(res.position)
    return dict(scores)


def _result_median_scores_for_riders(
    rider_ids: set[int],
    past_comps: list[Competition],
    *,
    min_results: int,
) -> tuple[dict[int, float], dict[int, dict]]:
    """
    Resultatstyrka: medianplacering (lägre bättre) + bonus för fler körda race i listan.
    Endast förare med minst min_results giltiga placeringar får ett värde.
    """
    from statistics import median

    positions_by_rider: dict[int, list[int]] = defaultdict(list)
    comp_ids = [int(c.id) for c in past_comps if c and c.id]
    if comp_ids:
        for res in CompetitionResult.query.filter(
            CompetitionResult.competition_id.in_(comp_ids)
        ).all():
            if res.rider_id is None:
                continue
            rid = int(res.rider_id)
            if rid not in rider_ids:
                continue
            if res.position is None or int(res.position) < 1:
                continue
            positions_by_rider[rid].append(int(res.position))

    score_raw: dict[int, float] = {}
    meta: dict[int, dict] = {}
    need = max(1, int(min_results))

    for rid, poss in positions_by_rider.items():
        n = len(poss)
        if n < need:
            continue
        med = float(median(poss))
        avg = float(sum(poss) / n)
        base = max(0.0, 26.0 - med)
        stability = min(10.0, float(n)) / 10.0
        score_raw[rid] = base + 2.0 * stability
        meta[rid] = {"count": n, "median": round(med, 2), "avg": round(avg, 2)}

    return score_raw, meta


def _past_comps_for_250_coast(past_all: list[Competition], coast: str) -> list[Competition]:
    c = (coast or "").strip().lower()
    out = []
    for comp in past_all:
        cc = str(getattr(comp, "coast_250", None) or "").strip().lower()
        if cc == c:
            out.append(comp)
    return out


def _prior_competition_for_picks(target: Competition) -> Competition | None:
    """Senaste tävling i samma serie före target (behöver inte ha resultat)."""
    q = Competition.query
    if getattr(target, "series", None):
        q = q.filter(Competition.series == target.series)
    if target.event_date:
        q = q.filter(Competition.event_date < target.event_date)
    else:
        q = q.filter(Competition.id != target.id)
    return q.order_by(Competition.event_date.desc().nullslast(), Competition.id.desc()).first()


def _crowd_scores_for_competition(target: Competition, rider_ids: set[int]) -> dict[int, float]:
    scores = defaultdict(float)
    comp_id = int(target.id)

    # Prefer snapshots once race deadline has passed (stable even if live rows change later)
    try:
        locked = is_picks_deadline_passed(target)
    except Exception:
        locked = False

    if locked:
        try:
            ensure_picks_snapshots_for_competition(comp_id, source="auto_lock")
        except Exception:
            pass
        import json

        snaps = PicksSnapshot.query.filter_by(competition_id=comp_id).all()
        for s in snaps:
            try:
                payload = json.loads(s.payload_json or "{}")
            except Exception:
                continue
            for p in payload.get("race_picks", []) or []:
                rid = p.get("rider_id")
                pred = p.get("predicted_position")
                if rid is None or pred is None:
                    continue
                if rid not in rider_ids:
                    continue
                if int(pred) < 1:
                    continue
                scores[int(rid)] += max(0.0, 11.0 - float(min(int(pred), 10)))
    else:
        picks = RacePick.query.filter_by(competition_id=comp_id).all()
        for p in picks:
            if p.rider_id not in rider_ids:
                continue
            pred = p.predicted_position
            if pred is None or pred < 1:
                continue
            # Higher weight for better predicted finishes (Borda-style, cap at top 10)
            scores[p.rider_id] += max(0.0, 11.0 - float(min(pred, 10)))
    return dict(scores)


def _crowd_scores_with_fallback(target: Competition, rider_ids: set[int]) -> dict[int, float]:
    """Picks för aktuellt race; om inga picks än, föregående veckas tävling."""
    scores = _crowd_scores_for_competition(target, rider_ids)
    if scores and max(scores.values()) > 1e-9:
        return scores
    prior = _prior_competition_for_picks(target)
    if prior and int(prior.id) != int(target.id):
        prior_scores = _crowd_scores_for_competition(prior, rider_ids)
        if prior_scores and max(prior_scores.values()) > 1e-9:
            return prior_scores
    return scores


def _min_max_normalize(d: dict[int, float]) -> dict[int, float]:
    if not d:
        return {}
    vals = list(d.values())
    lo, hi = min(vals), max(vals)
    if hi <= lo + 1e-9:
        return {k: 0.5 for k in d}
    return {k: (v - lo) / (hi - lo) for k, v in d.items()}


def _softmax_percentages(raw: list[float]) -> list[float]:
    if not raw:
        return []
    m = max(raw)
    exps = [math.exp(x - m) for x in raw]
    s = sum(exps) or 1.0
    return [round(100.0 * e / s, 1) for e in exps]


def _out_rider_ids(competition_id: int) -> set[int]:
    try:
        rows = CompetitionRiderStatus.query.filter_by(
            competition_id=competition_id, status="OUT"
        ).all()
        return {r.rider_id for r in rows}
    except Exception:
        return set()


def _riders_450_scope(
    out_ids: set[int], *, series: str | None = None, competition: Competition | None = None
) -> list[Rider]:
    if series == "WSX":
        return [r for r in wsx_roster_query("wsx_sx1").all() if r.id not in out_ids]
    if series == "MXGP":
        from mxgp_fantasy import CLASS_MXGP, mxgp_roster_query

        return [
            r
            for r in mxgp_roster_query().filter(Rider.class_name == CLASS_MXGP).all()
            if r.id not in out_ids
        ]
    q = rider_query_for_list_ui().filter(Rider.class_name == "450cc")
    riders = [r for r in q.all() if r.id not in out_ids]
    if (series or "").strip().upper() == "SMX":
        riders = _restrict_riders_to_smx_field(riders, "450", competition=competition)
    return riders


def _riders_250_scope(
    out_ids: set[int], coast: str | None, *, series: str | None = None, competition: Competition | None = None
) -> tuple[list[Rider], list[Rider] | None]:
    """
    Returns (single_list, split_pair).
    If coast is 'both', single_list is empty and split_pair is (east_riders, west_riders).
    Otherwise single_list is filtered 250 riders for that coast.
    WSX: SX2 roster as a single list (no East/West).
    MXGP: MX2 roster as a single list.
    """
    if series == "WSX":
        return [r for r in wsx_roster_query("wsx_sx2").all() if r.id not in out_ids], None
    if series == "MXGP":
        from mxgp_fantasy import CLASS_MX2, mxgp_roster_query

        return [
            r
            for r in mxgp_roster_query().filter(Rider.class_name == CLASS_MX2).all()
            if r.id not in out_ids
        ], None

    base = [
        r
        for r in rider_query_for_list_ui().filter(Rider.class_name == "250cc").all()
        if r.id not in out_ids
    ]
    if (series or "").strip().upper() == "SMX":
        base = _restrict_riders_to_smx_field(base, "250", competition=competition)
    c = (coast or "").lower()
    if c == "both":
        east = [r for r in base if (r.coast_250 or "") in ("east", "both")]
        west = [r for r in base if (r.coast_250 or "") in ("west", "both")]
        return [], (east, west)
    if c == "east":
        return [r for r in base if (r.coast_250 or "") in ("east", "both")], None
    if c == "west":
        return [r for r in base if (r.coast_250 or "") in ("west", "both")], None
    return base, None


def _wsx_portrait_slug(name: str | None) -> str:
    nl = (name or "").lower().strip().replace(".", "")
    return "".join(c for c in nl if c.isalnum())


# WSX name aliases / _canonical_wsx_rider_name → services.results_import (skiva 4)


def _wsx_portrait_name_candidates(name: str | None) -> list[str]:
    raw = (name or "").strip()
    if not raw:
        return []
    out = [raw]
    canon = _canonical_wsx_rider_name(raw)
    if canon and canon not in out:
        out.append(canon)
    # Also try typo spellings that map TO this official name (legacy portrait files)
    for typo, official in _WSX_NAME_ALIASES.items():
        if official == raw and typo not in out:
            out.append(typo)
        if official == canon and typo not in out:
            out.append(typo)
    return out


def _wsx_static_portrait_rel(name: str | None) -> str | None:
    """Relativ static-sökväg till WSX-porträtt om filen finns (utan mellanslag i URL)."""
    root = os.path.join(app.root_path, "static", "riders", "wsx")
    for candidate in _wsx_portrait_name_candidates(name):
        slug = _wsx_portrait_slug(candidate)
        if not slug:
            continue
        for fname in (f"{slug}.jpg", f"{slug}.png", f"{slug} (1).jpg", f"{slug}_1.jpg"):
            path = os.path.join(root, fname)
            if os.path.isfile(path):
                return f"riders/wsx/{fname}"
    return None


def _wsx_static_avatar_rel(name: str | None) -> str | None:
    """Kvadratisk ansikts-crop för små cirklar (power ranking m.m.)."""
    root = os.path.join(app.root_path, "static", "riders", "wsx", "avatars")
    for candidate in _wsx_portrait_name_candidates(name):
        slug = _wsx_portrait_slug(candidate)
        if not slug:
            continue
        for fname in (f"{slug}.jpg", f"{slug}.png"):
            path = os.path.join(root, fname)
            if os.path.isfile(path):
                return f"riders/wsx/avatars/{fname}"
    return None


def _static_rel_from_public(url: str | None) -> str | None:
    """'/static/riders/x' → 'riders/x'; absolute /rider_portrait/... behålls."""
    u = str(url or "").strip()
    if not u:
        return None
    if u.startswith("/static/"):
        return u[len("/static/") :]
    if u.startswith("/rider_portrait/") or u.startswith(("http://", "https://", "data:")):
        return u
    return u


def _rider_ama_twin_avatar_rel(r: Rider) -> str | None:
    """Tight AMA/SMX-headshot från tvillingrad (bättre i små cirklar än WSX-kort)."""
    try:
        from racerx_rider_bio import find_best_portrait_rider_for_name

        best = find_best_portrait_rider_for_name(getattr(r, "name", None) or "")
    except Exception:
        best = None
    if best is None or int(best.id) == int(r.id):
        return None
    twin_img = (getattr(best, "image_url", None) or "").strip()
    if twin_img and not twin_img.startswith(("http://", "https://", "data:")):
        static_hit = _static_rider_file_url(twin_img)
        if static_hit:
            return _static_rel_from_public(static_hit)
    twin_blob = getattr(best, "rider_image_data", None)
    if twin_blob and str(twin_blob).strip().startswith("data:"):
        return f"/rider_portrait/{int(best.id)}"
    try:
        src = template_rider_image_src(best)
        if src and "/brand_logos/" not in str(src):
            return _static_rel_from_public(src)
    except Exception:
        pass
    # Klassisk riders/{num}_{name}.png
    num = getattr(best, "rider_number", None)
    name = getattr(best, "name", None) or ""
    if num is not None and name:
        name_slug = re.sub(
            r"[^a-z0-9_]",
            "",
            re.sub(r"\s+", "_", name.lower().strip()),
        )
        rel = f"riders/{int(num)}_{name_slug}.png"
        if _static_rider_file_url(rel):
            return rel
    return None


def _rider_portrait_url(r: Rider) -> str | None:
    """Data-URL eller relativ sökväg under static (samma som övriga API:er)."""
    if not r:
        return None
    raw_blob = getattr(r, "rider_image_data", None)
    if raw_blob and str(raw_blob).strip().startswith("data:"):
        return str(raw_blob).strip()

    # 1) Egen image_url om filen faktiskt finns (undvik trasiga mellanslags-URL:er)
    img = (getattr(r, "image_url", None) or "").strip()
    if img:
        if img.startswith(("http://", "https://", "data:")):
            return img
        static_hit = _static_rider_file_url(img)
        if static_hit:
            # powerRankingPortraitSrc förväntar relativ riders/... (inte /static/)
            return _static_rel_from_public(static_hit)
        # Legacy: riders/wsx/foo (1).jpg → prova slug.jpg
        if "riders/wsx/" in img.replace("\\", "/"):
            wsx_rel = _wsx_static_portrait_rel(getattr(r, "name", None))
            if wsx_rel:
                return wsx_rel

    # 2) WSX-mapp efter namn
    cls = (getattr(r, "class_name", None) or "").strip()
    sp = (getattr(r, "series_participation", None) or "").strip().lower()
    if cls in ("wsx_sx1", "wsx_sx2") or sp == "wsx":
        wsx_rel = _wsx_static_portrait_rel(getattr(r, "name", None))
        if wsx_rel:
            return wsx_rel

    # 3) AMA/SMX-tvilling
    twin = _rider_ama_twin_avatar_rel(r)
    if twin:
        return twin

    return None


def _rider_avatar_url(r: Rider) -> str | None:
    """
    Bild för små cirklar (power ranking): föredra AMA-headshot / ansikts-crop
    framför WSX helfigur-kort (som blir oläsliga i 40px).
    """
    if not r:
        return None
    twin = _rider_ama_twin_avatar_rel(r)
    if twin:
        return twin
    avatar = _wsx_static_avatar_rel(getattr(r, "name", None))
    if avatar:
        return avatar
    return _rider_portrait_url(r)

def _static_rider_file_url(image_url: str | None) -> str | None:
    """Om image_url pekar på en fil under static/ som finns — använd den (ej DB-blob)."""
    u = str(image_url or "").strip()
    if not u or u.startswith(("http://", "https://", "data:")):
        return None
    rel = u if u.startswith(("riders/", "uploads/", "trackmaps/")) else f"riders/{u}"
    path = os.path.join(app.root_path, "static", rel.replace("/", os.sep))
    if os.path.isfile(path):
        return f"/static/{rel}"
    return None


def _public_rider_asset_url(url: str | None) -> str | None:
    """Gör riders/... till /static/riders/... för webbläsaren (samma som template_rider_image_src)."""
    u = str(url or "").strip()
    if not u:
        return None
    if u.startswith(("http://", "https://", "data:", "/")):
        return u
    static_u = _static_rider_file_url(u)
    if static_u:
        return static_u
    if u.startswith(("riders/", "uploads/", "trackmaps/")):
        return f"/static/{u}"
    return f"/static/riders/{u}"


def _riders_for_image_lookup(
    rider: Rider,
    *,
    riders_by_name: dict[str, list[Rider]] | None = None,
) -> list[Rider]:
    """Samma namn — dela porträtt mellan 450/250 och WSX-dubletter."""
    try:
        from racerx_rider_bio import find_rider_twins, twins_from_name_map

        if riders_by_name is not None:
            twins = twins_from_name_map(rider, riders_by_name) or [rider]
        else:
            twins = find_rider_twins(rider)
        ordered = [rider] + [t for t in twins if t.id != rider.id]
        seen: set[int] = set()
        out: list[Rider] = []
        for r in ordered:
            if r.id in seen:
                continue
            seen.add(r.id)
            out.append(r)
        return out
    except Exception:
        return [rider]


def template_rider_image_src(
    rider: Rider,
    *,
    bio_card: bool = False,
    riders_by_name: dict[str, list[Rider]] | None = None,
) -> str | None:
    """Bild-URL för Jinja (förarlista, bio) — inkl. dublett-fallback."""
    if not rider:
        return None

    # WSX: prefer downloaded card/avatar over AMA twin webp (often missing in prod → brand logo).
    cls = (getattr(rider, "class_name", None) or "").strip()
    if cls in ("wsx_sx1", "wsx_sx2"):
        own_static = _static_rider_file_url(getattr(rider, "image_url", None))
        if own_static:
            return own_static
        wsx_rel = _wsx_static_portrait_rel(getattr(rider, "name", None))
        if wsx_rel:
            return f"/static/{wsx_rel}"
        # Typo rows (e.g. Jason Andersson) may point at a missing riders/21_*.png —
        # try AMA twin / classic headshot via canonical spelling before brand logo.
        canon = _canonical_wsx_rider_name(getattr(rider, "name", None))
        if canon and canon != (getattr(rider, "name", None) or "").strip():
            try:
                from racerx_rider_bio import find_best_portrait_rider_for_name

                twin = find_best_portrait_rider_for_name(canon)
            except Exception:
                twin = None
            if twin is not None:
                twin_static = _static_rider_file_url(getattr(twin, "image_url", None))
                if twin_static:
                    return twin_static
                num = getattr(twin, "rider_number", None)
                if num is not None:
                    name_slug = re.sub(
                        r"[^a-z0-9_]",
                        "",
                        re.sub(r"\s+", "_", canon.lower().strip()),
                    )
                    rel = f"riders/{int(num)}_{name_slug}.png"
                    hit = _static_rider_file_url(rel)
                    if hit:
                        return hit

    try:
        from racerx_rider_bio import (
            find_best_portrait_rider_for_name,
            rider_ids_with_db_portrait,
            twins_from_name_map,
        )

        twin_list: list[Rider] | None = None
        if riders_by_name is not None:
            twin_list = twins_from_name_map(rider, riders_by_name) or None
        best = find_best_portrait_rider_for_name(rider.name or "", riders=twin_list)
    except Exception:
        best = None
        twin_list = None
    lookup_riders: list[Rider] = []
    if best is not None:
        lookup_riders.append(best)
    for r in _riders_for_image_lookup(rider, riders_by_name=riders_by_name):
        if r.id not in {x.id for x in lookup_riders}:
            lookup_riders.append(r)
    try:
        db_portrait_ids = rider_ids_with_db_portrait([int(r.id) for r in lookup_riders])
    except Exception:
        db_portrait_ids = set()
    brand_fallback: str | None = None
    for r in lookup_riders:
        static_u = _static_rider_file_url(getattr(r, "image_url", None))
        if static_u:
            return static_u
        if int(r.id) in db_portrait_ids:
            return f"/rider_portrait/{r.id}"
        url = _display_image_url_for_rider_row(
            r.id,
            has_db_portrait=False,
            image_url=getattr(r, "image_url", None),
            rider_name=r.name,
            rider_number=r.rider_number,
            class_name=r.class_name,
            coast_250=getattr(r, "coast_250", None),
            bike_brand=getattr(r, "bike_brand", None),
            series_participation=getattr(r, "series_participation", None),
        )
        if not url:
            continue
        if "/static/brand_logos/" in url:
            brand_fallback = brand_fallback or url
            continue
        if bio_card and url.startswith("http"):
            from app.portrait_urls import normalize_racerx_portrait_url_bio

            return normalize_racerx_portrait_url_bio(url) or url
        return url
    return brand_fallback


def _extract_rider_image_url(rider: Rider) -> str | None:
    """Normaliserad extern/lokal image_url — DB, syskon, sedan RacerX-CSV."""
    from app.portrait_urls import lookup_racerx_portrait_by_name, normalize_racerx_portrait_url, score_racerx_portrait_url

    if rider and rider.image_url:
        raw = str(rider.image_url).strip()
        if raw:
            if raw.startswith(("http://", "https://")):
                if score_racerx_portrait_url(raw) >= 0:
                    return normalize_racerx_portrait_url(raw)
            elif raw.startswith("data:"):
                return raw
            elif not raw.startswith(("riders/http",)) and "://" not in raw:
                return normalize_racerx_portrait_url(raw) if raw else None
    return lookup_racerx_portrait_by_name(getattr(rider, "name", None) if rider else None)


def _display_portrait_url_for_rider(
    rider: Rider,
    *,
    riders_by_name: dict[str, list[Rider]] | None = None,
) -> str:
    """Porträtt-URL för race picks — RacerX/DB före statiska gissningar och märkeslogga."""
    img_url = _extract_rider_image_url(rider)
    if not img_url:
        for alt in _riders_for_image_lookup(rider, riders_by_name=riders_by_name):
            if alt.id == rider.id:
                continue
            img_url = _extract_rider_image_url(alt)
            if img_url:
                break
    if img_url:
        return _public_rider_asset_url(img_url) or img_url

    portrait_url = template_rider_image_src(rider, riders_by_name=riders_by_name)
    return portrait_url or ""


def _rider_portrait_payload(
    rider: Rider,
    *,
    riders_by_name: dict[str, list[Rider]] | None = None,
) -> dict[str, str]:
    """Porträttfält för UI — samma logik som race_picks JSON."""
    from app.portrait_urls import lookup_racerx_portrait_by_name

    racerx_url = lookup_racerx_portrait_by_name(rider.name) or ""
    portrait_url = _display_portrait_url_for_rider(rider, riders_by_name=riders_by_name)
    img_url = _extract_rider_image_url(rider) or racerx_url or ""
    if (not portrait_url or "/static/brand_logos/" in str(portrait_url)) and (
        racerx_url or img_url
    ):
        portrait_url = racerx_url or img_url or portrait_url
    return {
        "portrait_url": portrait_url or "",
        "image_url": img_url or "",
        "racerx_portrait_url": racerx_url,
        "bike_brand": (rider.bike_brand or "").lower(),
    }


def _display_image_url_for_rider_row(
    rider_id: int,
    *,
    has_db_portrait: bool,
    image_url: str | None,
    rider_name: str | None,
    rider_number: int | None,
    class_name: str | None,
    coast_250: str | None = None,
    bike_brand: str | None = None,
    series_participation: str | None = None,
) -> str | None:
    """
    Slutlig bild-URL för resultat/pall — samma ordning som race_picks imgSrcFor().
    """
    if has_db_portrait:
        return f"/rider_portrait/{int(rider_id)}"

    if image_url:
        static_u = _static_rider_file_url(image_url)
        if static_u:
            return static_u

    if image_url:
        u = str(image_url).strip()
        if not u:
            pass
        elif u.startswith(("data:", "http://", "https://")):
            if u.startswith("http"):
                from app.portrait_urls import normalize_racerx_portrait_url

                low = u.lower()
                if "post_thumb.png" in low or "/i/logos/" in low:
                    pass
                else:
                    return normalize_racerx_portrait_url(u) or u
            return u
        elif u.startswith("/"):
            return u
        else:
            path = u if u.startswith(("riders/", "uploads/", "trackmaps/")) else f"riders/{u}"
            parts = path.split("/")
            parts[-1] = parts[-1].replace(" ", "_")
            return f"/static/{'/'.join(parts)}"

    class _RiderShim:
        pass

    shim = _RiderShim()
    shim.name = rider_name
    shim.rider_number = rider_number
    shim.class_name = class_name
    shim.coast_250 = coast_250
    shim.series_participation = series_participation
    shim.rider_image_data = None
    shim.image_url = None
    static_path = _resolve_rider_headshot_for_display(shim)
    if static_path:
        parts = static_path.split("/")
        parts[-1] = parts[-1].replace(" ", "_")
        return f"/static/{'/'.join(parts)}"

    if bike_brand:
        brand = str(bike_brand).lower().strip()
        brand_map = {
            "honda": "honda",
            "ktm": "ktm",
            "yamaha": "yamaha",
            "kawasaki": "kawasaki",
            "suzuki": "suzuki",
            "husqvarna": "husqvarna",
            "gasgas": "gasgas",
            "beta": "beta",
            "triumph": "triumph",
        }
        logo = brand_map.get(brand, brand)
        return f"/static/brand_logos/{logo}.png"

    return None


@app.route("/rider_portrait/<int:rider_id>")
def rider_portrait(rider_id: int):
    """Serverar DB-porträtt som bytes — undviker base64 i sid-JSON."""
    import base64
    import hashlib

    rider = rider_query_for_list_ui().filter_by(id=rider_id).first_or_404()
    portrait_id = rider_id
    try:
        from racerx_rider_bio import find_best_portrait_rider_for_name, find_rider_twins

        twins = find_rider_twins(rider)
        best = find_best_portrait_rider_for_name(rider.name or "", riders=twins)
        if best is not None:
            portrait_id = int(best.id)
    except Exception:
        pass

    for pid in dict.fromkeys((int(portrait_id), int(rider_id))):
        img_u = db.session.query(Rider.image_url).filter_by(id=pid).scalar()
        static_u = _static_rider_file_url(str(img_u or "").strip() or None)
        if static_u:
            return redirect(static_u, code=302)

    for pid in dict.fromkeys((int(portrait_id), int(rider_id))):
        hit = _cached_portrait_file(pid)
        if hit:
            return _portrait_file_response(hit[0], hit[1])

    with _PORTRAIT_DECODE_SEM:
        for pid in dict.fromkeys((int(portrait_id), int(rider_id))):
            hit = _cached_portrait_file(pid)
            if hit:
                return _portrait_file_response(hit[0], hit[1])

        raw = db.session.query(Rider.rider_image_data).filter_by(id=portrait_id).scalar()
        s = str(raw or "").strip()
        del raw
        if not s.startswith("data:image"):
            ext = (
                db.session.query(Rider.image_url)
                .filter_by(id=portrait_id)
                .scalar()
            )
            ext_s = str(ext or "").strip()
            if ext_s.startswith("http://") or ext_s.startswith("https://"):
                return redirect(ext_s, code=302)
            return Response(status=404)
        try:
            etag = '"' + hashlib.sha1(s.encode("utf-8")).hexdigest() + '"'
            cache_bin, cache_mime = _portrait_cache_paths(portrait_id, etag)
            inm = request.headers.get("If-None-Match")
            if inm and inm == etag:
                resp = Response(status=304)
                resp.headers["ETag"] = etag
                resp.headers["Cache-Control"] = "public, max-age=2592000, immutable"
                return resp

            if os.path.isfile(cache_bin):
                mime = "image/jpeg"
                if os.path.isfile(cache_mime):
                    with open(cache_mime, encoding="utf-8") as f:
                        mime = (f.read() or mime).strip() or mime
                return _portrait_file_response(cache_bin, mime, etag)

            meta, b64part = s.split(",", 1)
            del s
            mime = "image/jpeg"
            if ";" in meta:
                mime = meta[5:].split(";")[0].strip() or mime
            blob = base64.b64decode(b64part)
            del b64part, meta
            try:
                with open(cache_bin, "wb") as f:
                    f.write(blob)
                with open(cache_mime, "w", encoding="utf-8") as f:
                    f.write(mime)
            except OSError:
                pass
            resp = make_response(blob)
            resp.headers["Content-Type"] = mime
            resp.headers["ETag"] = etag
            resp.headers["Cache-Control"] = "public, max-age=2592000, immutable"
            return resp
        except Exception:
            return Response(status=404)


def _resolve_rider_headshot_for_display(rider: Rider) -> str | None:
    """
    Bild för mallar (recap / färdiga serier): samma ordning som race_picks imgSrcFor
    och race_results — DB först, sedan WSX-mappen riders/wsx/<namn>(1).jpg, sedan generiska riders/*.
    """
    if not rider:
        return None
    for attr in ("rider_image_data", "image_url"):
        v = getattr(rider, attr, None)
        if not v:
            continue
        s = str(v).strip()
        if not s:
            continue
        if s.startswith("data:"):
            return s
        if s.startswith("http://") or s.startswith("https://"):
            return s
        if not s.startswith(("riders/", "uploads/", "trackmaps/")):
            s = "riders/" + s
        return s

    cls = (getattr(rider, "class_name", None) or "").strip()
    sp = (getattr(rider, "series_participation", None) or "").strip().lower()
    if cls in ("wsx_sx1", "wsx_sx2") or sp == "wsx":
        wsx_rel = _wsx_static_portrait_rel(getattr(rider, "name", None))
        if wsx_rel:
            return wsx_rel

    coast = (getattr(rider, "coast_250", None) or "").strip().lower()
    if cls == "250cc" and rider.rider_number is not None and rider.name and coast in (
        "east",
        "west",
    ):
        name_slug = re.sub(
            r"[^a-z0-9_]",
            "",
            re.sub(r"\s+", "_", rider.name.lower().strip()),
        )
        sub = "250east" if coast == "east" else "250west"
        return f"riders/{sub}/{int(rider.rider_number)}_{name_slug}.png"

    if rider.rider_number is not None and rider.name:
        name_slug = re.sub(
            r"[^a-z0-9_]",
            "",
            re.sub(r"\s+", "_", rider.name.lower().strip()),
        )
        return f"riders/{int(rider.rider_number)}_{name_slug}.png"

    return None


def _rank_bucket_picks_only(
    riders: list[Rider],
    crowd_raw_all: dict[int, float],
    *,
    top_n: int = 3,
) -> list[dict]:
    """Ranking enbart från aggregerade spelarpicks (ingen form från resultat)."""
    rids = {r.id for r in riders}
    crowd_raw = {
        rid: float(crowd_raw_all.get(rid, 0.0))
        for rid in rids
        if float(crowd_raw_all.get(rid, 0.0)) > 1e-9
    }
    if not crowd_raw:
        return []

    crowd_n = _min_max_normalize(crowd_raw)
    sorted_ids = sorted(crowd_n.keys(), key=lambda i: crowd_n[i], reverse=True)
    top_ids = sorted_ids[:top_n]
    raw_top = [crowd_n[i] for i in top_ids]
    pcts = _softmax_percentages(raw_top)
    id_to_rider = {r.id: r for r in riders}
    rows = []
    for i, rid in enumerate(top_ids):
        r = id_to_rider.get(rid)
        if not r:
            continue
        c_n = crowd_n.get(rid, 0.5)
        rows.append(
            {
                "rank": i + 1,
                "rider_id": rid,
                "name": r.name,
                "number": r.rider_number,
                "coast_250": r.coast_250,
                "strength_pct": pcts[i] if i < len(pcts) else 0.0,
                "score": round(float(c_n), 4),
                "score_parts": {
                    "form_weight": 0.0,
                    "crowd_weight": 1.0,
                    "form_norm": None,
                    "crowd_norm": round(float(c_n), 4),
                    "form_raw": None,
                    "form_median_pos": None,
                    "form_result_count": None,
                    "crowd_raw": round(float(crowd_raw.get(rid, 0.0)), 4),
                    "source": "picks",
                },
                "image_url": _rider_avatar_url(r),
            }
        )
    return rows


def _rank_bucket(
    riders: list[Rider],
    target: Competition,
    past_comps: list[Competition],
    out_ids: set[int],
    form_weight: float = 0.55,
    crowd_weight: float = 0.45,
    top_n: int = 3,
    *,
    use_prior_pick_fallback: bool = True,
) -> tuple[list[dict], bool]:
    """
    Return (rows, picks_only).
    picks_only=True när ranking saknar tillräckligt med tidigare resultat.
    """
    if not riders:
        return [], False
    rids = {r.id for r in riders}
    if use_prior_pick_fallback:
        crowd_raw_all = _crowd_scores_with_fallback(target, rids)
    else:
        crowd_raw_all = _crowd_scores_for_competition(target, rids)

    # Kräv minst 2 resultat i aktuell scope om det finns minst två tävlingar; annars 1.
    min_res = 2 if len(past_comps) >= 2 else 1
    form_raw, form_meta = _result_median_scores_for_riders(rids, past_comps, min_results=min_res)
    eligible = set(form_raw.keys())
    if not eligible:
        return _rank_bucket_picks_only(riders, crowd_raw_all, top_n=top_n), True

    crowd_raw = {rid: float(crowd_raw_all.get(rid, 0.0)) for rid in eligible}
    form_raw_e = {rid: form_raw[rid] for rid in eligible}
    form_n = _min_max_normalize(form_raw_e)
    crowd_n = _min_max_normalize(crowd_raw)

    combined: dict[int, float] = {}
    for rid in eligible:
        f = form_n.get(rid, 0.5)
        c = crowd_n.get(rid, 0.5)
        if not crowd_raw or max(crowd_raw.values()) <= 1e-9:
            combined[rid] = f
        else:
            combined[rid] = form_weight * f + crowd_weight * c

    sorted_ids = sorted(combined.keys(), key=lambda i: combined[i], reverse=True)
    top_ids = sorted_ids[:top_n]
    raw_top = [combined[i] for i in top_ids]
    pcts = _softmax_percentages(raw_top)
    id_to_rider = {r.id: r for r in riders}
    rows = []
    for i, rid in enumerate(top_ids):
        r = id_to_rider.get(rid)
        if not r:
            continue
        f_n = form_n.get(rid, 0.5)
        c_n = crowd_n.get(rid, 0.5)
        combined_score = combined.get(rid, 0.0)
        fm = form_meta.get(rid) or {}
        rows.append(
            {
                "rank": i + 1,
                "rider_id": rid,
                "name": r.name,
                "number": r.rider_number,
                "coast_250": r.coast_250,
                "strength_pct": pcts[i] if i < len(pcts) else 0.0,
                "score": round(combined_score, 4),
                "score_parts": {
                    "form_weight": form_weight,
                    "crowd_weight": crowd_weight,
                    "form_norm": round(float(f_n), 4),
                    "crowd_norm": round(float(c_n), 4),
                    "form_raw": round(float(form_raw.get(rid, 0.0)), 4) if form_raw else None,
                    "form_median_pos": fm.get("median"),
                    "form_result_count": fm.get("count"),
                    "crowd_raw": round(float(crowd_raw.get(rid, 0.0)), 4) if crowd_raw else None,
                    "source": "results_and_picks",
                },
                "image_url": _rider_avatar_url(r),
            }
        )
    return rows, False


def build_power_ranking_payload(target: Competition) -> dict:
    """Build power ranking JSON (cached)."""
    cache_key = int(target.id)
    now = time.time()
    cached = _POWER_RANKING_CACHE.get(cache_key)
    if cached and cached[0] > now:
        return cached[1]

    series_code = _normalize_countdown_series(getattr(target, "series", None)) or getattr(
        target, "series", None
    )

    # Form: senaste avklarade race i samma serie (inte hela säsongen — undvik att MX #2 ser ut som #1)
    past = _past_races_for_form(target, limit=5)
    out_ids = _out_rider_ids(target.id)

    try:
        picks_locked = is_picks_locked(target)
    except Exception:
        picks_locked = False

    crowd_users = (
        db.session.query(db.func.count(db.distinct(RacePick.user_id)))
        .filter(RacePick.competition_id == target.id)
        .scalar()
        or 0
    )

    # Tunn form (t.ex. bara Fox) → lita mer på picks till aktuellt race
    if len(past) <= 1:
        fw, cw = 0.35, 0.65
    else:
        fw, cw = 0.55, 0.45

    riders_450 = _riders_450_scope(out_ids, series=series_code, competition=target)
    # För SX: visa alltid både East/West power rankings (även om veckans coast är bara en av dem).
    if series_code == "SX":
        single_250, split_250 = _riders_250_scope(
            out_ids, "both", series=series_code, competition=target
        )
    else:
        single_250, split_250 = _riders_250_scope(
            out_ids,
            getattr(target, "coast_250", None),
            series=series_code,
            competition=target,
        )

    label_450 = "SX1" if series_code == "WSX" else ("MXGP" if series_code == "MXGP" else "450cc")
    label_250 = "SX2" if series_code == "WSX" else ("MX2" if series_code == "MXGP" else "250cc")

    top_450, picks_only_450 = _rank_bucket(
        riders_450, target, past, out_ids, form_weight=fw, crowd_weight=cw, use_prior_pick_fallback=False
    )

    past_east = _past_comps_for_250_coast(past, "east")
    past_west = _past_comps_for_250_coast(past, "west")

    picks_only_any = picks_only_450
    form_names = [c.name for c in past if c and c.name]
    if len(past) == 0:
        method = (
            "Baserat på spelarnas picks till denna tävling (inget tidigare resultat i serien)"
        )
        form_scope_label = "ingen form ännu"
    elif len(past) == 1:
        method = (
            f"Form från {past[0].name} · picks till {target.name} "
            f"({'låsta' if picks_locked else 'pågående'})"
        )
        form_scope_label = f"form: {past[0].name}"
    else:
        method = (
            f"Form från {len(past)} senaste race · picks till {target.name} "
            f"({'låsta' if picks_locked else 'pågående'})"
        )
        form_scope_label = f"{len(past)} senaste race"

    payload: dict = {
        "ok": True,
        "competition": {
            "id": target.id,
            "name": target.name,
            "series": target.series,
            "coast_250": target.coast_250,
            "event_date": target.event_date.isoformat() if target.event_date else None,
        },
        "label_450": label_450,
        "label_250": label_250,
        "method": method,
        "past_races_used": len(past),
        "form_races": form_names,
        "form_scope_label": form_scope_label,
        "crowd_users": int(crowd_users),
        "crowd_picks_locked": bool(picks_locked),
        "ranking_source": "picks" if picks_only_any and len(past) == 0 else "results",
        "riders_450": top_450,
        "riders_250": None,
        "riders_250_east": None,
        "riders_250_west": None,
    }

    if split_250:
        east_r, west_r = split_250
        top_east, po_e = _rank_bucket(
            east_r, target, past_east, out_ids, form_weight=fw, crowd_weight=cw, use_prior_pick_fallback=False
        )
        top_west, po_w = _rank_bucket(
            west_r, target, past_west, out_ids, form_weight=fw, crowd_weight=cw, use_prior_pick_fallback=False
        )
        payload["riders_250_east"] = top_east
        payload["riders_250_west"] = top_west
        picks_only_any = picks_only_any or po_e or po_w
    else:
        coast = str(getattr(target, "coast_250", None) or "").strip().lower()
        past_250 = _past_comps_for_250_coast(past, coast) if coast in ("east", "west") else past
        top_250, po_250 = _rank_bucket(
            single_250, target, past_250, out_ids, form_weight=fw, crowd_weight=cw, use_prior_pick_fallback=False
        )
        payload["riders_250"] = top_250
        picks_only_any = picks_only_any or po_250

    if picks_only_any and len(past) > 0:
        payload["method"] = (
            "Delvis baserat på spelarnas picks där det saknas tillräckligt "
            "med tidigare resultat i klassen"
        )
        payload["ranking_source"] = "mixed"

    _POWER_RANKING_CACHE[cache_key] = (now + _POWER_RANKING_CACHE_TTL, payload)
    return payload


@app.get("/api/power_ranking")
def api_power_ranking():
    """
    Informationsvy: form från senaste resultat + aggregerade spelarpicks.
    Inte bettingodds.
    Query: competition_id=… and/or series=SX|MX|SMX|WSX
    """
    try:
        comp_id = request.args.get("competition_id", type=int)
        series = request.args.get("series")
        target = _resolve_power_ranking_competition(comp_id, series=series)
        if not target:
            return jsonify({"ok": False, "error": "no_competition"}), 404
        return jsonify(build_power_ranking_payload(target))
    except Exception as e:
        print(f"power_ranking error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"ok": False, "error": str(e)}), 500


@app.get("/api/mxon_crowd_ranking")
def api_mxon_crowd_ranking():
    """
    MXoN crowd consensus: ranked nations + class favorites from tips.
    No pick counts — order only (power-ranking style).
    Query: competition_id=… optional
    """
    try:
        from mxon_fantasy import build_mxon_crowd_ranking

        comp_id = request.args.get("competition_id", type=int)
        target = _resolve_power_ranking_competition(comp_id, series="MXON")
        if not target:
            return jsonify({"ok": False, "error": "no_competition"}), 404
        payload = build_mxon_crowd_ranking(int(target.id))
        if not payload.get("ok"):
            return jsonify(payload), 404
        return jsonify(payload)
    except Exception as e:
        print(f"mxon_crowd_ranking error: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"ok": False, "error": str(e)}), 500




