@app.route("/leagues/<int:league_id>")
def league_detail_page(league_id):
    if "user_id" not in session:
        return _redirect_to_login()
    league = League.query.get_or_404(league_id)
    is_member = LeagueMembership.query.filter_by(league_id=league_id, user_id=session["user_id"]).first()
    if not is_member:
        flash("Du är inte medlem i denna liga.", "error")
        return redirect(url_for("leagues_page"))

    uid = session["user_id"]
    _mark_challenge_notifications_read(uid, league_id)
    g.league_shame_map = _league_shame_map(league_id)
    summary = _league_summary_for_user(league_id, uid)
    race_matrix = _league_race_matrix(league_id, race_limit=8)
    upcoming_races = _upcoming_competitions(limit=4)
    picks_pulse = _league_picks_pulse(league_id, uid)
    last_race_digest = _league_last_race_digest(league_id, uid, summary)
    rival_card = _league_rival_card(league_id, uid, summary)
    challenges_ctx = _league_challenges_context(league_id, uid)

    member_users = (
        db.session.query(User)
        .join(LeagueMembership, User.id == LeagueMembership.user_id)
        .filter(LeagueMembership.league_id == league_id)
        .order_by(User.username)
        .all()
    )

    season_leaderboard = summary["standings"]

    season_archives = []
    try:
        from league_season_archive import list_archives_for_league

        season_archives = list_archives_for_league(int(league_id))
    except Exception as e:
        print(f"league_detail archives: {e}")

    # Get pending requests if user is league creator
    pending_requests = []
    is_creator = league.creator_id == session["user_id"]
    if is_creator:
        pending_requests = db.session.query(
            LeagueRequest.id,
            LeagueRequest.message,
            LeagueRequest.created_at,
            User.username,
            User.display_name
        ).join(User, LeagueRequest.user_id == User.id).filter(
            LeagueRequest.league_id == league_id,
            LeagueRequest.status == 'pending'
        ).order_by(LeagueRequest.created_at.desc()).all()

    return render_template(
        "league_detail.html",
        league=league,
        members=[
            {
                "user_id": u.id,
                "id": u.id,
                "username": u.username,
                "display_name": u.display_name or u.username,
                **_user_avatar_fields(u),
            }
            for u in member_users
        ],
        season_leaderboard=season_leaderboard,
        summary=summary,
        race_matrix=race_matrix,
        upcoming_races=upcoming_races,
        picks_pulse=picks_pulse,
        last_race_digest=last_race_digest,
        rival_card=rival_card,
        challenges=challenges_ctx,
        pending_requests=pending_requests,
        is_creator=is_creator,
        current_user_id=uid,
        season_archives=season_archives,
    )


def _resolve_season_team_user_id() -> int | None:
    """Aktuell användare eller ?user_id= för att visa annans säsongsteam."""
    if "user_id" not in session:
        return None
    raw = request.args.get("user_id", type=int)
    if raw is not None:
        return raw
    return session["user_id"]


def _ensure_season_team_created_at_column() -> None:
    """season_teams.created_at — used so late-built teams get no retroactive race points."""
    global _SEASON_TEAM_CREATED_AT_CHECKED
    if _SEASON_TEAM_CREATED_AT_CHECKED:
        return
    try:
        if "sqlite" in str(db.engine.url):
            _sqlite_add_column_if_missing(
                "season_teams", "created_at", "created_at DATETIME"
            )
        else:
            db.session.execute(
                db.text(
                    "ALTER TABLE season_teams ADD COLUMN IF NOT EXISTS created_at TIMESTAMP"
                )
            )
            db.session.commit()
    except Exception as e:
        try:
            db.session.rollback()
        except Exception:
            pass
        print(f"ensure season_teams.created_at: {e}")
    _SEASON_TEAM_CREATED_AT_CHECKED = True


def _season_team_created_date(team) -> date | None:
    """Calendar date the season team first existed (UTC). None = legacy / unknown."""
    created = getattr(team, "created_at", None)
    if not created:
        return None
    if hasattr(created, "date"):
        return created.date()
    return None


def season_team_counts_competition(team, competition) -> bool:
    """
    Whether a competition can award season-team points.
    - Tippa-only (WSX / MXON / MXGP): never — season team is AMA (SX/MX/SMX) only.
    - Late joiners: competition.event_date >= team.created_at (date).
    - Legacy teams without created_at keep counting all AMA races.
    """
    if competition is not None and is_tippa_only_series(getattr(competition, "series", None)):
        return False
    created_d = _season_team_created_date(team)
    if created_d is None:
        return True
    if not competition or not getattr(competition, "event_date", None):
        return True
    event_d = competition.event_date
    if hasattr(event_d, "date"):
        event_d = event_d.date()
    return event_d >= created_d


def recalculate_season_team_total_points(team) -> int:
    """Sum rider result points (+ SMX top-6 class bonus) only for eligible races."""
    _ensure_season_team_created_at_column()
    team_riders = SeasonTeamRider.query.filter_by(season_team_id=team.id).all()
    rider_ids = [tr.rider_id for tr in team_riders]
    if not rider_ids:
        team.total_points = 0
        return 0

    riders_by_class: dict[str, list[int]] = {}
    for tr in team_riders:
        rider = Rider.query.get(tr.rider_id)
        if rider:
            riders_by_class.setdefault(rider.class_name, []).append(rider.id)

    total_season_points = 0
    bonus_points = 0
    competition_bonuses: dict[int, dict[str, list[int]]] = {}

    for rider_id in rider_ids:
        for result in CompetitionResult.query.filter_by(rider_id=rider_id).all():
            comp = Competition.query.get(result.competition_id)
            if not season_team_counts_competition(team, comp):
                continue
            total_season_points += calculate_rider_points_for_position(result.position)
            if result.position and result.position <= 6:
                rider = Rider.query.get(rider_id)
                if rider and (not comp or comp.series in ("SMX", None)):
                    competition_bonuses.setdefault(
                        result.competition_id, {"450cc": [], "250cc": []}
                    )
                    competition_bonuses[result.competition_id][rider.class_name].append(
                        rider_id
                    )

    for comp_id_key, classes in competition_bonuses.items():
        comp = Competition.query.get(comp_id_key)
        if comp and comp.series not in ("SMX", None):
            continue
        for class_name in ("450cc", "250cc"):
            if class_name not in riders_by_class:
                continue
            team_set = set(riders_by_class[class_name])
            top6_set = set(classes.get(class_name) or [])
            if team_set and team_set.issubset(top6_set):
                bonus_points += 50

    team.total_points = total_season_points + bonus_points
    return team.total_points


def build_season_team_competition_points(user_id: int) -> tuple[dict | None, str | None]:
    """Returnerar {competitions: [...]} eller felkod."""
    _ensure_season_team_created_at_column()
    team = SeasonTeam.query.filter_by(user_id=user_id).first()
    if not team:
        return None, "no_team"

    team_riders = SeasonTeamRider.query.filter_by(season_team_id=team.id).all()
    rider_ids = [tr.rider_id for tr in team_riders]
    season_year = _season_team_target_year()
    # AMA only (SX/MX/SMX) for the active season-team year — never WSX / MXON / MXGP.
    competitions = (
        Competition.query.filter(ama_competition_clause()).all()
    )
    competitions.sort(
        key=lambda c: (
            c.event_date is None,
            c.event_date or date.min,
            int(c.id or 0),
        )
    )

    competition_points = []
    for comp in competitions:
        if is_tippa_only_series(getattr(comp, "series", None)):
            continue
        if comp.event_date and int(comp.event_date.year) != int(season_year):
            continue
        counts = season_team_counts_competition(team, comp)
        comp_points = 0
        rider_breakdown = []
        bonus_points = 0

        if counts:
            for rider_id in rider_ids:
                result = CompetitionResult.query.filter_by(
                    rider_id=rider_id, competition_id=comp.id
                ).first()
                if result:
                    rider = Rider.query.get(rider_id)
                    points = calculate_rider_points_for_position(result.position)
                    comp_points += points
                    rider_breakdown.append(
                        _season_team_breakdown_row(
                            rider, rider_id, position=result.position, points=points
                        )
                    )

            if comp.series == "SMX" or comp.series is None:
                riders_by_class = {}
                for tr in team_riders:
                    rider = Rider.query.get(tr.rider_id)
                    if rider:
                        riders_by_class.setdefault(rider.class_name, []).append(rider.id)

                competition_bonuses = {"450cc": [], "250cc": []}
                for rider_id in rider_ids:
                    result = CompetitionResult.query.filter_by(
                        rider_id=rider_id, competition_id=comp.id
                    ).first()
                    if result:
                        rider = Rider.query.get(rider_id)
                        if rider and result.position and result.position <= 6:
                            competition_bonuses[rider.class_name].append(rider_id)

                for class_name in ("450cc", "250cc"):
                    if class_name in riders_by_class:
                        team_riders_in_class = set(riders_by_class[class_name])
                        top6_riders_in_class = set(competition_bonuses[class_name])
                        if team_riders_in_class and team_riders_in_class.issubset(
                            top6_riders_in_class
                        ):
                            bonus_points += 50

        has_results = (
            CompetitionResult.query.filter_by(competition_id=comp.id).first() is not None
        )
        competition_points.append(
            {
                "competition_id": comp.id,
                "name": comp.name,
                "event_date": comp.event_date.strftime("%Y-%m-%d")
                if comp.event_date
                else "",
                "series": comp.series,
                "total_points": (comp_points + bonus_points) if counts else 0,
                "rider_points": comp_points if counts else 0,
                "bonus_points": bonus_points if counts else 0,
                "has_results": has_results,
                "counts_for_team": counts,
                "before_team": (not counts),
                "rider_breakdown": rider_breakdown if counts else [],
            }
        )

    scored = [
        c
        for c in competition_points
        if c.get("has_results") and c.get("counts_for_team") and not c.get("before_team")
    ]
    return {
        "competitions": competition_points,
        "season_year": int(season_year),
        "scored_race_count": len(scored),
        "team_created_at": team.created_at.isoformat() if team.created_at else None,
    }, None



def _season_team_riders_for_user(user_id: int):
    team = SeasonTeam.query.filter_by(user_id=user_id).first()
    if not team:
        return None, []
    riders = (
        Rider.query.join(SeasonTeamRider, Rider.id == SeasonTeamRider.rider_id)
        .filter(SeasonTeamRider.season_team_id == team.id)
        .all()
    )
    return team, riders


def _season_team_riders_ui(user_id: int) -> tuple[object | None, list[dict]]:
    """Roster for compact UI strips (picks overview, home)."""
    team, riders = _season_team_riders_for_user(user_id)
    if not team:
        return None, []

    def _sort_key(r: Rider):
        cls = (r.class_name or "").lower()
        class_rank = 0 if "450" in cls else 1
        return (class_rank, -(r.price or 0), (r.name or "").lower())

    out: list[dict] = []
    for r in sorted(riders, key=_sort_key):
        portrait = _rider_portrait_payload(r)
        portrait_url = (portrait.get("portrait_url") or "").strip()
        if not portrait_url or "/static/brand_logos/" in portrait_url:
            portrait_url = f"/rider_portrait/{int(r.id)}"
        out.append(
            {
                "id": int(r.id),
                "name": r.name,
                "number": r.rider_number,
                "class": r.class_name or "",
                "brand": (r.bike_brand or "").lower(),
                "image_url": portrait.get("image_url") or r.image_url,
                "portrait_url": portrait_url,
                "team_name": team.team_name,
                "total_points": int(team.total_points or 0),
            }
        )
    return team, out


def _season_team_breakdown_row(rider: Rider | None, rider_id: int, *, position, points: int) -> dict:
    """One rider line for season-team competition details (incl. portrait)."""
    portrait_url = f"/rider_portrait/{int(rider_id)}"
    if rider:
        try:
            payload = _rider_portrait_payload(rider)
            p = (payload.get("portrait_url") or "").strip()
            if p and "/static/brand_logos/" not in p:
                portrait_url = p
        except Exception:
            pass
    return {
        "rider_id": int(rider_id),
        "rider_name": rider.name if rider else f"Rider {rider_id}",
        "rider_number": rider.rider_number if rider else None,
        "class_name": rider.class_name if rider else None,
        "position": position,
        "points": int(points or 0),
        "portrait_url": portrait_url,
    }


@app.route("/season_team")
def season_team_page():
    if "user_id" not in session:
        return _redirect_to_login()

    _ensure_season_team_created_at_column()
    user_id = session["user_id"]
    team, riders = _season_team_riders_for_user(user_id)

    # Same AMA tippa total as swap cost / highscore (excludes WSX/MXON/MXGP leftovers).
    user_total_points = _user_pick_total_points(user_id)

    return render_template(
        "season_team.html",
        team=team,
        riders=riders,
        user_total_points=user_total_points,
        is_own_team=True,
        viewing_user=None,
        season_team_user_id=user_id,
    )


@app.route("/season_team/view/<int:user_id>")
def view_user_season_team(user_id: int):
    """Andras säsongsteam: poäng per tävling (från leaderboard)."""
    if "user_id" not in session:
        return _redirect_to_login()
