def _clean_bio_text(text: str) -> str:
    """Ta bort RacerX/MX Fantasy-brusrubriker innan visning."""
    import re

    raw = (text or "").strip()
    if not raw:
        return ""
    raw = re.sub(r"^\(MX Fantasy\)\s*", "", raw, flags=re.IGNORECASE)
    raw = re.sub(r"^MX Fantasy[:\s]+", "", raw, flags=re.IGNORECASE)
    return raw.strip()


def _bio_sentences(text: str) -> list[str]:
    import re

    cleaned = _clean_bio_text(text)
    if not cleaned:
        return []
    parts = re.split(r"(?<=[.!?])\s+", cleaned)
    return [p.strip() for p in parts if p.strip()]


def _bio_sentence_is_boilerplate(sentence: str) -> bool:
    import re

    s = sentence.lower()
    patterns = (
        r"\bwas born\b",
        r"\bföddes\b",
        r"\bborn on\b",
        r"\bbörjade tävla professionellt\b",
        r"\bturned pro\b",
        r"\bbegan his professional\b",
        r"\bbegan her professional\b",
        r"\bstarted racing professionally\b",
    )
    return any(re.search(p, s) for p in patterns)


def _bio_sentence_hook_score(sentence: str) -> int:
    score = 0
    s = sentence.lower()
    if _bio_sentence_is_boilerplate(sentence):
        score -= 8
    keywords = (
        "champion",
        "mästare",
        "championship",
        "vann",
        "won",
        "first",
        "första",
        "debut",
        "superstar",
        "led",
        "dominer",
        "dominated",
        "title",
        "titlar",
        "main event",
    )
    for kw in keywords:
        if kw in s:
            score += 3
    if 40 <= len(sentence) <= 180:
        score += 1
    return score


def _split_bio_hook(text: str) -> tuple[str, str]:
    """Välj en intressant mening som hook — hoppa över födelse/pro-debut."""
    sentences = _bio_sentences(text)
    if not sentences:
        return "", ""

    ranked = sorted(
        enumerate(sentences[:6]),
        key=lambda item: (-_bio_sentence_hook_score(item[1]), item[0]),
    )
    hook_idx, hook = ranked[0]
    if _bio_sentence_hook_score(hook) < 0 and len(sentences) > 1:
        hook_idx, hook = 1, sentences[1]
    if _bio_sentence_hook_score(hook) < 0:
        hook_idx, hook = 0, sentences[0]

    body_parts = [s for i, s in enumerate(sentences) if i != hook_idx]
    return hook, " ".join(body_parts).strip()


def _bio_content_parts(bio: str | None) -> dict[str, str]:
    full = _clean_bio_text(bio or "")
    hook, body = _split_bio_hook(full)
    return {"hook": hook, "body": body, "full": full}


def _picks_series_for_rider(rider: Rider) -> str:
    if (rider.class_name or "") in ("wsx_sx1", "wsx_sx2"):
        return "WSX"
    return "SX"


def _rider_class_by_id() -> dict[int, str]:
    """Id → class_name utan att ladda rider_image_data (OOM-skydd)."""
    return {
        int(rid): str(cls or "")
        for rid, cls in db.session.query(Rider.id, Rider.class_name).all()
    }


def _rider_pick_class_names(rider: Rider, *, is_wsx: bool) -> set[str]:
    cls = (rider.class_name or "").strip().lower()
    if is_wsx:
        if cls == "wsx_sx1":
            return {"wsx_sx1"}
        if cls == "wsx_sx2":
            return {"wsx_sx2"}
        return set()
    if cls in ("450cc", "450"):
        return {"450cc"}
    if cls in ("250cc", "250"):
        return {"250cc"}
    return set()


def _rider_pick_stats_for_comp(rider: Rider, comp: Competition) -> dict[str, Any] | None:
    """Andel lagn som plockat föraren inför en tävling."""
    from collections import Counter

    rider_id = int(rider.id)
    is_wsx = (comp.series or "") == "WSX"
    allowed = _rider_pick_class_names(rider, is_wsx=is_wsx)
    if not allowed:
        return None

    class_by_id = _rider_class_by_id()
    n_lineups = 0
    picked = 0
    p1 = 0
    pos_counts: Counter[int] = Counter()
    holeshot = 0

    for _uid, payload in _iter_crowd_pick_payloads(int(comp.id), ensure_snapshots=True):
        race_picks = payload.get("race_picks") or []
        has_lineup = False
        for p in race_picks:
            try:
                rid = int(p.get("rider_id"))
                pos = int(p.get("predicted_position"))
            except (TypeError, ValueError):
                continue
            r_cls = (class_by_id.get(rid) or "").strip().lower()
            if not r_cls or r_cls not in allowed:
                continue
            has_lineup = True
            if rid == rider_id:
                picked += 1
                pos_counts[pos] += 1
                if pos == 1:
                    p1 += 1
        if has_lineup:
            n_lineups += 1

        holos = payload.get("holeshot_picks") or {}
        for _cls, rid in holos.items():
            if rid is not None and int(rid) == rider_id:
                holeshot += 1

    if n_lineups <= 0:
        return None

    common = pos_counts.most_common(1)[0] if pos_counts else None
    return {
        "lineups": n_lineups,
        "picked_count": picked,
        "picked_pct": round(100.0 * picked / n_lineups, 1),
        "p1_pct": round(100.0 * p1 / n_lineups, 1),
        "common_position": common[0] if common else None,
        "common_position_pct": round(100.0 * common[1] / n_lineups, 1) if common else None,
        "holeshot_pct": round(100.0 * holeshot / n_lineups, 1),
    }


def _rider_recent_race_results(rider_id: int, *, limit: int = 4) -> list[dict[str, Any]]:
    rows = (
        db.session.query(CompetitionResult, Competition)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .filter(CompetitionResult.rider_id == int(rider_id))
        .order_by(Competition.event_date.desc(), Competition.id.desc())
        .limit(limit)
        .all()
    )
    out: list[dict[str, Any]] = []
    for cr, comp in rows:
        pts = int(_standing_points_for_comp_result(cr, comp))
        out.append(
            {
                "comp_name": comp.name,
                "event_date": comp.event_date,
                "position": int(cr.position),
                "points": pts,
                "series": comp.series or "",
            }
        )
    return out


def _current_racing_season_year() -> int:
    row = (
        Competition.query.filter(
            Competition.event_date.isnot(None),
            Competition.series.in_(("SX", "MX", "SMX", "WSX")),
        )
        .order_by(Competition.event_date.desc())
        .first()
    )
    if row and row.event_date:
        return int(row.event_date.year)
    return get_today().year


def _dedupe_championship_query_rows(
    rows: list[tuple],
) -> list[tuple]:
    """One row per rider per race — handles duplicate Competition rows and result rows."""
    by_comp_rider: dict[tuple[int, int], tuple] = {}
    for cr, comp, rider in rows:
        key = (int(comp.id), int(rider.id))
        prev = by_comp_rider.get(key)
        if prev is None or int(cr.result_id) > int(prev[0].result_id):
            by_comp_rider[key] = (cr, comp, rider)

    by_race_rider: dict[tuple, tuple] = {}
    for cr, comp, rider in by_comp_rider.values():
        coast = (comp.coast_250 or "").strip().lower()
        if comp.event_date:
            race_day = comp.event_date.isoformat()
        else:
            race_day = f"comp_{comp.id}"
        race_key = (
            str(comp.series).strip().upper(),
            race_day,
            coast,
            int(rider.id),
        )
        prev = by_race_rider.get(race_key)
        if prev is None or int(cr.result_id) > int(prev[0].result_id):
            by_race_rider[race_key] = (cr, comp, rider)
    return list(by_race_rider.values())


def _accumulate_championship_totals(*, year: int | None = None) -> dict[tuple, dict[int, float]]:
    """Samma bucket-logik som race results — valfritt filter på kalenderår."""
    if year is not None:
        now = time.time()
        cached = _CHAMPIONSHIP_TOTALS_CACHE.get(int(year))
        if cached and cached[0] > now:
            return cached[1]

    from collections import defaultdict

    totals: dict[tuple, dict[int, float]] = defaultdict(lambda: defaultdict(float))
    promoted_250_coasts = _promoted_250_coast_by_name()

    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .all()
    )
    rows = _dedupe_championship_query_rows(rows)

    for cr, comp, rider in rows:
        if year is not None and (not comp.event_date or int(comp.event_date.year) != int(year)):
            continue

        s = str(comp.series).strip() if comp.series is not None else ""
        if s not in ("WSX", "SX", "MX", "SMX"):
            continue

        if s == "WSX":
            if cr.rider_points is not None:
                pts = float(cr.rider_points)
            else:
                pts = float(get_smx_qualification_points(cr.position))
        elif s == "SMX":
            mult = comp.point_multiplier or 1.0
            pts = float(get_smx_qualification_points(cr.position)) * float(mult)
        else:
            pts = float(_result_points_for_standing(cr, comp))

        bucket = _championship_bucket_for_rider(cr, comp, rider, promoted_250_coasts)
        if not bucket:
            continue

        totals[bucket][int(rider.id)] += pts

    result = {k: dict(v) for k, v in totals.items()}
    if year is not None:
        _CHAMPIONSHIP_TOTALS_CACHE[int(year)] = (time.time() + _HOMEPAGE_CACHE_TTL, result)
    return result


def _rank_in_points_map(points_map: dict[int, float], rider_id: int) -> dict[str, int] | None:
    if rider_id not in points_map:
        return None
    items = sorted(points_map.items(), key=lambda x: (-x[1], x[0]))
    pts_raw = float(points_map[rider_id])
    pts = int(pts_raw) if abs(pts_raw - round(pts_raw)) < 0.001 else round(pts_raw, 1)
    rank = next(i + 1 for i, (rid, _) in enumerate(items) if int(rid) == rider_id)
    return {"rank": rank, "points": pts, "of": len(items)}


def _merge_championship_maps(
    totals: dict[tuple, dict[int, float]],
    *buckets: tuple,
) -> dict[int, float]:
    from collections import defaultdict

    merged: dict[int, float] = defaultdict(float)
    for bucket in buckets:
        for rid, pts in (totals.get(bucket) or {}).items():
            merged[int(rid)] += float(pts)
    return dict(merged)


def _rider_championship_standings(rider: Rider, year: int) -> list[dict[str, Any]]:
    """SX / MX / SMX-placering för säsongen (samma regler som resultatsidan)."""
    totals = _accumulate_championship_totals(year=year)
    rid = int(rider.id)
    cls = (rider.class_name or "").strip().lower()
    coast = (rider.coast_250 or "").strip().lower()
    rows: list[dict[str, Any]] = []

    def add_row(series: str, label: str, points_map: dict[int, float]) -> None:
        standing = _rank_in_points_map(points_map, rid)
        if standing:
            rows.append({"series": series, "label": label, **standing})

    if cls in ("wsx_sx1", "wsx_sx2"):
        add_row("WSX", f"WSX {year}", totals.get(("wsx", cls)) or {})
        return rows

    if cls in ("450cc", "450"):
        sx_b: tuple = ("sx", "450")
        mx_b = ("mx", "450")
        add_row("SX", f"SX {year}", totals.get(sx_b) or {})
        add_row("MX", f"MX {year}", totals.get(mx_b) or {})
        add_row("SMX", f"SMX {year}", _merge_championship_maps(totals, sx_b, mx_b))
        return rows

    if cls in ("250cc", "250") and coast in ("east", "west"):
        sx_b = ("sx", "250", coast)
        mx_b = ("mx", "250", coast)
        tag = "250E" if coast == "east" else "250W"
        add_row("SX", f"SX {tag} {year}", totals.get(sx_b) or {})
        add_row("MX", f"MX {tag} {year}", totals.get(mx_b) or {})
        add_row("SMX", f"SMX {tag} {year}", _merge_championship_maps(totals, sx_b, mx_b))

    return rows


def _last_completed_competition(*, series: str | None = None) -> Competition | None:
    """Senaste tävling med resultat. series=None → AMA (exkl. WSX)."""
    today = get_today()
    series_code = _normalize_countdown_series(series)
    q = (
        db.session.query(Competition)
        .join(CompetitionResult, CompetitionResult.competition_id == Competition.id)
        .filter(Competition.event_date.isnot(None))
        .filter(Competition.event_date <= today)
    )
    if series_code:
        q = q.filter(Competition.series == series_code)
    else:
        q = q.filter(ama_competition_clause())
    return q.order_by(Competition.event_date.desc(), Competition.id.desc()).first()


def _spotlight_upcoming_competition(*, series: str | None = None) -> Competition | None:
    """Nästa pick-race för spotlight (crowd pick), scoped per serie."""
    series_code = _normalize_countdown_series(series)
    if series_code:
        return _next_competition_for_picks(series=series_code, require_open=False)
    return _home_primary_competition(require_open=False)


def _p1_winners_for_comp(comp: Competition) -> list[tuple[Rider, CompetitionResult, str]]:
    """P1 per huvudklass — 450 + 250 (eller SX1 + SX2)."""
    is_wsx = (comp.series or "") == "WSX"
    class_specs = (
        [("wsx_sx1", "SX1"), ("wsx_sx2", "SX2")]
        if is_wsx
        else [("450cc", "450"), ("250cc", "250")]
    )
    winners: list[tuple[Rider, CompetitionResult, str]] = []
    for cls, badge in class_specs:
        rows = (
            db.session.query(CompetitionResult, Rider)
            .join(Rider, Rider.id == CompetitionResult.rider_id)
            .filter(CompetitionResult.competition_id == comp.id)
            .filter(CompetitionResult.position == 1)
            .filter(
                db.func.coalesce(CompetitionResult.class_name, Rider.class_name) == cls
            )
            .order_by(CompetitionResult.result_id.asc())
            .all()
        )
        for result, rider in rows:
            badge_final = badge
            if cls == "250cc":
                coast = (rider.coast_250 or "").strip().lower()
                if coast == "east":
                    badge_final = "250E"
                elif coast == "west":
                    badge_final = "250W"
            winners.append((rider, result, badge_final))
    return winners


def _riders_by_name_for(riders: list[Rider]) -> dict[str, list[Rider]]:
    """Namn → alla rader (450/250-dubletter) för porträttsökning."""
    from collections import defaultdict

    names = list({(r.name or "").strip() for r in riders if (r.name or "").strip()})
    by_name: dict[str, list[Rider]] = defaultdict(list)
    if not names:
        return by_name
    for row in rider_query_for_list_ui().filter(Rider.name.in_(names)).all():
        key = (row.name or "").strip().lower()
        if key:
            by_name[key].append(row)
    return by_name


def _patch_spotlight_portraits(
    modes: dict[str, dict[str, Any]],
    riders: list[Rider],
) -> None:
    """Sätt korrekta porträtt-URL:er (samma logik som bio/resultat)."""
    if not riders or not modes:
        return
    riders_by_name = _riders_by_name_for(riders)
    by_id = {int(r.id): r for r in riders}
    for mode in modes.values():
        for card in mode.get("riders") or []:
            r = by_id.get(int(card.get("rider_id") or 0))
            if not r:
                continue
            canon = _canonical_wsx_rider_name(getattr(r, "name", None))
            if canon and canon != (getattr(r, "name", None) or "").strip():
                card["name"] = canon
            url = template_rider_image_src(r, bio_card=True, riders_by_name=riders_by_name)
            if not url or "/brand_logos/" in str(url):
                wsx_rel = _wsx_static_portrait_rel(canon or getattr(r, "name", None))
                if wsx_rel:
                    url = f"/static/{wsx_rel}"
            if url:
                card["portrait_url"] = url


def _standing_points_for_comp_result(cr: CompetitionResult, comp: Competition) -> float:
    return float(_result_points_for_standing(cr, comp))


def _spotlight_rider_card(
    rider: Rider,
    *,
    comp: Competition | None = None,
    result: CompetitionResult | None = None,
    reason: str = "",
    subtitle: str = "",
    badge: str = "",
    badge_emoji: str = "🥇",
    season_year: int | None = None,
    extra_stats: list[str] | None = None,
    include_championship: bool = True,
) -> dict[str, Any]:
    year = season_year or _current_racing_season_year()
    bio_text = (getattr(rider, "bio_sv", None) or getattr(rider, "bio", None) or "").strip()
    bio_parts = _bio_content_parts(bio_text) if bio_text else {}
    hook = (bio_parts.get("hook") or bio_parts.get("full") or "")[:220]

    stats = list(extra_stats or [])
    if include_championship:
        championships = _rider_championship_standings(rider, year)
        sx_row = next((c for c in championships if c.get("series") == "SX"), None)
        mx_row = next((c for c in championships if c.get("series") == "MX"), None)
        wsx_row = next((c for c in championships if c.get("series") == "WSX"), None)
        if sx_row:
            stats.append(f'SX {year}: #{sx_row["rank"]} · {sx_row["points"]} p')
        if mx_row:
            stats.append(f'MX: #{mx_row["rank"]} · {mx_row["points"]} p')
        if wsx_row:
            stats.append(f'WSX: #{wsx_row["rank"]} · {wsx_row["points"]} p')

    pts = None
    if result and comp:
        pts = int(_standing_points_for_comp_result(result, comp))

    return {
        "rider_id": int(rider.id),
        "name": rider.name,
        "number": rider.rider_number,
        "class_label": _rider_directory_series_label(rider),
        "class_badge": badge,
        "brand": rider.bike_brand or "",
        "portrait_url": "",
        "profile_url": url_for("rider_profile", rider_id=int(rider.id)),
        "bio_hook": hook,
        "reason": reason,
        "subtitle": subtitle,
        "badge_emoji": badge_emoji,
        "points": pts,
        "position": int(result.position) if result else None,
        "stats": stats,
        "season_year": year,
    }


def _aggregate_pick_rates_for_comp(
    comp: Competition,
) -> tuple[int, dict[int, dict[str, Any]]]:
    """Andel lagn som plockat varje förare (snapshots eller live RacePick)."""
    import json
    from collections import Counter

    is_wsx = (comp.series or "") == "WSX"
    riders_dict = {r.id: r for r in rider_query_for_list_ui().all()}
    comp_id = int(comp.id)
    payloads: list[dict] = []

    snaps = PicksSnapshot.query.filter_by(competition_id=comp_id).all()
    if snaps:
        for s in snaps:
            try:
                payloads.append(json.loads(s.payload_json or "{}"))
            except Exception:
                payloads.append({})
    else:
        try:
            locked = is_picks_locked(comp)
        except Exception:
            locked = False
        if locked:
            try:
                ensure_picks_snapshots_for_competition(comp_id, source="auto_lock")
            except Exception:
                pass
            snaps = PicksSnapshot.query.filter_by(competition_id=comp_id).all()
            for s in snaps:
                try:
                    payloads.append(json.loads(s.payload_json or "{}"))
                except Exception:
                    payloads.append({})
        else:
            by_user: dict[int, list] = defaultdict(list)
            for p in RacePick.query.filter_by(competition_id=comp_id).all():
                by_user[int(p.user_id)].append(p)
            for uid in sorted(by_user.keys()):
                payloads.append(
                    {
                        "race_picks": [
                            {
                                "rider_id": p.rider_id,
                                "predicted_position": p.predicted_position,
                            }
                            for p in by_user[uid]
                        ]
                    }
                )

    n_lineups = 0
    picked: Counter[int] = Counter()
    p1_picks: Counter[int] = Counter()
    pos_counts: dict[int, Counter[int]] = defaultdict(Counter)

    for payload in payloads:
        race_picks = payload.get("race_picks") or []
        lineup_riders: set[int] = set()
        for p in race_picks:
            try:
                rid = int(p.get("rider_id"))
                pos = int(p.get("predicted_position"))
            except (TypeError, ValueError):
                continue
            r = riders_dict.get(rid)
            if not r:
                continue
            cls = (r.class_name or "").strip().lower()
            if is_wsx and cls not in ("wsx_sx1", "wsx_sx2"):
                continue
            if not is_wsx and cls not in ("450cc", "250cc"):
                continue
            lineup_riders.add(rid)
            if pos == 1:
                p1_picks[rid] += 1
            pos_counts[rid][pos] += 1
        if lineup_riders:
            n_lineups += 1
            for rid in lineup_riders:
                picked[rid] += 1

    if n_lineups <= 0:
        return 0, {}

    out: dict[int, dict[str, Any]] = {}
    for rid, cnt in picked.items():
        r = riders_dict.get(rid)
        if not r:
            continue
        common = pos_counts[rid].most_common(1)[0] if pos_counts.get(rid) else None
        out[rid] = {
            "picked_pct": round(100.0 * cnt / n_lineups, 1),
            "p1_pct": round(100.0 * p1_picks.get(rid, 0) / n_lineups, 1),
            "common_position": common[0] if common else None,
            "common_position_pct": (
                round(100.0 * common[1] / n_lineups, 1) if common else None
            ),
            "class_name": r.class_name,
            "class_group": (
                "450"
                if (r.class_name or "") in ("450cc", "wsx_sx1")
                else "250"
            ),
        }
    return n_lineups, out


def _championship_bucket_for_rider(
    cr: CompetitionResult,
    comp: Competition,
    rider: Rider,
    promoted_250_coasts: dict[str, str],
) -> tuple | None:
    """Bucket-nyckel för mästerskap — samma regler överallt (bio, resultat, spotlight)."""
    s = str(comp.series).strip() if comp.series is not None else ""
    if s not in ("WSX", "SX", "MX", "SMX"):
        return None
    if s == "WSX":
        rider_class = getattr(cr, "class_name", None) or rider.class_name
        if rider_class not in ("wsx_sx1", "wsx_sx2"):
            return None
        return ("wsx", rider_class)
    rider_class, result_coast = _standing_class_and_coast(
        cr, comp, rider, promoted_250_coasts
    )
    if rider_class == "450cc":
        return (s.lower(), "450")
    if rider_class == "250cc":
        rc = (result_coast or rider.coast_250 or "").strip().lower()
        if rc not in ("east", "west"):
            return None
        cc = (comp.coast_250 or "").strip().lower()
        # Pro Motocross: alla 250 kör tillsammans — äldre rader kan sakna coast_250.
        if s == "MX" and cc not in ("both", "showdown", "east", "west"):
            cc = "both"
        if s == "SMX":
            return ("smx", "250", rc)
        if cc in ("both", "showdown"):
            return (s.lower(), "250", rc)
        if cc in ("east", "west") and cc == rc:
            return (s.lower(), "250", rc)
    return None


def _points_by_bucket_for_competitions(
    comps: list[Competition],
) -> dict[tuple, dict[int, float]]:
    """Poäng per mästerskapsbucket för angivna tävlingar (t.ex. MX hittills)."""
    promoted = _promoted_250_coast_by_name()
    comp_ids = [int(c.id) for c in comps if c and c.id]
    if not comp_ids:
        return {}
    totals: dict[tuple, dict[int, float]] = defaultdict(lambda: defaultdict(float))
    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(Competition.id.in_(comp_ids))
        .all()
    )
    for cr, c, rider in rows:
        bucket = _championship_bucket_for_rider(cr, c, rider, promoted)
        if not bucket:
            continue
        totals[bucket][int(rider.id)] += _standing_points_for_comp_result(cr, c)
    return {k: dict(v) for k, v in totals.items()}


def _prior_comps_in_series(comp: Competition) -> list[Competition]:
    """Tidigare race i samma serie före detta event."""
    q = Competition.query.filter(Competition.series == comp.series)
    if comp.event_date:
        q = q.filter(
            Competition.event_date.isnot(None),
            Competition.event_date < comp.event_date,
        )
    else:
        q = q.filter(Competition.id != comp.id)
    return q.order_by(Competition.event_date.asc(), Competition.id.asc()).all()


def _spotlight_rocket_from_comp(
    comp: Competition,
    year: int,
) -> tuple[Rider, int, int, int] | None:
    """Förare med störst mästerskapsklättring efter senaste race i klassen."""
    promoted = _promoted_250_coast_by_name()
    prior = _prior_comps_in_series(comp)
    before_pts = _points_by_bucket_for_competitions(prior)
    after_pts = _points_by_bucket_for_competitions(prior + [comp])

    comp_rows = (
        db.session.query(CompetitionResult, Rider)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(CompetitionResult.competition_id == comp.id)
        .all()
    )

    best: tuple[Rider, int, int, int] | None = None
    best_climb = 0
    for cr_row, rider in comp_rows:
        bucket = _championship_bucket_for_rider(cr_row, comp, rider, promoted)
        if not bucket:
            continue
        rid = int(rider.id)
        before_map = before_pts.get(bucket) or {}
        after_map = after_pts.get(bucket) or {}
        if rid not in after_map:
            continue
        rank_before = _rank_in_points_map(before_map, rid)
        rank_after = _rank_in_points_map(after_map, rid)
        if not rank_after or not rank_before:
            continue
        rb = int(rank_before["rank"])
        ra = int(rank_after["rank"])
        climb = rb - ra
        if climb > best_climb:
            best_climb = climb
            best = (rider, climb, rb, ra)

    return best


def _spotlight_dark_horse_from_comp(
    comp: Competition,
) -> tuple[Rider, CompetitionResult, float] | None:
    """Topp 5 med låg pick-rate — ingen såg det komma."""
    n_lineups, rates = _aggregate_pick_rates_for_comp(comp)
    if n_lineups < 2:
        return None

    rows = (
        db.session.query(CompetitionResult, Rider)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(CompetitionResult.competition_id == comp.id)
        .filter(CompetitionResult.position <= 5)
        .order_by(CompetitionResult.position.asc())
        .all()
    )
    best: tuple[Rider, CompetitionResult, float] | None = None
    best_score = -1.0
    for result, rider in rows:
        rate = rates.get(int(rider.id))
        if not rate:
            continue
        pct = float(rate.get("picked_pct") or 100.0)
        if pct > 20.0:
            continue
        pos = int(result.position)
        score = (6 - pos) * (100.0 - pct)
        if score > best_score:
            best_score = score
            best = (rider, result, pct)
    return best


def _spotlight_crowd_cards(comp: Competition) -> list[dict[str, Any]]:
    n_lineups, rates = _aggregate_pick_rates_for_comp(comp)
    if n_lineups < 2 or not rates:
        return []

    is_wsx = (comp.series or "") == "WSX"
    groups = ("450", "250") if not is_wsx else ("450", "250")
    group_labels = {"450": "SX1" if is_wsx else "450", "250": "SX2" if is_wsx else "250"}
    cards: list[dict[str, Any]] = []
    year = (
        int(comp.event_date.year)
        if comp.event_date
        else _current_racing_season_year()
    )

    for grp in groups:
        candidates = [
            (rid, data)
            for rid, data in rates.items()
            if data.get("class_group") == grp
        ]
        if not candidates:
            continue
        rid, data = max(candidates, key=lambda x: (x[1]["picked_pct"], x[1]["p1_pct"]))
        rider = Rider.query.get(int(rid))
        if not rider:
            continue
        badge = group_labels[grp]
        common_pos = data.get("common_position")
        common_pct = data.get("common_position_pct")

        def _pct_label(v: float | int | None) -> str:
            if v is None:
                return "0"
            n = float(v)
            return f"{n:.0f}" if abs(n - round(n)) < 0.05 else f"{n:.1f}"

        stat_chips: list[str] = [f'{_pct_label(data["picked_pct"])}% i lag']
        if data.get("p1_pct"):
            stat_chips.append(f'{_pct_label(data["p1_pct"])}% P1')
        if common_pos and common_pct:
            stat_chips.append(f'oftast P{common_pos}')
        cards.append(
            _spotlight_rider_card(
                rider,
                comp=comp,
                reason=f"Folkets favorit — {badge}",
                subtitle="",
                badge=badge,
                badge_emoji="🔥",
                season_year=year,
                extra_stats=stat_chips,
                include_championship=False,
            )
        )
    return cards


def _spotlight_mode_needs_portrait_refresh(mode: dict) -> bool:
    """Only force rebuild for empty/bad typo URLs — not every brand-logo fallback.

    Treating brand_logos as always-stale caused perpetual spotlight rebuilds on
    every homepage hit (1 gunicorn worker → intermittent 500 under load).
    """
    if int(mode.get("_portrait_v") or 0) < _SPOTLIGHT_PORTRAIT_CACHE_V:
        return True
    for card in mode.get("riders") or []:
        url = str(card.get("portrait_url") or "")
        if not url:
            return True
        # Legacy typo path that 404s in prod (Jason Andersson)
        if "andersson" in url.lower() or str(card.get("name") or "") == "Jason Andersson":
            return True
    return False


def _spotlight_shell_stale(payload: dict, *, series: str | None = None) -> bool:
    """Rebuild shell when crowd-tab or latest completed race no longer matches cache."""
    if not payload.get("available"):
        return False
    lazy = payload.get("lazy_modes") or []
    modes = payload.get("modes") or {}
    has_crowd_tab = "crowd_pick" in lazy or "crowd_pick" in modes
    upcoming = _spotlight_upcoming_competition(series=series)
    try:
        locked = is_picks_locked(upcoming) if upcoming else True
    except Exception:
        locked = True
    crowd_ok = bool(
        upcoming and not locked and _crowd_spotlight_ready(upcoming)
    )
    if has_crowd_tab != crowd_ok:
        return True

    # Stale "Senaste race" after new results (per-series cache can linger otherwise).
    last_comp = _last_completed_competition(series=series)
    lr = modes.get("last_race") or {}
    headline = str(lr.get("headline") or "")
    if last_comp and headline and last_comp.name and last_comp.name not in headline:
        return True
    if last_comp and not lr and "last_race" not in lazy:
        # Shell claims last_race available but never loaded and not lazy — odd; rebuild.
        available_keys = payload.get("mode_tabs") or []
        if any((t.get("key") == "last_race") for t in available_keys):
            return True
    return False


def _spotlight_cache_needs_refresh(payload: dict) -> bool:
    """Äldre cache kan sakna porträtt-URL efter bildfix."""
    if not payload.get("available"):
        return False
    for mode in (payload.get("modes") or {}).values():
        if _spotlight_mode_needs_portrait_refresh(mode):
            return True
    return False


def _spotlight_season_year(last_comp: Competition | None) -> int:
    if last_comp and last_comp.event_date:
        return int(last_comp.event_date.year)
    return _current_racing_season_year()


def _crowd_pick_lineup_count(comp: Competition) -> int:
    """Antal unika spelare med minst ett race pick till tävlingen."""
    comp_id = int(comp.id)
    snap_users = (
        db.session.query(db.func.count(db.distinct(PicksSnapshot.user_id)))
        .filter(PicksSnapshot.competition_id == comp_id)
        .scalar()
        or 0
    )
    if snap_users >= 2:
        return int(snap_users)
    return (
        db.session.query(db.func.count(db.distinct(RacePick.user_id)))
        .filter(RacePick.competition_id == comp_id)
        .scalar()
        or 0
    )


def _crowd_spotlight_ready(comp: Competition) -> bool:
    return _crowd_pick_lineup_count(comp) >= 2


def _spotlight_available_mode_keys(
    last_comp: Competition | None,
    upcoming: Competition | None,
) -> list[str]:
    keys: list[str] = []
    if last_comp:
        keys.extend(["last_race", "rocket", "dark_horse"])
    if upcoming:
        try:
            locked = is_picks_locked(upcoming)
        except Exception:
            locked = True
        if not locked and _crowd_spotlight_ready(upcoming):
            keys.append("crowd_pick")
    return keys


def _spotlight_default_mode_key(
    available: list[str],
    upcoming: Competition | None,
) -> str:
    default_mode = "last_race"
    if "crowd_pick" in available and upcoming and upcoming.event_date:
        days = (upcoming.event_date - get_today()).days
        if 0 <= days <= 7:
            default_mode = "crowd_pick"
    if default_mode not in available and available:
        default_mode = available[0]
    return default_mode


def _build_spotlight_mode_data(
    mode_key: str,
    *,
    last_comp: Competition | None,
    upcoming: Competition | None,
    season_year: int,
) -> tuple[dict[str, Any] | None, list[Rider]]:
    riders: list[Rider] = []

    if mode_key == "last_race" and last_comp:
        winners = _p1_winners_for_comp(last_comp)
        if not winners:
            return None, []
        race_cards = []
        for rider, result, badge in winners:
            riders.append(rider)
            if (last_comp.series or "") == "WSX":
                pts = (
                    int(result.rider_points)
                    if result.rider_points is not None
                    else int(get_smx_qualification_points(result.position))
                )
            else:
                pts = int(_result_points_for_standing(result, last_comp))
            race_cards.append(
                _spotlight_rider_card(
                    rider,
                    comp=last_comp,
                    result=result,
                    reason=f"Vann {last_comp.name} · {pts} p",
                    badge=badge,
                    badge_emoji="🥇",
                    season_year=season_year,
                )
            )
        meta = _SPOTLIGHT_TAB_META["last_race"]
        return {
            "available": True,
            "label": meta["label"],
            "icon": meta["icon"],
            "headline": f"Vinnare — {last_comp.name}",
            "riders": race_cards,
        }, riders

    if mode_key == "rocket" and last_comp:
        rocket_hit = _spotlight_rocket_from_comp(last_comp, season_year)
        if not rocket_hit or rocket_hit[1] <= 0:
            return None, []
        rider, climb, rb, ra = rocket_hit
        riders.append(rider)
        meta = _SPOTLIGHT_TAB_META["rocket"]
        return {
            "available": True,
            "label": meta["label"],
            "icon": meta["icon"],
            "headline": "Störst klättring i mästerskapet",
            "riders": [
                _spotlight_rider_card(
                    rider,
                    comp=last_comp,
                    reason=f"Klättrade {climb} platser efter {last_comp.name}",
                    subtitle=f"Mästerskap: #{rb} → #{ra}",
                    badge_emoji="🚀",
                    season_year=season_year,
                    extra_stats=[],
                    include_championship=False,
                )
            ],
        }, riders

    if mode_key == "dark_horse" and last_comp:
        dark = _spotlight_dark_horse_from_comp(last_comp)
        if not dark:
            return None, []
        rider, result, pct = dark
        riders.append(rider)
        meta = _SPOTLIGHT_TAB_META["dark_horse"]
        return {
            "available": True,
            "label": meta["label"],
            "icon": meta["icon"],
            "headline": "Ingen såg det komma",
            "riders": [
                _spotlight_rider_card(
                    rider,
                    comp=last_comp,
                    result=result,
                    reason=f"P{result.position} i {last_comp.name} — bara {pct}% hade honom",
                    subtitle="Alla tror på stjärnorna — han levererade ändå",
                    badge_emoji="🌙",
                    season_year=season_year,
                    extra_stats=[],
                    include_championship=False,
                )
            ],
        }, riders

    if mode_key == "crowd_pick" and upcoming:
        try:
            if is_picks_locked(upcoming):
                return None, []
        except Exception:
            return None, []
        crowd_cards = _spotlight_crowd_cards(upcoming)
        if not crowd_cards:
            return None, []
        for card in crowd_cards:
            rid = int(card.get("rider_id") or 0)
            if rid:
                row = rider_query_for_list_ui().filter_by(id=rid).first()
                if row:
                    riders.append(row)
        meta = _SPOTLIGHT_TAB_META["crowd_pick"]
        return {
            "available": True,
            "label": meta["label"],
            "icon": meta["icon"],
            "headline": f"Folkets favorit inför {upcoming.name}",
            "riders": crowd_cards,
        }, riders

    return None, []


def build_spotlight_mode(
    mode_key: str,
    *,
    series: str | None = None,
) -> dict[str, Any] | None:
    """Bygg ett spotlight-läge (cachad per flik + serie + race-id)."""
    series_code = _normalize_countdown_series(series)
    last_comp = _last_completed_competition(series=series_code)
    upcoming = _spotlight_upcoming_competition(series=series_code)
    last_id = int(last_comp.id) if last_comp else 0
    up_id = int(upcoming.id) if upcoming else 0
    # Bind cache to the competition that backs the mode so new results cannot reuse
    # an older "Senaste race" payload (seen on SMX after Playoff 2 import).
    if mode_key == "crowd_pick":
        cache_key = f"{_spotlight_series_cache_key(series_code)}:{mode_key}:u{up_id}"
    else:
        cache_key = f"{_spotlight_series_cache_key(series_code)}:{mode_key}:c{last_id}"
    now = time.time()
    cached = _RIDER_SPOTLIGHT_MODE_CACHE.get(cache_key)
    if cached and cached[0] > now:
        mode_data = cached[1]
        if mode_key == "rocket" and int(mode_data.get("_calc_v") or 0) < 3:
            pass
        elif mode_key == "crowd_pick" and int(mode_data.get("_calc_v") or 0) < 2:
            pass
        elif not _spotlight_mode_needs_portrait_refresh(mode_data):
            return mode_data

    season_year = _spotlight_season_year(last_comp)
    mode_data, riders = _build_spotlight_mode_data(
        mode_key,
        last_comp=last_comp,
        upcoming=upcoming,
        season_year=season_year,
    )
    if not mode_data:
        return None

    _patch_spotlight_portraits({mode_key: mode_data}, riders)
    mode_data["_portrait_v"] = _SPOTLIGHT_PORTRAIT_CACHE_V
    if last_comp:
        mode_data["_comp_id"] = int(last_comp.id)
        mode_data["_comp_name"] = last_comp.name
    if mode_key == "rocket":
        mode_data["_calc_v"] = 3
    if mode_key == "crowd_pick":
        mode_data["_calc_v"] = 2
    _RIDER_SPOTLIGHT_MODE_CACHE[cache_key] = (now + _HOMEPAGE_CACHE_TTL, mode_data)
    return mode_data


def build_rider_spotlight(*, series: str | None = None) -> dict[str, Any]:
    """Spotlight-shell: metadata + endast standardflik (övriga laddas lazy)."""
    series_code = _normalize_countdown_series(series)
    cache_key = _spotlight_series_cache_key(series_code)
    now = time.time()
    entry = _RIDER_SPOTLIGHT_CACHE.get(cache_key)
    if entry and entry[0] > now:
        cached = entry[1]
        if not _spotlight_cache_needs_refresh(cached) and not _spotlight_shell_stale(
            cached, series=series_code
        ):
            return cached

    last_comp = _last_completed_competition(series=series_code)
    upcoming = _spotlight_upcoming_competition(series=series_code)
    available = _spotlight_available_mode_keys(last_comp, upcoming)
    if not available:
        payload = {"available": False, "series": series_code}
        _RIDER_SPOTLIGHT_CACHE[cache_key] = (now + _HOMEPAGE_CACHE_TTL, payload)
        return payload

    default_mode = _spotlight_default_mode_key(available, upcoming)
    default_data = build_spotlight_mode(default_mode, series=series_code)
    if not default_data:
        fallback = next((k for k in available if k != default_mode), None)
        if fallback:
            default_mode = fallback
            default_data = build_spotlight_mode(default_mode, series=series_code)
    if not default_data:
        payload = {"available": False, "series": series_code}
        _RIDER_SPOTLIGHT_CACHE[cache_key] = (now + _HOMEPAGE_CACHE_TTL, payload)
        return payload

    mode_tabs = [
        {**_SPOTLIGHT_TAB_META[k], "key": k}
        for k in ("last_race", "crowd_pick", "rocket", "dark_horse")
        if k in available
    ]
    payload = {
        "available": True,
        "title": "I rampljuset",
        "series": series_code,
        "default_mode": default_mode,
        "mode_tabs": mode_tabs,
        "lazy_modes": [k for k in available if k != default_mode],
        "modes": {default_mode: default_data},
    }
    _RIDER_SPOTLIGHT_CACHE[cache_key] = (now + _HOMEPAGE_CACHE_TTL, payload)
    return payload


def build_rider_game_context(rider: Rider) -> dict[str, Any]:
    """Plockstatistik + senaste race — kopplar biosidan till fantasy."""
    series = _picks_series_for_rider(rider)
    upcoming = _next_competition_for_picks(series=series, require_open=False)
    upcoming_block: dict[str, Any] | None = None
    if upcoming:
        stats = _rider_pick_stats_for_comp(rider, upcoming) or {}
        upcoming_block = {
            "comp_name": upcoming.name,
            "comp_id": int(upcoming.id),
            "picks_open": not is_picks_locked(upcoming),
            "picks_url": url_for("race_picks_page", competition_id=upcoming.id),
            "lineups": int(stats.get("lineups") or 0),
            "picked_count": int(stats.get("picked_count") or 0),
            "picked_pct": stats.get("picked_pct"),
            "p1_pct": stats.get("p1_pct"),
            "common_position": stats.get("common_position"),
            "common_position_pct": stats.get("common_position_pct"),
            "holeshot_pct": stats.get("holeshot_pct"),
        }

    recent = _rider_recent_race_results(int(rider.id))
    season_year = _current_racing_season_year()
    championships = _rider_championship_standings(rider, season_year)
    return {
        "season_year": season_year,
        "upcoming": upcoming_block,
        "recent_results": recent,
        "championships": championships,
        "has_any": bool(upcoming_block or recent or championships),
    }


def _rider_brand_logo_url(bike_brand: str | None) -> str | None:
    if not bike_brand:
        return None
    brand = str(bike_brand).lower().strip()
    brand_map = {
        "honda": "honda",
        "ktm": "ktm",
        "yamaha": "yamaha",
        "kawasaki": "kawasaki",
        "suzuki": "suzuki",
        "husqvarna": "husqvarna",
        "gasgas": "gasgas",
        "beta": "beta",
        "triumph": "triumph",
    }
    logo = brand_map.get(brand, brand)
    return f"/static/brand_logos/{logo}.png"


# Public rider profile
@app.get('/rider/<int:rider_id>')
def rider_profile(rider_id: int):
    from sqlalchemy.orm import defer
    from racerx_rider_bio import ensure_rider_content_from_twins, resolve_rider_bio_source

    rider = (
        Rider.query.options(
            defer(Rider.rider_image_data),
        )
        .filter_by(id=rider_id)
        .first_or_404()
    )
    from racerx_rider_bio import build_riders_by_name_map, find_rider_twins, twin_group_key

    twins = find_rider_twins(rider)
    twins_by_name = build_riders_by_name_map(twins) if twins else None
    try:
        if ensure_rider_content_from_twins(rider, riders=twins):
            db.session.commit()
            db.session.refresh(rider)
    except Exception as exc:
        db.session.rollback()
        print(f"ensure_rider_content_from_twins: {exc}")
    bio_source = resolve_rider_bio_source(rider, riders=twins)
    img_map = twins_by_name
    if img_map is None and twins:
        key = twin_group_key(rider.name or "", rider.rider_number)
        if key:
            img_map = {key: twins}
    bio_en = _bio_content_parts(bio_source.bio)
    bio_sv_raw = (bio_source.bio_sv or "").strip()
    bio_sv = _bio_content_parts(bio_sv_raw) if bio_sv_raw else {"hook": "", "body": "", "full": ""}
    resp = make_response(
        render_template(
        'rider_detail.html',
        rider=rider,
        bio_source=bio_source,
        series_label=_rider_directory_series_label(rider),
        brand_logo_url=_rider_brand_logo_url(rider.bike_brand),
        bio_en=bio_en,
        bio_sv=bio_sv,
        achievements_en=(bio_source.achievements or "").strip(),
        achievements_sv=(bio_source.achievements_sv or "").strip(),
        rider_image_src=template_rider_image_src(
            rider, bio_card=True, riders_by_name=img_map
        ),
        game_context=build_rider_game_context(rider),
        username=session.get('username'),
        )
    )
    resp.headers['Cache-Control'] = 'no-store'
    return resp


@app.get('/api/rider/<int:rider_id>/bio')
def rider_bio_i18n(rider_id: int):
    """Bio/meriter på engelska eller svenska (översätter och cachar vid behov)."""
    from racerx_rider_bio import resolve_rider_bio_source

    from sqlalchemy.orm import defer

    rider = Rider.query.options(defer(Rider.rider_image_data)).get_or_404(rider_id)
    bio_source = resolve_rider_bio_source(rider)
    lang = (request.args.get("lang") or "sv").strip().lower()
    if lang not in ("en", "sv"):
        lang = "sv"
    if lang == "en":
        return jsonify({
            "ok": True,
            "lang": "en",
            "bio": bio_source.bio or "",
            "achievements": bio_source.achievements or "",
        })
    try:
        from rider_bio_translate import ensure_swedish_bio

        bio_sv, ach_sv = ensure_swedish_bio(bio_source)
        db.session.commit()
        return jsonify({
            "ok": True,
            "lang": "sv",
            "bio": bio_sv,
            "achievements": ach_sv,
        })
    except Exception as exc:
        db.session.rollback()
        print(f"rider bio translate error: {exc}")
        return jsonify({
            "ok": False,
            "error": "translate_failed",
            "bio": bio_source.bio or "",
            "achievements": bio_source.achievements or "",
        }), 502

def _rider_directory_sort_key(rider: Rider) -> tuple:
    num = rider.rider_number if rider.rider_number is not None else 99999
    return (num, (rider.name or "").lower())


def _rider_directory_series_label(rider: Rider) -> str:
    cls = (rider.class_name or "").strip().lower()
    if cls == "wsx_sx1":
        return "WSX SX1"
    if cls == "wsx_sx2":
        return "WSX SX2"
    if cls in ("450cc", "450"):
        return "450"
    if cls in ("250cc", "250"):
        coast = (rider.coast_250 or "").strip().lower()
        if coast == "east":
            return "250E"
        if coast == "west":
            return "250W"
        if coast == "both":
            return "250"
        return "250?"
    return cls.upper() or "?"


def _group_riders_for_directory(riders: list[Rider] | None = None) -> dict[str, list[Rider]]:
    """
    Build /riders columns from DB (live query, no cache).
    WSX has its own columns (not mixed with AMA 450/250).
    250cc with coast 'both' appears in both 250E and 250W (same as race picks).
  """
    if riders is None:
        riders = rider_query_for_list_ui().order_by(Rider.id).all()
    riders_450: list[Rider] = []
    riders_250_east: list[Rider] = []
    riders_250_west: list[Rider] = []
    riders_250_unassigned: list[Rider] = []
    riders_wsx_sx1: list[Rider] = []
    riders_wsx_sx2: list[Rider] = []
    seen_east: set[int] = set()
    seen_west: set[int] = set()

    for rider in riders:
        cls = (rider.class_name or "").strip().lower()
        if cls == "wsx_sx1":
            riders_wsx_sx1.append(rider)
            continue
        if cls == "wsx_sx2":
            riders_wsx_sx2.append(rider)
            continue
        if cls in ("450cc", "450"):
            riders_450.append(rider)
            continue
        if cls not in ("250cc", "250"):
            continue
        coast = (rider.coast_250 or "").strip().lower()
        if coast in ("east", "both"):
            riders_250_east.append(rider)
            seen_east.add(rider.id)
        if coast in ("west", "both"):
            riders_250_west.append(rider)
            seen_west.add(rider.id)
        if rider.id not in seen_east and rider.id not in seen_west:
            riders_250_unassigned.append(rider)

    key = _rider_directory_sort_key
    for bucket in (
        riders_450,
        riders_250_east,
        riders_250_west,
        riders_250_unassigned,
        riders_wsx_sx1,
        riders_wsx_sx2,
    ):
        bucket.sort(key=key)
    return {
        "riders_450": riders_450,
        "riders_250_east": riders_250_east,
        "riders_250_west": riders_250_west,
        "riders_250_unassigned": riders_250_unassigned,
        "riders_wsx_sx1": riders_wsx_sx1,
        "riders_wsx_sx2": riders_wsx_sx2,
    }


