@app.route("/admin_old")
def admin_page_old():
    if not is_admin_user():
        return redirect(url_for("index"))
    competitions = Competition.query.order_by(Competition.event_date).all()
    riders_450 = Rider.query.filter_by(class_name="450cc").order_by(Rider.rider_number).all()
    
    # For admin page, we need ALL 250cc riders (not filtered by coast)
    # Coast filtering will be handled by JavaScript based on selected competition
    riders_250 = Rider.query.filter_by(class_name="250cc").order_by(Rider.rider_number).all()

    # Serialize riders data for JavaScript
    def serialize_rider(r: Rider):
        return {
            "id": r.id,
            "name": r.name,
            "class_name": r.class_name,
            "rider_number": r.rider_number,
            "bike_brand": r.bike_brand,
            "coast_250": r.coast_250,
        }

    riders_250_json = [serialize_rider(r) for r in riders_250]

    # Create competition coast map for JavaScript
    comp_coast_map = {}
    for comp in competitions:
        comp_coast_map[comp.id] = comp.coast_250

    race_scores = []
    last_scored = (
        db.session.query(CompetitionScore.competition_id)
        .join(Competition, Competition.id == CompetitionScore.competition_id)
        .order_by(Competition.event_date.desc())
        .first()
    )
    if last_scored:
        last_comp_id = last_scored[0]
        race_scores = (
            db.session.query(User.username, CompetitionScore.total_points)
            .join(User, User.id == CompetitionScore.user_id)
            .filter(CompetitionScore.competition_id == last_comp_id)
            .order_by(CompetitionScore.total_points.desc())
            .all()
        )

    return render_template(
        "admin_new.html",
        competitions=competitions,
        riders_450=riders_450,
        riders_250=riders_250,
        riders_250_json=riders_250_json,
        comp_coast_map=comp_coast_map,
        race_scores=race_scores,
        today=get_today(),
    )


@app.get("/admin/get_results/<int:competition_id>")
def admin_get_results(competition_id):
    if not is_admin_user():
        return jsonify({"error": "unauthorized"}), 403

    try:
        # Getting admin results

        results = (
            db.session.query(
                CompetitionResult.rider_id,
                CompetitionResult.position,
                CompetitionResult.rider_points,
                db.func.coalesce(CompetitionResult.class_name, Rider.class_name).label("class_name"),
                Rider.name.label("rider_name"),
                Rider.rider_number.label("rider_number"),
            )
            .join(Rider, Rider.id == CompetitionResult.rider_id)
            .filter(CompetitionResult.competition_id == competition_id)
            .order_by(CompetitionResult.position.asc())
            .all()
        )

        holos = (
            db.session.query(
                HoleshotResult.rider_id,
                HoleshotResult.class_name,
                Rider.name.label("rider_name"),
                Rider.rider_number.label("rider_number"),
            )
            .join(Rider, Rider.id == HoleshotResult.rider_id)
            .filter(HoleshotResult.competition_id == competition_id)
            .all()
        )

        # Get competition to determine series
        competition = Competition.query.get(competition_id)
        is_wsx = competition and competition.series == 'WSX'
        
        # Debug: Log all results
        print(f"🔍 DEBUG admin_get_results: Found {len(results)} results for competition {competition_id} (WSX: {is_wsx})")
        
        # Calculate points for each result (same logic as race_results_page)
        top_results_with_points = []
        for r in results:
            # Calculate points: use rider_points if provided (manual entry), otherwise calculate from position
            if is_wsx:
                if r.rider_points is not None:
                    points = r.rider_points
                else:
                    points = get_smx_qualification_points(r.position)
            else:
                points = get_smx_qualification_points(r.position)
            
            top_results_with_points.append({
                "rider_id": r.rider_id,
                "position": r.position,
                "class": r.class_name,
                "rider_name": r.rider_name,
                "rider_number": r.rider_number,
                "rider_points": r.rider_points,  # Keep original (may be None)
                "calculated_points": points  # Always calculated
            })
            print(f"  - Position {r.position}: {r.rider_name} (ID: {r.rider_id}, class: {r.class_name}, rider_points: {r.rider_points}, calculated: {points})")

        # Found results and holeshot results

        return jsonify(
            {
                "top_results": top_results_with_points,
                "holeshot_results": [
                    {
                        "rider_id": h.rider_id,
                        "class": h.class_name,
                        "rider_name": h.rider_name,
                        "rider_number": h.rider_number
                    }
                    for h in holos
                ],
            }
        )
    except Exception as e:
        # Error in admin_get_results
        import traceback
        traceback.print_exc()
        return jsonify({"error": "internal_error"}), 500

def _competition_picks_assessment(comp: Competition) -> dict:
    """Per-user pick completeness for admin stats (matches homepage has_picks rules)."""
    series_u = (comp.series or "").upper()
    is_wsx = series_u == "WSX"
    is_mxon = series_u == "MXON"
    comp_id = int(comp.id)

    if is_mxon:
        nation_rows = MxonNationPick.query.filter_by(competition_id=comp_id).all()
        class_rows = MxonClassPick.query.filter_by(competition_id=comp_id).all()
        nation_by_user: dict[int, set[int]] = {}
        for p in nation_rows:
            nation_by_user.setdefault(int(p.user_id), set()).add(int(p.position or 0))
        class_by_user: dict[int, set[str]] = {}
        for p in class_rows:
            class_by_user.setdefault(int(p.user_id), set()).add(
                (p.class_name or "").strip().lower()
            )

        all_user_ids = set(nation_by_user) | set(class_by_user)
        users_by_id = {}
        if all_user_ids:
            users_by_id = {u.id: u for u in User.query.filter(User.id.in_(all_user_ids)).all()}

        rows = []
        for uid in sorted(all_user_ids):
            user = users_by_id.get(uid)
            n_count = len(nation_by_user.get(uid, set()))
            c_set = class_by_user.get(uid, set())
            c_count = len(c_set)
            missing: list[str] = []
            if n_count < 5:
                missing.append(f"Nationer: {n_count}/5")
            for key, label in (("mxgp", "MXGP"), ("mx2", "MX2"), ("open", "OPEN")):
                if key not in c_set:
                    missing.append(f"Klassfavorit {label}")
            if n_count >= 5 and c_count >= 3:
                status = "complete"
            elif n_count or c_count:
                status = "partial"
            else:
                status = "none"
            rows.append(
                {
                    "user_id": uid,
                    "username": user.username if user else f"#{uid}",
                    "display_name": (user.display_name if user else None)
                    or (user.username if user else f"#{uid}"),
                    "status": status,
                    "race_450": n_count,  # reuse UI slots: nations / class picks
                    "race_250": c_count,
                    "holeshot_450": "mxgp" in c_set,
                    "holeshot_250": "mx2" in c_set,
                    "wildcard_position": "open" in c_set,
                    "wildcard_rider": "open" in c_set,
                    "nations": n_count,
                    "class_favorites": c_count,
                    "missing": missing,
                }
            )

        complete = [r for r in rows if r["status"] == "complete"]
        partial = [r for r in rows if r["status"] == "partial"]
        total_users = User.query.count()
        return {
            "is_wsx": False,
            "is_mxon": True,
            "label_450": "Nationer",
            "label_250": "Klassfavoriter",
            "users_complete": len(complete),
            "users_partial": len(partial),
            "users_started": len(rows),
            "users_not_started": max(0, total_users - len(rows)),
            "total_users": total_users,
            "complete_pct": round((len(complete) / total_users * 100) if total_users > 0 else 0, 1),
            "started_pct": round((len(rows) / total_users * 100) if total_users > 0 else 0, 1),
            "users_complete_list": complete,
            "users_partial_list": partial,
        }

    class_450 = "wsx_sx1" if is_wsx else "450cc"
    class_250 = "wsx_sx2" if is_wsx else "250cc"
    label_450 = "SX1" if is_wsx else "450cc"
    label_250 = "SX2" if is_wsx else "250cc"

    race_picks = RacePick.query.filter_by(competition_id=comp_id).order_by(RacePick.pick_id).all()
    holeshots = HoleshotPick.query.filter_by(competition_id=comp_id).all()
    wildcards = {
        wc.user_id: wc
        for wc in WildcardPick.query.filter_by(competition_id=comp_id).all()
    }

    rider_ids = {p.rider_id for p in race_picks}
    rider_ids.update(h.rider_id for h in holeshots)
    rider_ids.update(wc.rider_id for wc in wildcards.values() if wc.rider_id)
    riders_by_id = {}
    if rider_ids:
        riders_by_id = {r.id: r for r in Rider.query.filter(Rider.id.in_(rider_ids)).all()}

    race_by_user: dict[int, dict[int, RacePick]] = {}
    for pick in race_picks:
        uid = int(pick.user_id)
        rid = int(pick.rider_id)
        bucket = race_by_user.setdefault(uid, {})
        if rid not in bucket or pick.pick_id > bucket[rid].pick_id:
            bucket[rid] = pick

    holeshot_by_user: dict[int, dict[str, bool]] = {}
    for hs in holeshots:
        uid = int(hs.user_id)
        rider = riders_by_id.get(hs.rider_id)
        if not rider:
            continue
        cls = (rider.class_name or "").strip().lower()
        flags = holeshot_by_user.setdefault(uid, {class_450: False, class_250: False})
        if cls in (class_450, "450cc", "wsx_sx1"):
            flags[class_450] = True
        elif cls in (class_250, "250cc", "wsx_sx2"):
            flags[class_250] = True

    all_user_ids = set(race_by_user) | set(holeshot_by_user) | set(wildcards)
    users_by_id = {}
    if all_user_ids:
        users_by_id = {u.id: u for u in User.query.filter(User.id.in_(all_user_ids)).all()}

    def _user_row(uid: int) -> dict:
        user = users_by_id.get(uid)
        picks_map = race_by_user.get(uid, {})
        n450 = 0
        n250 = 0
        for pick in picks_map.values():
            rider = riders_by_id.get(pick.rider_id)
            if not rider:
                continue
            cls = (rider.class_name or "").strip().lower()
            if cls in (class_450, "450cc", "wsx_sx1"):
                n450 += 1
            elif cls in (class_250, "250cc", "wsx_sx2"):
                n250 += 1

        hs_flags = holeshot_by_user.get(uid, {class_450: False, class_250: False})
        wc = wildcards.get(uid)
        wc_pos = bool(wc and wc.position is not None)
        wc_rider = bool(wc and wc.rider_id)

        race_complete = n450 == 6 and n250 == 6
        holeshot_complete = hs_flags[class_450] and hs_flags[class_250]
        if is_wsx:
            wildcard_complete = True
        else:
            wildcard_complete = wc_pos and wc_rider

        missing: list[str] = []
        if n450 < 6:
            missing.append(f"{label_450}: {n450}/6")
        if n250 < 6:
            missing.append(f"{label_250}: {n250}/6")
        if not hs_flags[class_450]:
            missing.append(f"Holeshot {label_450}")
        if not hs_flags[class_250]:
            missing.append(f"Holeshot {label_250}")
        if not is_wsx:
            if not wc_pos:
                missing.append("Wildcard position")
            elif not wc_rider:
                missing.append("Wildcard förare")

        if race_complete and holeshot_complete and wildcard_complete:
            status = "complete"
        elif n450 or n250 or hs_flags[class_450] or hs_flags[class_250] or wc_pos or wc_rider:
            status = "partial"
        else:
            status = "none"

        return {
            "user_id": uid,
            "username": user.username if user else f"#{uid}",
            "display_name": (user.display_name if user else None) or (user.username if user else f"#{uid}"),
            "status": status,
            "race_450": n450,
            "race_250": n250,
            "holeshot_450": hs_flags[class_450],
            "holeshot_250": hs_flags[class_250],
            "wildcard_position": wc_pos,
            "wildcard_rider": wc_rider,
            "missing": missing,
        }

    rows = [_user_row(uid) for uid in sorted(all_user_ids)]
    complete = [r for r in rows if r["status"] == "complete"]
    partial = [r for r in rows if r["status"] == "partial"]
    total_users = User.query.count()

    return {
        "is_wsx": is_wsx,
        "is_mxon": False,
        "label_450": label_450,
        "label_250": label_250,
        "users_complete": len(complete),
        "users_partial": len(partial),
        "users_started": len(rows),
        "users_not_started": max(0, total_users - len(rows)),
        "total_users": total_users,
        "complete_pct": round((len(complete) / total_users * 100) if total_users > 0 else 0, 1),
        "started_pct": round((len(rows) / total_users * 100) if total_users > 0 else 0, 1),
        "users_complete_list": complete,
        "users_partial_list": partial,
    }


def _admin_picks_stats_payload(comp: Competition) -> dict:
    """JSON payload for admin picks statistics (one competition)."""
    assessment = _competition_picks_assessment(comp)
    sched: dict = {}
    try:
        sched = _competition_race_schedule(comp) or {}
    except Exception:
        pass
    has_results = (
        CompetitionResult.query.filter_by(competition_id=comp.id).first() is not None
    )
    return {
        "success": True,
        "competition_id": comp.id,
        "competition_name": comp.name,
        "series": comp.series,
        "event_date": comp.event_date.isoformat() if comp.event_date else None,
        "picks_locked": is_picks_locked(comp),
        "has_results": has_results,
        "deadline_display": sched.get("pick_deadline_display"),
        "race_display": sched.get("race_display") or sched.get("start_display"),
        "is_wsx": assessment["is_wsx"],
        "is_mxon": assessment.get("is_mxon", False),
        "label_450": assessment.get("label_450"),
        "label_250": assessment.get("label_250"),
        "total_users": assessment["total_users"],
        "users_complete": assessment["users_complete"],
        "users_partial": assessment["users_partial"],
        "users_started": assessment["users_started"],
        "users_not_started": assessment["users_not_started"],
        "complete_pct": assessment["complete_pct"],
        "started_pct": assessment["started_pct"],
        "users_complete_list": assessment["users_complete_list"],
        "users_partial_list": assessment["users_partial_list"],
    }


