@app.get("/get_season_leaderboard")
def get_season_leaderboard():
    """Get season leaderboard - always returns JSON"""
    try:
        # Use shared function to calculate deltas - ensures consistency with get_weekly_fun_stats
        leaderboard_data = calculate_leaderboard_deltas()
        
        # Build result - team_name is already included in leaderboard_data
        result = []
        for user_data in leaderboard_data:
            result.append({
                "user_id": user_data['user_id'],
                "username": user_data['username'],
                "display_name": user_data['display_name'] or None,
                "team_name": user_data.get('team_name') or None,
                "total_points": int(user_data['total_points']),
                "tippa_points": int(user_data.get('tippa_points') or 0),
                "team_points": int(user_data.get('team_points') or 0),
                "combined": bool(user_data.get('combined')),
                "rank": user_data['rank'],
                "delta": user_data['delta']
            })

        # OBS: Spara inte snapshot på varje fetch (det nollar pilarna vid refresh).
        # Snapshot skapas via admin-flöden (t.ex. efter omräkning) eller manuellt vid behov.
        # Return the result after successful ranking logic
        return jsonify(result)
    
    except Exception as e:
        # Catch ANY error in the entire function and return JSON
        print(f"ERROR in get_season_leaderboard: {e}")
        import traceback
        traceback.print_exc()
        db.session.rollback()
        # Return error info for debugging
        return jsonify({"error": str(e)})

@app.get("/get_season_team_leaderboard")
def get_season_team_leaderboard():
    """Get leaderboard for season teams only (separate from race picks)"""
    # Get all season teams ordered by total_points
    season_teams = (
        db.session.query(
            SeasonTeam.id,
            SeasonTeam.user_id,
            SeasonTeam.team_name,
            SeasonTeam.total_points,
            User.username,
            User.display_name
        )
        .join(User, User.id == SeasonTeam.user_id)
        .order_by(SeasonTeam.total_points.desc())
        .all()
    )
    
    result = []
    for i, (team_id, user_id, team_name, total_points, username, display_name) in enumerate(season_teams, 1):
        result.append({
            "user_id": user_id,
            "username": username,
            "display_name": display_name or None,
            "team_name": team_name or None,
            "total_points": int(total_points or 0),
            "rank": i
        })
    
    return jsonify(result)


@app.get("/get_season_teams_browse")
def get_season_teams_browse():
    """Sök andras säsongsteam (username / display / lagnamn) — ingen lång lista."""
    raw_q = (request.args.get("q") or "").strip()
    if len(raw_q) < 2:
        total = SeasonTeam.query.count()
        exclude_id = session.get("user_id")
        if exclude_id is not None:
            try:
                total = SeasonTeam.query.filter(SeasonTeam.user_id != int(exclude_id)).count()
            except (TypeError, ValueError):
                pass
        return jsonify({"teams": [], "need_query": True, "total_teams": int(total or 0)})

    like = f"%{raw_q}%"
    exclude_id = session.get("user_id")
    q = (
        db.session.query(SeasonTeam, User)
        .join(User, User.id == SeasonTeam.user_id)
        .filter(
            db.or_(
                User.username.ilike(like),
                User.display_name.ilike(like),
                SeasonTeam.team_name.ilike(like),
            )
        )
        .order_by(SeasonTeam.team_name.asc(), User.username.asc())
        .limit(12)
    )
    if exclude_id is not None:
        try:
            q = q.filter(SeasonTeam.user_id != int(exclude_id))
        except (TypeError, ValueError):
            pass

    out = []
    for team, user in q.all():
        _, riders_ui = _season_team_riders_ui(int(user.id))
        out.append(
            {
                "user_id": int(user.id),
                "username": user.username,
                "display_name": user.display_name or None,
                "team_name": team.team_name or None,
                "riders": [
                    {
                        "id": r["id"],
                        "name": r["name"],
                        "number": r["number"],
                        "class": r["class"],
                        "portrait_url": r.get("portrait_url") or f"/rider_portrait/{r['id']}",
                    }
                    for r in riders_ui
                ],
            }
        )
    return jsonify({"teams": out, "need_query": False, "query": raw_q})


@app.get("/user/<string:username>")
def user_stats_page(username: str):
    user = User.query.filter_by(username=username).first_or_404()
    # Lista alla tävlingar och poäng för användaren
    rows = (
        db.session.query(
            Competition.id.label("competition_id"),
            Competition.name,
            Competition.series,
            Competition.event_date,
            CompetitionScore.total_points,
        )
        .outerjoin(CompetitionScore, (Competition.id == CompetitionScore.competition_id) & (CompetitionScore.user_id == user.id))
        .order_by(Competition.event_date.asc().nulls_last())
        .all()
    )

    # Bygg stats
    cum = 0
    history = []
    best = {"name": None, "points": -1}
    for r in rows:
        pts = r.total_points or 0
        cum += pts
        history.append(
            {
                "competition_id": r.competition_id,
                "name": r.name,
                "date": r.event_date.strftime("%Y-%m-%d") if r.event_date else "",
                "points": pts,
                "cumulative": cum,
            }
        )
        if pts > best["points"]:
            best = {"name": r.name, "points": pts}

    avg = round(cum / max(1, sum(1 for h in history if h["points"] > 0)), 2)

    return render_template(
        "user_stats.html",
        username=user.username,
        team=SeasonTeam.query.filter_by(user_id=user.id).first(),
        total=cum,
        avg=avg,
        best=best,
        history=history,
    )


def compute_series_championship_totals(
    *,
    season_year: int | None = None,
    wsx_year: int | None = None,
):
    """
    Summarizes season points using the same rules as the per-race results view:
    WSX (rider_points or position), SMX playoffs (position × round multiplier), SX/MX (AMA scale).

    Official SMX (supermotocross.com rulebook):
    - SMX Combined = SX championship points + MX championship points (regular season seeding).
    - SMX World Championship = seed adjustment (top 20 from combined) + playoff round points
      (Playoff 1 ×1, Playoff 2 ×2, Final ×3; AMA scale 25–1 for positions 1–21).
    Buckets internally: SX/MX/SMX × (450cc, 250 East, 250 West); WSX × (SX1, SX2).
    """
    from collections import defaultdict

    from sqlalchemy import func

    totals = defaultdict(lambda: defaultdict(float))
    rider_meta = {}
    promoted_250_coasts = _promoted_250_coast_by_name()
    season_year = int(season_year or _current_racing_season_year())

    # Race results / live standings: selected WSX year (default = active season).
    # Older WSX years can be opened via ?year= on förarresultat.
    wsx_year = int(wsx_year or _active_wsx_season_year())
    try:
        wsx_comp_ids = {int(c.id) for c in _wsx_competitions_for_year(wsx_year)}
    except Exception:
        wsx_comp_ids = set()

    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .all()
    )
    rows = _dedupe_championship_query_rows(rows)

    for cr, comp, rider in rows:
        s = str(comp.series).strip() if comp.series is not None else ""
        if s not in ("WSX", "SX", "MX", "SMX"):
            continue
        if s == "WSX" and wsx_comp_ids and int(comp.id) not in wsx_comp_ids:
            continue
        if s in ("SX", "MX", "SMX"):
            if not comp.event_date or int(comp.event_date.year) != season_year:
                continue

        if s == "WSX":
            if cr.rider_points is not None:
                pts = float(cr.rider_points)
            else:
                pts = float(get_smx_qualification_points(cr.position))
        elif s == "SMX":
            mult = comp.point_multiplier or 1.0
            pts = float(get_smx_qualification_points(cr.position)) * float(mult)
        else:
            pts = float(_result_points_for_standing(cr, comp))

        bucket = _championship_bucket_for_rider(cr, comp, rider, promoted_250_coasts)
        if not bucket:
            continue

        rid = rider.id
        totals[bucket][rid] += pts

        if rid not in rider_meta:
            merged_img = getattr(rider, "rider_image_data", None) or rider.image_url
            rider_meta[rid] = {
                "rider_id": rid,
                "rider_name": rider.name,
                "rider_number": rider.rider_number,
                "bike_brand": rider.bike_brand or "",
                "coast_250": rider.coast_250 or "",
                "class_name": getattr(rider, "class_name", None) or "",
                "image_url": merged_img,
            }

    # SMX Combined: prefer official supermotocross.com snapshot for 2026 seeding/LCQ
    # (live import can drift on docked points). Next season: live sum only.
    try:
        from official_smx_2026 import apply_official_smx_2026_to_championship_totals

        apply_official_smx_2026_to_championship_totals(
            totals, rider_meta, season_year=season_year
        )
    except Exception as exc:
        print(f"WARNING apply_official_smx_2026_to_championship_totals: {exc}")

    def _norm_rider_name(rid: int) -> str:
        try:
            from official_smx_2026 import _norm_name

            return _norm_name((rider_meta.get(rid) or {}).get("rider_name") or "")
        except Exception:
            return str((rider_meta.get(rid) or {}).get("rider_name") or "").strip().lower()

    def _prefer_ama_rid(rids: list[int], *, want_250: bool | None = None) -> int:
        """Pick AMA 450/250 row over WSX twin when collapsing duplicate names."""

        def score(rid: int) -> tuple[int, int]:
            cls = str((rider_meta.get(rid) or {}).get("class_name") or "").strip().lower()
            if want_250 is True and cls == "250cc":
                pri = 0
            elif want_250 is False and cls == "450cc":
                pri = 0
            elif cls in ("450cc", "250cc"):
                pri = 1
            elif cls.startswith("wsx"):
                pri = 3
            else:
                pri = 2
            return (pri, rid)

        return sorted({int(r) for r in rids}, key=score)[0]

    def _collapse_points_by_name(
        points_by_rid: dict[int, float],
        *,
        want_250: bool | None = None,
    ) -> dict[int, float]:
        """Sum twin-row points (AMA+WSX same name) onto one canonical rider id."""
        by_name: dict[str, list[int]] = {}
        for rid in points_by_rid:
            by_name.setdefault(_norm_rider_name(int(rid)), []).append(int(rid))
        out: dict[int, float] = {}
        for norm, rids in by_name.items():
            if not norm:
                for rid in rids:
                    out[rid] = float(points_by_rid.get(rid) or 0)
                continue
            keeper = _prefer_ama_rid(rids, want_250=want_250)
            out[keeper] = sum(float(points_by_rid.get(rid) or 0) for rid in rids)
        return out

    def top_list(*bucket_parts, limit=12):
        bucket = tuple(bucket_parts)
        d = totals.get(bucket) or {}
        items = sorted(d.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rid, p in items[:limit]:
            row = dict(rider_meta.get(rid, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            out.append(row)
        return out

    def combined_top_list(
        *bucket_tuples,
        limit: int = 12,
        min_rank: int = 1,
        max_rank: int | None = None,
    ):
        """SX + MX combined; optional rank window (e.g. 21–30 for LCQ bubble)."""
        merged = defaultdict(float)
        for bucket_parts in bucket_tuples:
            bucket = tuple(bucket_parts)
            for rid, p in (totals.get(bucket) or {}).items():
                merged[rid] += float(p)
        merged = _collapse_points_by_name(merged, want_250=False)
        items = sorted(merged.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rank, (rid, p) in enumerate(items, start=1):
            if rank < min_rank:
                continue
            if max_rank is not None and rank > max_rank:
                break
            row = dict(rider_meta.get(rid, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            row["smx_rank"] = rank
            row["zone"] = _smx_qualification_zone(rank)
            out.append(row)
            if max_rank is None and len(out) >= limit:
                break
        return out

    def combined_250_unified_list(
        *,
        limit: int = 12,
        min_rank: int = 1,
        max_rank: int | None = None,
    ):
        """Official SMX 250 Combined: one list (East + West SX + MX)."""
        merged = defaultdict(float)
        for coast in ("east", "west"):
            for bucket_parts in (("sx", "250", coast), ("mx", "250", coast)):
                bucket = tuple(bucket_parts)
                for rid, p in (totals.get(bucket) or {}).items():
                    merged[int(rid)] += float(p)
        merged = _collapse_points_by_name(merged, want_250=True)
        items = sorted(merged.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rank, (rid, p) in enumerate(items, start=1):
            if rank < min_rank:
                continue
            if max_rank is not None and rank > max_rank:
                break
            row = dict(rider_meta.get(rid, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            row["smx_rank"] = rank
            row["zone"] = _smx_qualification_zone(rank)
            out.append(row)
            if max_rank is None and len(out) >= limit:
                break
        return out

    def smx_playoff_top_list(sx_bucket, mx_bucket, smx_bucket, limit=25):
        """Official SMX World Championship: seed adjustment (top 20 combined) + playoff rounds."""
        combined = defaultdict(float)
        for rid, p in (totals.get(sx_bucket) or {}).items():
            combined[int(rid)] += float(p)
        for rid, p in (totals.get(mx_bucket) or {}).items():
            combined[int(rid)] += float(p)
        combined = _collapse_points_by_name(combined, want_250=False)

        playoff_pts = defaultdict(float)
        ranked = sorted(combined.items(), key=lambda x: (-x[1], x[0]))
        for rank, (rid, _) in enumerate(ranked[:20], start=1):
            playoff_pts[rid] += float(get_smx_qualification_points(rank))

        smx_raw = {int(rid): float(p) for rid, p in (totals.get(smx_bucket) or {}).items()}
        for rid, p in _collapse_points_by_name(smx_raw, want_250=False).items():
            playoff_pts[int(rid)] += float(p)

        items = sorted(playoff_pts.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rid, p in items[:limit]:
            if p <= 0:
                continue
            row = dict(rider_meta.get(rid, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            out.append(row)
        return out

    def smx_playoff_top_list_unified_250(limit=25):
        """SMX World Championship 250 — unified combined seed + playoff rounds."""
        combined = defaultdict(float)
        for coast in ("east", "west"):
            for bucket_parts in (("sx", "250", coast), ("mx", "250", coast)):
                bucket = tuple(bucket_parts)
                for rid, p in (totals.get(bucket) or {}).items():
                    combined[int(rid)] += float(p)
        combined = _collapse_points_by_name(combined, want_250=True)

        playoff_pts = defaultdict(float)
        ranked = sorted(combined.items(), key=lambda x: (-x[1], x[0]))
        for rank, (rid, _) in enumerate(ranked[:20], start=1):
            playoff_pts[rid] += float(get_smx_qualification_points(rank))

        smx_raw: dict[int, float] = defaultdict(float)
        for coast in ("east", "west"):
            smx_bucket = ("smx", "250", coast)
            for rid, p in (totals.get(smx_bucket) or {}).items():
                smx_raw[int(rid)] += float(p)
        for rid, p in _collapse_points_by_name(dict(smx_raw), want_250=True).items():
            playoff_pts[int(rid)] += float(p)

        items = sorted(playoff_pts.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rid, p in items[:limit]:
            if p <= 0:
                continue
            row = dict(rider_meta.get(rid, {}))
            row["points"] = int(p) if abs(p - round(p)) < 0.001 else round(p, 1)
            out.append(row)
        return out

    sx = {
        "label": "AMA Supercross (SX)",
        "450": top_list("sx", "450"),
        "250_east": top_list("sx", "250", "east"),
        "250_west": top_list("sx", "250", "west"),
    }
    mx = {
        "label": "Pro Motocross (MX)",
        "450": top_list("mx", "450"),
        "250_east": top_list("mx", "250", "east"),
        "250_west": top_list("mx", "250", "west"),
    }
    smx = {
        "label": "SMX Combined (SX + MX)",
        "450": combined_top_list(("sx", "450"), ("mx", "450"), limit=12, max_rank=20),
        "450_lcq": combined_top_list(("sx", "450"), ("mx", "450"), min_rank=21, max_rank=30),
        "250": combined_250_unified_list(limit=12, max_rank=20),
        "250_lcq": combined_250_unified_list(min_rank=21, max_rank=30),
    }
    smx_playoffs = {
        "label": "SMX World Championship (Playoffs)",
        "450": smx_playoff_top_list(("sx", "450"), ("mx", "450"), ("smx", "450")),
        "250": smx_playoff_top_list_unified_250(),
    }
    wsx = {
        "label": f"WSX {wsx_year}",
        "year": wsx_year,
        "sx1": top_list("wsx", "wsx_sx1"),
        "sx2": top_list("wsx", "wsx_sx2"),
    }

    def _block_nonempty(block):
        for k, v in block.items():
            if k == "label" or not isinstance(v, list):
                continue
            if len(v) > 0:
                return True
        return False

    smx_comp_exists = (
        db.session.query(Competition.id)
        .filter(func.trim(Competition.series) == "SMX")
        .first()
        is not None
    )
    has_any = (
        _block_nonempty(sx)
        or _block_nonempty(mx)
        or _block_nonempty(smx)
        or _block_nonempty(smx_playoffs)
        or _block_nonempty(wsx)
        or smx_comp_exists
    )

    return {
        "SX": sx,
        "MX": mx,
        "SMX": smx,
        "SMX_PLAYOFFS": smx_playoffs,
        "WSX": wsx,
        "has_any": has_any,
        "show_smx_section": _block_nonempty(smx) or smx_comp_exists,
        "show_smx_playoffs_section": _block_nonempty(smx_playoffs) or smx_comp_exists,
    }


def _build_race_results_season_wrap(
    series_filter: str,
    championship_totals: dict,
    competitions: list,
    *,
    year_filter: int | None = None,
) -> dict | None:
    """Status banner when a single finished series tab is open on /race_results."""
    code = (series_filter or "").strip().upper()
    if code not in ("SX", "MX", "SMX", "WSX"):
        return None

    today = get_today()
    name_by_code = {
        "SX": "Supercross",
        "MX": "Motocross",
        "SMX": "SMX Finals",
        "WSX": "WSX",
    }
    label_by_code = {
        "SX": "AMA Supercross",
        "MX": "AMA Pro Motocross",
        "SMX": "SMX",
        "WSX": "WSX",
    }

    if year_filter:
        season_year = int(year_filter)
    else:
        season_year = _current_racing_season_year()
        if code == "WSX":
            try:
                season_year = int(_active_wsx_season_year())
            except Exception:
                pass

    year = season_year
    finished = False
    series_name = name_by_code[code]
    row = Series.query.filter_by(name=series_name, year=season_year).first()
    if row:
        if row.year:
            year = int(row.year)
        if row.end_date and today > row.end_date:
            finished = True

    if not finished and competitions:
        dated = [c for c in competitions if getattr(c, "event_date", None)]
        if dated:
            last = max(c.event_date for c in dated)
            upcoming = [c for c in dated if c.event_date >= today]
            if not upcoming and last < today:
                finished = True
            if last:
                year = year or int(last.year)

    if not finished:
        return None

    class_label = "450cc"
    rows: list = []
    class_champs: list[dict] = []
    ct = championship_totals or {}

    if code == "SX":
        block = ct.get("SX") or {}
        rows = block.get("450") or []
        for key, lbl in (("250_east", "250 East"), ("250_west", "250 West")):
            top = (block.get(key) or [None])[0]
            if top:
                class_champs.append(
                    {
                        "class_label": lbl,
                        "rider_name": top.get("rider_name"),
                        "points": top.get("points"),
                    }
                )
    elif code == "MX":
        block = ct.get("MX") or {}
        rows = block.get("450") or []
        for key, lbl in (("250_east", "250 East"), ("250_west", "250 West")):
            top = (block.get(key) or [None])[0]
            if top:
                class_champs.append(
                    {
                        "class_label": lbl,
                        "rider_name": top.get("rider_name"),
                        "points": top.get("points"),
                    }
                )
    elif code == "SMX":
        po = ct.get("SMX_PLAYOFFS") or {}
        if po.get("450"):
            rows = po.get("450") or []
            class_label = "450 Playoffs"
            top250 = (po.get("250") or [None])[0]
        else:
            combined = ct.get("SMX") or {}
            rows = combined.get("450") or []
            class_label = "450 Combined"
            top250 = (combined.get("250") or [None])[0]
        if top250:
            class_champs.append(
                {
                    "class_label": "250",
                    "rider_name": top250.get("rider_name"),
                    "points": top250.get("points"),
                }
            )
    elif code == "WSX":
        block = ct.get("WSX") or {}
        rows = block.get("sx1") or []
        class_label = "SX1"
        top2 = (block.get("sx2") or [None])[0]
        if top2:
            class_champs.append(
                {
                    "class_label": "SX2",
                    "rider_name": top2.get("rider_name"),
                    "points": top2.get("points"),
                }
            )

    podium = []
    for i, r in enumerate((rows or [])[:3]):
        podium.append(
            {
                "rank": i + 1,
                "rider_name": r.get("rider_name") or "?",
                "points": r.get("points"),
                "rider_number": r.get("rider_number"),
            }
        )

    return {
        "finished": True,
        "year": year,
        "series_code": code,
        "series_label": label_by_code[code],
        "class_label": class_label,
        "podium": podium,
        "class_champs": class_champs,
    }


def _race_results_available_years(series_filter: str) -> list[int]:
    """Distinct calendar years with races (plus WSX Series.year even without dates)."""
    years: set[int] = set()
    q = db.session.query(db.extract("year", Competition.event_date)).filter(
        Competition.event_date.isnot(None)
    )
    code = (series_filter or "").strip().upper()
    if code in ("SX", "MX", "SMX", "WSX", "MXGP", "MXON"):
        q = q.filter(db.func.upper(Competition.series) == code)
    elif code == "AMA":
        q = q.filter(~db.func.upper(Competition.series).in_(tuple(TIPPA_ONLY_SERIES)))
    for (y,) in q.distinct().all():
        if y is not None:
            years.add(int(y))

    if code in ("", "ALL", "WSX"):
        for (y,) in (
            db.session.query(Series.year).filter(Series.name == "WSX", Series.year.isnot(None)).all()
        ):
            years.add(int(y))
    if code in ("", "ALL", "MXGP"):
        for (y,) in (
            db.session.query(Series.year)
            .filter(Series.name == "MXGP", Series.year.isnot(None))
            .all()
        ):
            years.add(int(y))
    if code in ("", "ALL", "MXON"):
        for (y,) in (
            db.session.query(Series.year)
            .filter(Series.name == "MXON", Series.year.isnot(None))
            .all()
        ):
            years.add(int(y))

    return sorted(years, reverse=True)


def _race_results_default_year(series_filter: str, available: list[int]) -> int:
    code = (series_filter or "").strip().upper()
    if code == "WSX":
        prefer = int(_active_wsx_season_year())
    elif code == "MXGP":
        prefer = 2027
    else:
        prefer = int(_current_racing_season_year())
    if prefer in available:
        return prefer
    if available:
        return int(available[0])
    return prefer


def _race_results_series_tab_groups(year: int) -> dict:
    """Series chips for /race_results: AMA collapsed; live only when picks are open.

    States:
      live — tippa window open (picks not preseason-locked)
      soon — season exists but picks not open yet / under construction
      done — finished archive for the selected year (or latest MXoN)
    """
    today = get_today()
    tippa_catalog = [
        ("WSX", "WSX", "WSX", "wsx"),
        ("MXGP", "MXGP", "MXGP", "mxgp"),
        ("MXON", "MXoN", "MXON", "mxon"),
    ]
    ama_parts = (
        ("SX", "Supercross"),
        ("MX", "Motocross"),
        ("SMX", "SMX Finals"),
    )

    def _is_finished(row: Series | None, code: str, y: int) -> bool:
        if row and row.end_date and today > row.end_date:
            return True
        dated = (
            Competition.query.filter(
                db.func.upper(Competition.series) == code,
                Competition.event_date.isnot(None),
                db.extract("year", Competition.event_date) == int(y),
            )
            .order_by(Competition.event_date.desc())
            .all()
        )
        if dated and all(c.event_date < today for c in dated):
            return True
        return False

    def _next_upcoming(codes: tuple[str, ...] | list[str]):
        return (
            Competition.query.filter(
                db.func.upper(Competition.series).in_([c.upper() for c in codes]),
                Competition.event_date.isnot(None),
                Competition.event_date >= today,
            )
            .order_by(Competition.event_date.asc())
            .first()
        )

    def _picks_live_for(codes: tuple[str, ...] | list[str]) -> bool:
        nxt = _next_upcoming(codes)
        if nxt is None:
            return False
        try:
            return not is_picks_preseason_locked(nxt)
        except Exception:
            return True

    tabs: list[dict] = []

    # --- AMA / SMX (one chip) ---
    ama_live_year = None
    for _code, series_name in ama_parts:
        rows = (
            Series.query.filter_by(name=series_name)
            .order_by(Series.year.desc())
            .all()
        )
        for row in rows:
            if row.end_date and today > row.end_date:
                continue
            y = int(row.year) if row.year else int(year)
            if _is_finished(row, _code, y):
                continue
            if ama_live_year is None or y > ama_live_year:
                ama_live_year = y
            break

    if ama_live_year is not None:
        picks_live = _picks_live_for(("SX", "MX", "SMX"))
        tabs.append(
            {
                "code": "AMA",
                "label": "AMA / SMX",
                "tone": "ama",
                "finished": False,
                "year": int(ama_live_year),
                "state": "live" if picks_live else "soon",
            }
        )

    ama_fin_any = False
    for _code, series_name in ama_parts:
        row = Series.query.filter_by(name=series_name, year=int(year)).first()
        has_comps = (
            db.session.query(Competition.id)
            .filter(
                db.func.upper(Competition.series) == _code,
                Competition.event_date.isnot(None),
                db.extract("year", Competition.event_date) == int(year),
            )
            .first()
            is not None
        )
        if (row or has_comps) and _is_finished(row, _code, int(year)):
            ama_fin_any = True
            break
    if ama_fin_any and not any(
        t["code"] == "AMA" and int(t["year"]) == int(year) for t in tabs
    ):
        tabs.append(
            {
                "code": "AMA",
                "label": "AMA / SMX",
                "tone": "ama",
                "finished": True,
                "year": int(year),
                "state": "done",
            }
        )

    # --- WSX / MXGP / MXON ---
    for code, label, series_name, tone in tippa_catalog:
        rows = (
            Series.query.filter_by(name=series_name)
            .order_by(Series.year.desc())
            .all()
        )
        live = None
        for row in rows:
            if row.end_date and today > row.end_date:
                continue
            live = row
            break

        if live is not None:
            y = int(live.year) if live.year else int(year)
            if not _is_finished(live, code, y):
                under_construction = bool(getattr(live, "under_construction", False))
                if under_construction:
                    state = "soon"
                elif _picks_live_for((code,)):
                    state = "live"
                else:
                    state = "soon"
                tabs.append(
                    {
                        "code": code,
                        "label": label,
                        "tone": tone,
                        "finished": False,
                        "year": y,
                        "state": state,
                    }
                )

        row = Series.query.filter_by(name=series_name, year=int(year)).first()
        has_year_comps = (
            db.session.query(Competition.id)
            .filter(
                db.func.upper(Competition.series) == code,
                Competition.event_date.isnot(None),
                db.extract("year", Competition.event_date) == int(year),
            )
            .first()
            is not None
        )
        if (row or has_year_comps) and _is_finished(row, code, int(year)):
            if not any(t["code"] == code and int(t["year"]) == int(year) for t in tabs):
                tabs.append(
                    {
                        "code": code,
                        "label": label,
                        "tone": tone,
                        "finished": True,
                        "year": int(year),
                        "state": "done",
                    }
                )

    if not any(t["code"] == "MXON" for t in tabs):
        mxon_rows = (
            Series.query.filter_by(name="MXON")
            .order_by(Series.year.desc())
            .all()
        )
        for row in mxon_rows:
            y = int(row.year) if row.year else int(year)
            if not _is_finished(row, "MXON", y):
                continue
            tabs.append(
                {
                    "code": "MXON",
                    "label": "MXoN",
                    "tone": "mxon",
                    "finished": True,
                    "year": y,
                    "state": "done",
                }
            )
            break

    state_rank = {"live": 0, "soon": 1, "done": 2}
    code_rank = {"AMA": 0, "WSX": 1, "MXGP": 2, "MXON": 3}
    tabs.sort(
        key=lambda t: (
            state_rank.get(t.get("state") or "done", 9),
            code_rank.get(t.get("code") or "", 9),
            -int(t.get("year") or 0),
        )
    )

    active = [t for t in tabs if t.get("state") == "live"]
    upcoming = [t for t in tabs if t.get("state") == "soon"]
    finished = [t for t in tabs if t.get("state") == "done"]
    return {
        "tabs": tabs,
        "active": active,
        "upcoming": upcoming,
        "finished": finished,
    }



@app.get("/race_results")
def race_results_page():
    """Show actual race results for all competitions"""
    try:
        series_filter = (request.args.get("series") or "").strip().upper()
        # SX/MX/SMX collapse into one AMA / SMX chip
        if series_filter in ("SX", "MX", "SMX"):
            series_filter = "AMA"
        if series_filter not in ("WSX", "AMA", "MXGP", "MXON"):
            series_filter = ""

        # Year first (needed for finished-archive tabs); may be overridden by active tab year
        all_years = _race_results_available_years("")
        year_raw = (request.args.get("year") or "").strip()
        year_filter: int | None = None
        if year_raw.isdigit():
            year_filter = int(year_raw)
        if year_filter is None:
            year_filter = _race_results_default_year(series_filter, all_years)

        series_groups = _race_results_series_tab_groups(year_filter)
        tabs = series_groups.get("tabs") or []
        tab_by_code = {t["code"]: t for t in tabs}
        active_by_code = {t["code"]: t for t in series_groups.get("active") or []}
        finished_by_code = {t["code"]: t for t in series_groups.get("finished") or []}

        # Default: first live tippa series, else first soon, else first tab
        if not series_filter:
            pick = (
                (series_groups.get("active") or [None])[0]
                or (series_groups.get("upcoming") or [None])[0]
                or (tabs[0] if tabs else None)
            )
            if pick:
                series_filter = pick["code"]
                year_filter = int(pick["year"])

        # If user opens a live/soon series without year, use that series' year
        if series_filter in tab_by_code and not year_raw:
            year_filter = int(tab_by_code[series_filter]["year"])

        # Rebuild groups if year changed after defaulting
        series_groups = _race_results_series_tab_groups(year_filter)
        tabs = series_groups.get("tabs") or []
        tab_by_code = {t["code"]: t for t in tabs}
        active_by_code = {t["code"]: t for t in series_groups.get("active") or []}
        finished_by_code = {t["code"]: t for t in series_groups.get("finished") or []}

        sel = tab_by_code.get(series_filter) or {}
        state = sel.get("state") or (
            "done" if series_filter in finished_by_code else "live" if series_filter in active_by_code else "soon"
        )
        series_bucket = (
            "finished" if state == "done" else "active" if state == "live" else "upcoming"
        )

        available_years = _race_results_available_years(series_filter) or [year_filter]
        if year_filter not in available_years:
            available_years = sorted(set(available_years) | {year_filter}, reverse=True)

        try:
            championship_totals = compute_series_championship_totals(
                season_year=year_filter,
                wsx_year=year_filter,
            )
        except Exception as ex_ct:
            print(f"WARNING compute_series_championship_totals: {ex_ct}")
            championship_totals = {
                "has_any": False,
                "SX": {},
                "MX": {},
                "SMX": {},
                "SMX_PLAYOFFS": {},
                "WSX": {},
                "show_smx_section": False,
                "show_smx_playoffs_section": False,
            }

        competitions = Competition.query.order_by(Competition.event_date.asc()).all()
        if series_filter == "WSX":
            try:
                competitions = _wsx_competitions_for_year(year_filter)
            except Exception:
                competitions = [
                    c
                    for c in competitions
                    if (c.series or "").upper() == "WSX"
                    and c.event_date
                    and int(c.event_date.year) == year_filter
                ]
        elif series_filter == "MXGP":
            try:
                competitions = _mxgp_competitions_for_year(year_filter)
                if not competitions:
                    competitions = [
                        c
                        for c in Competition.query.order_by(Competition.event_date.asc()).all()
                        if (c.series or "").upper() == "MXGP"
                        and c.event_date
                        and int(c.event_date.year) == year_filter
                    ]
            except Exception:
                competitions = [
                    c
                    for c in competitions
                    if (c.series or "").upper() == "MXGP"
                    and (not c.event_date or int(c.event_date.year) == year_filter)
                ]
        elif series_filter == "AMA":
            competitions = [
                c
                for c in competitions
                if (c.series or "").upper() not in TIPPA_ONLY_SERIES
                and c.event_date
                and int(c.event_date.year) == year_filter
            ]
        elif series_filter:
            series_ids_for_year = {
                int(s.id)
                for s in Series.query.filter(Series.year == year_filter).all()
                if s.id is not None
            }
            competitions = [
                c
                for c in competitions
                if (c.series or "").upper() == series_filter
                and (
                    (c.event_date and int(c.event_date.year) == year_filter)
                    or (c.series_id and int(c.series_id) in series_ids_for_year)
                )
            ]
        else:
            competitions = [
                c
                for c in competitions
                if c.event_date and int(c.event_date.year) == year_filter
            ]

        competition_results: dict[int, dict] = {
            int(c.id): {"results": [], "holeshots": []} for c in competitions
        }

        promoted_250_coasts = _promoted_250_coast_by_name()
        comp_ids = [int(c.id) for c in competitions]

        if comp_ids:
            rows = (
                db.session.query(
                    CompetitionResult.competition_id,
                    CompetitionResult.rider_id,
                    CompetitionResult.position,
                    CompetitionResult.rider_points,
                    Rider.name.label("rider_name"),
                    db.func.coalesce(CompetitionResult.class_name, Rider.class_name).label(
                        "class_name"
                    ),
                    Rider.class_name.label("rider_current_class"),
                    Rider.coast_250.label("coast_250"),
                    Rider.rider_number,
                    Rider.image_url,
                    (Rider.rider_image_data.isnot(None) & (Rider.rider_image_data != "")).label(
                        "has_db_portrait"
                    ),
                    Rider.bike_brand,
                    Rider.series_participation,
                )
                .join(Rider, Rider.id == CompetitionResult.rider_id)
                .filter(CompetitionResult.competition_id.in_(comp_ids))
                .order_by(
                    CompetitionResult.competition_id.asc(),
                    db.func.coalesce(CompetitionResult.class_name, Rider.class_name).asc(),
                    CompetitionResult.position.asc(),
                )
                .all()
            )

            comp_by_id = {int(c.id): c for c in competitions}
            for result in rows:
                comp_id = int(result.competition_id)
                comp = comp_by_id.get(comp_id)
                if not comp:
                    continue

                if comp.series == "WSX":
                    if hasattr(result, "rider_points") and result.rider_points is not None:
                        points = result.rider_points
                    else:
                        points = get_smx_qualification_points(result.position)
                elif comp.series == "SMX":
                    points = get_smx_qualification_points(result.position) * comp.point_multiplier
                elif comp.series == "MX":
                    points = _result_points_for_standing(result, comp)
                else:
                    points = get_smx_qualification_points(result.position)

                img_url = _display_image_url_for_rider_row(
                    int(result.rider_id),
                    has_db_portrait=bool(getattr(result, "has_db_portrait", False)),
                    image_url=result.image_url,
                    rider_name=result.rider_name,
                    rider_number=result.rider_number,
                    class_name=getattr(result, "rider_current_class", None) or result.class_name,
                    coast_250=getattr(result, "coast_250", None),
                    bike_brand=result.bike_brand,
                    series_participation=getattr(result, "series_participation", None),
                )

                if comp.series == "WSX":
                    display_class = (result.class_name or "").strip().lower()
                    if display_class in ("450cc", "450", "sx1"):
                        display_class = "wsx_sx1"
                    elif display_class in ("250cc", "250", "sx2"):
                        display_class = "wsx_sx2"
                    elif not display_class:
                        rc = (getattr(result, "rider_current_class", None) or "").strip().lower()
                        if rc in ("wsx_sx1", "450cc"):
                            display_class = "wsx_sx1"
                        elif rc in ("wsx_sx2", "250cc"):
                            display_class = "wsx_sx2"
                        else:
                            display_class = rc or result.class_name
                else:
                    display_class = _standing_class_and_coast(
                        result, comp, result, promoted_250_coasts
                    )[0] or result.class_name

                competition_results[comp_id]["results"].append(
                    {
                        "rider_id": result.rider_id,
                        "position": result.position,
                        "rider_name": result.rider_name,
                        "class_name": display_class,
                        "rider_number": result.rider_number,
                        "image_url": img_url,
                        "bike_brand": result.bike_brand,
                        "points": points,
                    }
                )

            hs_rows = (
                db.session.query(
                    HoleshotResult.competition_id,
                    HoleshotResult.rider_id,
                    HoleshotResult.class_name,
                    Rider.name.label("rider_name"),
                    Rider.rider_number,
                    Rider.image_url,
                    (Rider.rider_image_data.isnot(None) & (Rider.rider_image_data != "")).label(
                        "has_db_portrait"
                    ),
                    Rider.bike_brand,
                )
                .join(Rider, Rider.id == HoleshotResult.rider_id)
                .filter(HoleshotResult.competition_id.in_(comp_ids))
                .order_by(HoleshotResult.competition_id.asc())
                .all()
            )
            for h in hs_rows:
                comp_id = int(h.competition_id)
                img_url = _display_image_url_for_rider_row(
                    int(h.rider_id),
                    has_db_portrait=bool(getattr(h, "has_db_portrait", False)),
                    image_url=h.image_url,
                    rider_name=h.rider_name,
                    rider_number=h.rider_number,
                    class_name=h.class_name,
                    bike_brand=h.bike_brand,
                )
                competition_results[comp_id]["holeshots"].append(
                    {
                        "rider_id": h.rider_id,
                        "rider_name": h.rider_name,
                        "class_name": h.class_name,
                        "rider_number": h.rider_number,
                        "image_url": img_url,
                        "bike_brand": h.bike_brand,
                    }
                )

        # MXoN: official board is nations + class winners (not CompetitionResult)
        mxon_comp_ids = [
            int(c.id)
            for c in competitions
            if (c.series or "").upper() == "MXON"
        ]
        if mxon_comp_ids:
            from mxon_fantasy import build_mxon_official_board

            for mid in mxon_comp_ids:
                board = build_mxon_official_board(mid)
                bucket = competition_results.setdefault(
                    mid, {"results": [], "holeshots": []}
                )
                bucket["mxon_nations"] = board.get("nations") or []
                bucket["mxon_sweden"] = board.get("sweden")
                bucket["mxon_class_winners"] = board.get("class_winners") or []

        today = get_today()
        latest_competition_id = None
        earliest_upcoming_id = None
        earliest_upcoming_date = None

        for comp in competitions:
            bucket = competition_results.get(comp.id) or {}
            has_results = (
                len(bucket.get("results") or []) > 0
                or len(bucket.get("holeshots") or []) > 0
                or len(bucket.get("mxon_nations") or []) > 0
            )

            if has_results:
                comp.status = "completed"
                comp.status_text = "Körda race"
                comp.status_color = "text-green-600"
                comp.status_bg = "bg-green-100"
            elif comp.event_date and comp.event_date < today:
                comp.status = "missed"
                comp.status_text = "Missade race"
                comp.status_color = "text-red-600"
                comp.status_bg = "bg-red-100"
            else:
                comp.status = "upcoming"
                comp.status_text = "Uppkommande"
                comp.status_color = "text-blue-600"
                comp.status_bg = "bg-blue-100"

            if (
                comp.status == "upcoming"
                and comp.event_date
                and (earliest_upcoming_date is None or comp.event_date < earliest_upcoming_date)
            ):
                earliest_upcoming_id = comp.id
                earliest_upcoming_date = comp.event_date

        season_wrap = None
        try:
            season_wrap = _build_race_results_season_wrap(
                series_filter,
                championship_totals,
                competitions,
                year_filter=year_filter,
            )
        except Exception as ex_sw:
            print(f"WARNING _build_race_results_season_wrap: {ex_sw}")
            season_wrap = None

        # Default race: newest completed, else next upcoming
        filtered_completed = [
            c for c in competitions if c.status == "completed" and c.event_date
        ]
        if filtered_completed:
            latest_competition_id = max(
                filtered_completed, key=lambda c: (c.event_date, int(c.id))
            ).id
        elif earliest_upcoming_id:
            latest_competition_id = earliest_upcoming_id
        elif competitions:
            dated = [c for c in competitions if c.event_date]
            if dated:
                latest_competition_id = max(
                    dated, key=lambda c: (c.event_date, int(c.id))
                ).id
            else:
                latest_competition_id = competitions[-1].id

        competitions.sort(
            key=lambda c: (c.event_date is None, c.event_date or date.min, int(c.id))
        )

        return render_template(
            "race_results.html",
            competitions=competitions,
            competition_results=competition_results,
            latest_competition_id=latest_competition_id,
            championship_totals=championship_totals,
            series_filter=series_filter or "all",
            year_filter=year_filter,
            available_years=available_years,
            series_groups=series_groups,
            series_bucket=series_bucket,
            season_wrap=season_wrap,
            username=session.get("username", "Gäst"),
            is_logged_in="user_id" in session,
        )

    except Exception as e:
        print(f"ERROR in race_results_page: {e}")
        import traceback
        traceback.print_exc()
        return f"Error loading race results: {str(e)}", 500

