@app.get("/admin/get_out_status/<int:competition_id>")
def admin_get_out_status(competition_id):
    if not is_admin_user():
        return jsonify({"error": "unauthorized"}), 403

    try:
        print(f"DEBUG: admin_get_out_status called for competition {competition_id}")

        comp = Competition.query.get(competition_id)
        if not comp:
            return jsonify({"error": "competition_not_found"}), 404

        is_wsx = (comp.series or "") == "WSX"
        is_mxgp = (comp.series or "").upper() == "MXGP"
        if is_wsx:
            # Same tippa roster as race picks — no orphan/wrong-class duplicates
            riders = (
                wsx_roster_query("wsx_sx1").order_by(Rider.rider_number.asc()).all()
                + wsx_roster_query("wsx_sx2").order_by(Rider.rider_number.asc()).all()
            )
        elif is_mxgp:
            from mxgp_fantasy import mxgp_roster_query

            riders = mxgp_roster_query().order_by(
                Rider.class_name.asc(), Rider.rider_number.asc()
            ).all()
        else:
            riders = (
                db.session.query(Rider)
                .filter(Rider.class_name.in_(["450cc", "250cc"]))
                .order_by(Rider.class_name.desc(), Rider.rider_number.asc())
                .all()
            )
        print(f"DEBUG: Found {len(riders)} riders (wsx={is_wsx}, mxgp={is_mxgp})")

        # out set for this competition
        out_rows = (
            db.session.query(CompetitionRiderStatus.rider_id)
            .filter(
                CompetitionRiderStatus.competition_id == competition_id,
                CompetitionRiderStatus.status == "OUT",
            )
            .all()
        )
        out_ids = {rid for (rid,) in out_rows}

        # Map orphan OUT rows (wrong rider_id) onto tippa roster by name
        if (is_wsx or is_mxgp) and out_ids:
            by_name = {(r.name or "").strip().lower(): r.id for r in riders}
            orphan_ids = out_ids - {r.id for r in riders}
            for oid in orphan_ids:
                orphan = Rider.query.get(oid)
                if not orphan:
                    continue
                key = (orphan.name or "").strip().lower()
                tippa_id = by_name.get(key)
                if tippa_id:
                    out_ids.add(tippa_id)
        print(f"DEBUG: Found {len(out_ids)} OUT riders for competition {competition_id}")

        result = [
            {
                "id": r.id,
                "name": r.name,
                "class": r.class_name,
                "rider_number": r.rider_number,
                "bike_brand": r.bike_brand,
                "is_out": r.id in out_ids,
            }
            for r in riders
        ]
        print(f"DEBUG: Returning {len(result)} riders with OUT status")
        return jsonify(result), 200
    except Exception as e:
        print(f"DEBUG: Error in admin_get_out_status: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": "internal_error"}), 500


@app.post("/admin/set_out_status")
def admin_set_out_status():
    if not is_admin_user():
        return jsonify({"error": "unauthorized"}), 403

    data = request.get_json(force=True) or {}
    comp_id = data.get("competition_id")
    rider_id = data.get("rider_id")
    status = (data.get("status") or "").upper()  # "OUT" eller "CLEAR"

    print(f"DEBUG: admin_set_out_status called - comp_id: {comp_id}, rider_id: {rider_id}, status: {status}")

    try:
        comp_id = int(comp_id)
        rider_id = int(rider_id)
    except Exception as e:
        print(f"DEBUG: Error parsing IDs: {e}")
        return jsonify({"error": "invalid_payload"}), 400

    # Validera att tävling och förare finns
    comp = Competition.query.get(comp_id)
    rider = Rider.query.get(rider_id)
    if not comp:
        print(f"DEBUG: Competition {comp_id} not found")
        return jsonify({"error": "competition_not_found"}), 404
    if not rider:
        print(f"DEBUG: Rider {rider_id} not found")
        return jsonify({"error": "rider_not_found"}), 404

    print(f"DEBUG: Found competition: {comp.name}, rider: {rider.name}, series: {comp.series}")

    if status == "OUT":
        # Set OUT for this competition
        row = (
            CompetitionRiderStatus.query.filter_by(
                competition_id=comp_id, rider_id=rider_id
            ).first()
        )
        if not row:
            row = CompetitionRiderStatus(
                competition_id=comp_id, rider_id=rider_id, status="OUT"
            )
            db.session.add(row)
            print(f"DEBUG: Created new OUT status for {rider.name} in {comp.name}")
        else:
            row.status = "OUT"
            print(f"DEBUG: Updated existing OUT status for {rider.name} in {comp.name}")
        
        # IMPORTANT: Also set OUT for all FUTURE competitions in the same series
        # This way, once a rider is OUT, they stay OUT until manually cleared
        if comp.series:
            future_comps = (
                Competition.query
                .filter(
                    Competition.series == comp.series,
                    Competition.event_date >= comp.event_date,
                    Competition.id != comp_id  # Don't duplicate the current one
                )
                .all()
            )
            
            added_count = 0
            for future_comp in future_comps:
                existing = CompetitionRiderStatus.query.filter_by(
                    competition_id=future_comp.id,
                    rider_id=rider_id
                ).first()
                
                if not existing:
                    future_row = CompetitionRiderStatus(
                        competition_id=future_comp.id,
                        rider_id=rider_id,
                        status="OUT"
                    )
                    db.session.add(future_row)
                    added_count += 1
                    print(f"DEBUG: Auto-set OUT for {rider.name} in future competition {future_comp.name}")
                elif existing.status != "OUT":
                    existing.status = "OUT"
                    added_count += 1
                    print(f"DEBUG: Updated existing status to OUT for {rider.name} in {future_comp.name}")
            
            if added_count > 0:
                print(f"DEBUG: Auto-set OUT for {rider.name} in {added_count} future {comp.series} competitions")
        
        db.session.commit()
        print(f"DEBUG: Committed OUT status for {rider.name}")
        return jsonify({
            "ok": True,
            "message": f"Rider set OUT for this competition and all future {comp.series or 'competitions'} in the same series"
        }), 200

    # CLEAR: Remove OUT status
    # Option 1: Clear only for this competition (if clear_all_future is False or not provided)
    # Option 2: Clear for this competition AND all future competitions in the same series (if clear_all_future is True)
    clear_all_future = data.get("clear_all_future", False)
    
    if clear_all_future and comp.series:
        # Clear for this competition and all future competitions in the same series
        future_comps = (
            Competition.query
            .filter(
                Competition.series == comp.series,
                Competition.event_date >= comp.event_date
            )
            .all()
        )
        future_comp_ids = [c.id for c in future_comps]
        
        deleted_count = CompetitionRiderStatus.query.filter(
            CompetitionRiderStatus.rider_id == rider_id,
            CompetitionRiderStatus.competition_id.in_(future_comp_ids)
        ).delete()
        
        db.session.commit()
        print(f"DEBUG: Cleared OUT status for {rider.name} in {deleted_count} competitions (this + all future {comp.series})")
        return jsonify({
            "ok": True,
            "message": f"Cleared OUT status for {rider.name} in this competition and all future {comp.series} competitions",
            "deleted_count": deleted_count
        }), 200
    else:
        # Clear only for this specific competition
        deleted_count = CompetitionRiderStatus.query.filter_by(
            competition_id=comp_id, rider_id=rider_id
        ).delete()
        db.session.commit()
        print(f"DEBUG: Cleared OUT status for {rider.name} in competition {comp.name} only (deleted {deleted_count} rows)")
        return jsonify({
            "ok": True,
            "message": f"Cleared OUT status for {rider.name} in this competition only",
            "deleted_count": deleted_count
        }), 200


