def _iter_crowd_pick_payloads(competition_id: int, ensure_snapshots: bool):
    """Yield (user_id, payload_dict) for users with any pick rows for this competition."""
    import json

    if ensure_snapshots:
        try:
            ensure_picks_snapshots_for_competition(int(competition_id), source="auto_lock")
        except Exception:
            pass

    snap_rows = PicksSnapshot.query.filter_by(competition_id=competition_id).all()
    snap_by_uid = {int(s.user_id): s for s in snap_rows}

    uid_sources: set[int] = set()
    for model in (RacePick, HoleshotPick, WildcardPick):
        uid_sources.update(
            int(uid)
            for (uid,) in db.session.query(model.user_id)
            .filter(model.competition_id == competition_id)
            .distinct()
            .all()
            if uid is not None
        )

    for uid in sorted(set(snap_by_uid.keys()) | uid_sources):
        snap = snap_by_uid.get(uid)
        if snap:
            try:
                payload = json.loads(snap.payload_json or "{}")
            except Exception:
                payload = {}
        else:
            payload = _build_picks_snapshot_payload(uid, competition_id)
        yield uid, payload


def _build_crowd_picks_summary(competition_id: int, comp: Competition, ensure_snapshots: bool) -> dict:
    """
    Aggregate locked picks into per-slot popularity (pseudo-'odds' / crowd share).
    Uses snapshots when available so results stay stable after lock.
    """
    is_wsx = getattr(comp, "series", None) == "WSX"
    riders_dict = {r.id: r for r in rider_query_for_list_ui().all()}

    slot_450: dict[int, dict[int, int]] = defaultdict(lambda: defaultdict(int))
    slot_250: dict[int, dict[int, int]] = defaultdict(lambda: defaultdict(int))
    holo_450: dict[int, int] = defaultdict(int)
    holo_250: dict[int, int] = defaultdict(int)
    wc_key: dict[tuple[int, int], int] = defaultdict(int)

    n_lineups = 0

    for _uid, payload in _iter_crowd_pick_payloads(competition_id, ensure_snapshots):
        race_picks = payload.get("race_picks") or []
        has_race = False
        for p in race_picks:
            try:
                rid = int(p.get("rider_id"))
                pos = int(p.get("predicted_position"))
            except (TypeError, ValueError):
                continue
            rider = riders_dict.get(rid)
            if not rider:
                continue
            if is_wsx:
                if rider.class_name == "wsx_sx1":
                    slot_450[pos][rid] += 1
                    has_race = True
                elif rider.class_name == "wsx_sx2":
                    slot_250[pos][rid] += 1
                    has_race = True
            else:
                if rider.class_name == "450cc":
                    slot_450[pos][rid] += 1
                    has_race = True
                elif rider.class_name == "250cc":
                    slot_250[pos][rid] += 1
                    has_race = True
        if has_race:
            n_lineups += 1

        holos = payload.get("holeshot_picks") or {}
        for cls, rid in holos.items():
            if rid is None:
                continue
            try:
                rid_i = int(rid)
            except (TypeError, ValueError):
                continue
            cls_s = str(cls)
            if is_wsx:
                if cls_s in ("450cc", "wsx_sx1"):
                    holo_450[rid_i] += 1
                elif cls_s in ("250cc", "wsx_sx2"):
                    holo_250[rid_i] += 1
            else:
                if cls_s == "450cc":
                    holo_450[rid_i] += 1
                elif cls_s == "250cc":
                    holo_250[rid_i] += 1

        if not is_wsx:
            wcr = payload.get("wildcard_pick")
            wcp = payload.get("wildcard_pos")
            if wcr is not None and wcp is not None:
                try:
                    wc_key[(int(wcp), int(wcr))] += 1
                except (TypeError, ValueError):
                    pass

    def rider_row(rid: int) -> dict:
        r = riders_dict.get(rid)
        if not r:
            return {"rider_id": rid, "short": "?", "name": "?"}
        num = getattr(r, "rider_number", None)
        return {
            "rider_id": rid,
            "short": f"#{num or '?'} {r.name}",
            "name": r.name,
            "num": num,
        }

    def top_for_slot(counter_by_rid: dict[int, int], topn: int = 3) -> list:
        tot = sum(counter_by_rid.values())
        if tot <= 0:
            return []
        items = sorted(counter_by_rid.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rid, c in items[:topn]:
            o = rider_row(rid)
            o["count"] = c
            o["pct"] = round(100.0 * c / tot, 1)
            out.append(o)
        return out

    def slots_to_dict(slot_map: dict[int, dict[int, int]]) -> dict:
        return {str(pos): top_for_slot(dict(slot_map.get(pos, {}))) for pos in range(1, 7)}

    def top_holeshot(hcounter: dict[int, int], topn: int = 5) -> list:
        tot = sum(hcounter.values())
        if tot <= 0:
            return []
        items = sorted(hcounter.items(), key=lambda x: (-x[1], x[0]))
        out = []
        for rid, c in items[:topn]:
            o = rider_row(rid)
            o["count"] = c
            o["pct"] = round(100.0 * c / tot, 1)
            out.append(o)
        return out

    wc_list: list = []
    if wc_key:
        tot_wc = sum(wc_key.values())
        items = sorted(wc_key.items(), key=lambda x: (-x[1], x[0]))[:8]
        for (pos, rid), c in items:
            o = rider_row(rid)
            o["position"] = pos
            o["count"] = c
            o["pct"] = round(100.0 * c / tot_wc, 1)
            wc_list.append(o)

    snap_uids = {
        int(u)
        for (u,) in db.session.query(PicksSnapshot.user_id)
        .filter(PicksSnapshot.competition_id == competition_id)
        .distinct()
        .all()
        if u is not None
    }
    pick_uids = {
        int(u)
        for (u,) in db.session.query(RacePick.user_id)
        .filter(RacePick.competition_id == competition_id)
        .distinct()
        .all()
        if u is not None
    }
    holo_uids = {
        int(u)
        for (u,) in db.session.query(HoleshotPick.user_id)
        .filter(HoleshotPick.competition_id == competition_id)
        .distinct()
        .all()
        if u is not None
    }
    wc_uids = {
        int(u)
        for (u,) in db.session.query(WildcardPick.user_id)
        .filter(WildcardPick.competition_id == competition_id)
        .distinct()
        .all()
        if u is not None
    }
    n_users = len(snap_uids | pick_uids | holo_uids | wc_uids)

    return {
        "n_lineups": n_lineups,
        "n_users_with_snapshots_or_picks": n_users,
        "slots_450": slots_to_dict(slot_450),
        "slots_250": slots_to_dict(slot_250),
        "holeshot_450": top_holeshot(holo_450),
        "holeshot_250": top_holeshot(holo_250),
        "wildcard_top": wc_list,
    }


@app.route("/crowd_picks_summary/<int:competition_id>")
def crowd_picks_summary(competition_id):
    """Crowd-popularitet för teaser — kräver inloggning + låsta picks eller färdigt race."""
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401

    comp = Competition.query.get_or_404(competition_id)
    picks_locked = is_picks_locked(comp)
    series_u = (getattr(comp, "series", None) or "").upper()
    if series_u == "MXON":
        try:
            from mxon_fantasy import mxon_has_official_results

            has_results = mxon_has_official_results(int(competition_id))
        except Exception:
            has_results = False
    else:
        has_results = (
            CompetitionResult.query.filter_by(competition_id=competition_id).first()
            is not None
        )

    if not _can_view_other_users_picks(comp):
        return jsonify({"error": "Picks måste vara låsta eller race färdigt."}), 403

    try:
        if series_u == "MXON":
            from mxon_fantasy import build_mxon_crowd_summary

            summary = build_mxon_crowd_summary(int(competition_id))
        else:
            summary = _build_crowd_picks_summary(
                competition_id, comp, ensure_snapshots=picks_locked or has_results
            )
        return jsonify(
            {
                "ok": True,
                "competition": {"id": comp.id, "name": comp.name, "series": comp.series},
                "crowd": summary,
            }
        )
    except Exception as e:
        print(f"ERROR crowd_picks_summary: {e}")
        return jsonify({"error": str(e)}), 500


@app.route("/get_other_users_picks/<int:competition_id>")
def get_other_users_picks(competition_id):
    try:
        if "user_id" not in session:
            return jsonify({"error": "not_logged_in"}), 401
        
        # Get competition to determine series
        comp = Competition.query.get_or_404(competition_id)
        series_u = (getattr(comp, "series", None) or "").upper()
        
        picks_locked = is_picks_locked(comp)
        if series_u == "MXON":
            try:
                from mxon_fantasy import mxon_has_official_results

                has_results = mxon_has_official_results(int(competition_id))
            except Exception:
                has_results = False
        else:
            has_results = (
                CompetitionResult.query.filter_by(competition_id=competition_id).first()
                is not None
            )
        
        print(f"DEBUG: get_other_users_picks - Competition: {comp.name}, picks_locked: {picks_locked}, has_results: {has_results}")
        
        if not _can_view_other_users_picks(comp):
            error_msg = f"Picks måste vara låsta eller race måste vara färdigt för att se andra användares picks (picks_locked={picks_locked}, has_results={has_results})"
            print(f"DEBUG: get_other_users_picks - Access denied: {error_msg}")
            return jsonify({"error": error_msg}), 403

        if series_u == "MXON":
            from mxon_fantasy import build_mxon_crowd_summary, list_other_users_mxon_picks

            users_picks = list_other_users_mxon_picks(
                int(competition_id),
                exclude_user_id=int(session["user_id"]),
            )
            crowd_payload = None
            try:
                crowd_payload = build_mxon_crowd_summary(int(competition_id))
            except Exception as ex_crowd:
                print(f"WARNING: mxon crowd summary skipped: {ex_crowd}")
            return jsonify(
                {
                    "users": users_picks,
                    "crowd": crowd_payload,
                    "competition": {
                        "id": comp.id,
                        "name": comp.name,
                        "series": comp.series,
                    },
                }
            )

        # When locked, take snapshots (best-effort) and prefer snapshot data for stability.
        if picks_locked:
            try:
                ensure_picks_snapshots_for_competition(int(competition_id), source="auto_lock")
            except Exception:
                pass
        
        is_wsx = getattr(comp, 'series', None) == 'WSX'
        
        # Ladda inte rider_image_data — varje blob kan vara hundratals KB (OOM på Render).
        riders_dict = {r.id: r for r in rider_query_for_list_ui().all()}
        
        # Get all users except current user
        current_user_id = session["user_id"]
        other_users = User.query.filter(User.id != current_user_id).all()
        
        print(f"DEBUG: Found {len(other_users)} other users")
        print(f"DEBUG: Competition {comp.name} is WSX: {is_wsx}")
    
        users_picks = []
        for user in other_users:
            snapshot_payload = None
            if picks_locked:
                snap = PicksSnapshot.query.filter_by(user_id=user.id, competition_id=competition_id).first()
                if snap:
                    import json

                    try:
                        snapshot_payload = json.loads(snap.payload_json or "{}")
                    except Exception:
                        snapshot_payload = None

            # Get race picks for this user (only top 6 per class)
            if snapshot_payload:
                race_picks = snapshot_payload.get("race_picks", []) or []
            else:
                race_picks = RacePick.query.filter_by(user_id=user.id, competition_id=competition_id).all()
            
            picks = []
            picks_450 = []
            picks_250 = []
            
            for pick in race_picks:
                rider_id = pick.get("rider_id") if snapshot_payload else pick.rider_id
                pos = pick.get("predicted_position") if snapshot_payload else pick.predicted_position
                rider = riders_dict.get(rider_id)
                if rider:
                    # Ensure we have valid rider data
                    rider_number = getattr(rider, 'rider_number', '?') or '?'
                    rider_name = getattr(rider, 'name', 'Unknown') or 'Unknown'
                    bike_brand = getattr(rider, 'bike_brand', 'Unknown') or 'Unknown'
                    
                    pick_data = {
                        "position": pos,
                        "class": rider.class_name,
                        "rider_name": f"#{rider_number} {rider_name} ({bike_brand})"
                    }
                    print(f"DEBUG: Created pick_data: {pick_data}")
                    
                    # Handle both regular classes and WSX classes
                    if is_wsx:
                        # WSX: map wsx_sx1 to picks_450, wsx_sx2 to picks_250
                        if rider.class_name == 'wsx_sx1' and len(picks_450) < 6:
                            picks_450.append(pick_data)
                        elif rider.class_name == 'wsx_sx2' and len(picks_250) < 6:
                            picks_250.append(pick_data)
                    else:
                        # Regular series: 450cc and 250cc
                        if rider.class_name == '450cc' and len(picks_450) < 6:
                            picks_450.append(pick_data)
                        elif rider.class_name == '250cc' and len(picks_250) < 6:
                            picks_250.append(pick_data)
        
            # Sort by position and take only top 6
            picks_450.sort(key=lambda x: x['position'])
            picks_250.sort(key=lambda x: x['position'])
            
            picks = picks_450 + picks_250
            
            # Get holeshot picks
            if snapshot_payload:
                holeshot_map = snapshot_payload.get("holeshot_picks", {}) or {}
                holeshot_picks = [{"class_name": k, "rider_id": v} for k, v in holeshot_map.items()]
            else:
                holeshot_picks = HoleshotPick.query.filter_by(user_id=user.id, competition_id=competition_id).all()
            holeshot_450 = None
            holeshot_250 = None
            
            for holeshot in holeshot_picks:
                cls = holeshot.get("class_name") if snapshot_payload else holeshot.class_name
                rid = holeshot.get("rider_id") if snapshot_payload else holeshot.rider_id
                rider = riders_dict.get(rid)
                if rider:
                    if is_wsx:
                        # WSX: check for wsx_sx1 and wsx_sx2, or legacy 450cc/250cc mapping
                        if (cls == '450cc' or cls == 'wsx_sx1') and not holeshot_450:
                            holeshot_450 = {
                                "rider_number": getattr(rider, 'rider_number', '?') or '?',
                                "rider_name": getattr(rider, 'name', 'Unknown') or 'Unknown'
                            }
                        elif (cls == '250cc' or cls == 'wsx_sx2') and not holeshot_250:
                            holeshot_250 = {
                                "rider_number": getattr(rider, 'rider_number', '?') or '?',
                                "rider_name": getattr(rider, 'name', 'Unknown') or 'Unknown'
                            }
                    else:
                        # Regular series
                        if cls == '450cc' and not holeshot_450:
                            holeshot_450 = {
                                "rider_number": getattr(rider, 'rider_number', '?') or '?',
                                "rider_name": getattr(rider, 'name', 'Unknown') or 'Unknown'
                            }
                        elif cls == '250cc' and not holeshot_250:
                            holeshot_250 = {
                                "rider_number": getattr(rider, 'rider_number', '?') or '?',
                                "rider_name": getattr(rider, 'name', 'Unknown') or 'Unknown'
                            }
        
            # Get wildcard pick (only for non-WSX series)
            wildcard = None
            wildcard_pick = None
            if not is_wsx:
                if snapshot_payload:
                    wc_rider_id = snapshot_payload.get("wildcard_pick")
                    wc_pos = snapshot_payload.get("wildcard_pos")
                    if wc_rider_id is not None or wc_pos is not None:
                        wildcard_pick = type("WCPick", (), {"rider_id": wc_rider_id, "position": wc_pos})()
                else:
                    wildcard_pick = WildcardPick.query.filter_by(user_id=user.id, competition_id=competition_id).first()
            if wildcard_pick:
                rider = riders_dict.get(wildcard_pick.rider_id)
                if rider:
                    wildcard = {
                        "position": wildcard_pick.position,
                        "rider_number": getattr(rider, 'rider_number', '?') or '?',
                        "rider_name": getattr(rider, 'name', 'Unknown') or 'Unknown'
                    }
            
            print(f"DEBUG: User {user.username} - picks: {len(picks)}, holeshot_450: {holeshot_450 is not None}, holeshot_250: {holeshot_250 is not None}, wildcard: {wildcard is not None}")
            
            if picks or holeshot_450 or holeshot_250 or wildcard:  # Only include users who have made any picks
                print(f"DEBUG: Including user {user.username} - picks_450: {picks_450}")
                print(f"DEBUG: Including user {user.username} - picks_250: {picks_250}")
                user_data = {
                    "username": user.username,
                    "display_name": getattr(user, 'display_name', None) or user.username,
                    "picks_450": picks_450,
                    "picks_250": picks_250,
                    "holeshot_450": holeshot_450,
                    "holeshot_250": holeshot_250,
                    "wildcard": wildcard,
                    "is_wsx": is_wsx  # Include series info for frontend
                }
                print(f"DEBUG: Adding user data: {user_data['display_name']} (username: {user_data['username']})")
                users_picks.append(user_data)
            else:
                print(f"DEBUG: Excluding user {user.username} - no picks found")
        
        print(f"DEBUG: Returning {len(users_picks)} users with picks")
        crowd_payload = None
        try:
            crowd_payload = _build_crowd_picks_summary(
                competition_id, comp, ensure_snapshots=picks_locked or has_results
            )
        except Exception as ex_crowd:
            print(f"WARNING: crowd summary skipped in get_other_users_picks: {ex_crowd}")

        return jsonify(
            {
                "users": users_picks,
                "crowd": crowd_payload,
                "competition": {
                    "id": comp.id,
                    "name": comp.name,
                    "series": comp.series,
                },
            }
        )
    except Exception as e:
        import traceback
        error_trace = traceback.format_exc()
        print(f"ERROR in get_other_users_picks: {e}")
        print(f"ERROR traceback: {error_trace}")
        db.session.rollback()
        return jsonify({"error": f"Okänt fel: {str(e)}"}), 500

@app.post("/save_picks")
def save_picks():
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401

    data = request.get_json(force=True)
    uid = session["user_id"]

    # 1) Hämta tävlingen
    try:
        comp_id = int(data.get("competition_id"))
    except Exception:
        return jsonify({"error": "invalid_competition_id"}), 400

    comp = Competition.query.get(comp_id)
    if not comp:
        return jsonify({"error": "competition_not_found"}), 404

    series_u = (getattr(comp, "series", None) or "").strip().upper()
    if series_u == "MXGP":
        try:
            from mxgp_fantasy import mxgp_user_can_play

            if not mxgp_user_can_play(is_admin=is_admin_user()):
                return jsonify({
                    "error": "MXGP är under construction — tippa öppnar till 2027."
                }), 403
        except Exception:
            if not is_admin_user():
                return jsonify({"error": "MXGP är under construction."}), 403

    # Use the unified picks lock check function
    picks_locked = is_picks_locked(comp)

    # If picks are locked, reject the save
    if picks_locked:
        return jsonify({"error": "Picks är låsta! Du kan inte längre ändra dina val."}), 403

    # 2) Hämta OUT‑förare för detta race (viktigt)
    out_ids = set(
        rid
        for (rid,) in db.session.query(CompetitionRiderStatus.rider_id)
        .filter(
            CompetitionRiderStatus.competition_id == comp.id,
            CompetitionRiderStatus.status == "OUT",
        )
        .all()
    )

    # 3) Validera att inga dubletter finns i picks
    picks = data.get("picks", [])

    new_rider_ids = [int(p.get("rider_id")) for p in picks if p.get("rider_id")]
    if len(new_rider_ids) != len(set(new_rider_ids)):
        return jsonify({"error": "Du kan inte välja samma förare flera gånger"}), 400

    seen_number_keys = set()
    # --- VALIDERA ALLT FÖRST (inga raderingar) så att vi inte tömmer användarens picks vid valideringsfel ---
    wc_pick = data.get("wildcard_pick")
    wc_pos = data.get("wildcard_pos")
    skips_wildcard = series_u in ("WSX", "MXGP")
    if skips_wildcard:
        wc_pick = None
        wc_pos = None
        if series_u == "WSX":
            try:
                prune_off_roster_wsx_picks(int(comp.id))
            except Exception:
                db.session.rollback()

    wsx_allowed_ids = _wsx_official_roster_ids() if series_u == "WSX" else set()
    mxgp_allowed_ids: set[int] = set()
    if series_u == "MXGP":
        try:
            from mxgp_fantasy import mxgp_official_roster_ids

            mxgp_allowed_ids = mxgp_official_roster_ids()
        except Exception:
            mxgp_allowed_ids = set()
    smx_allowed_ids: set[int] = set()
    if series_u == "SMX":
        try:
            sync_smx_playoff_entry_list(comp)
            # refresh OUT after sync
            out_ids = set(
                rid
                for (rid,) in db.session.query(CompetitionRiderStatus.rider_id)
                .filter(
                    CompetitionRiderStatus.competition_id == comp.id,
                    CompetitionRiderStatus.status == "OUT",
                )
                .all()
            )
            field = smx_playoff_field_ids(competition=comp)
            smx_allowed_ids = set(field.get("450") or ()) | set(field.get("250") or ())
        except Exception as sync_err:
            print(f"SMX save sync skipped: {sync_err}")
            db.session.rollback()

    riders_450_ids = []
    for p in picks:
        try:
            pos = int(p.get("position"))
            rid = int(p.get("rider_id"))
        except Exception:
            return jsonify({"error": "Ogiltig pick-format"}), 400
        rider = Rider.query.get(rid)
        if not rider:
            return jsonify({"error": f"Förare med id {rid} hittades inte"}), 400
        if rider.id in out_ids:
            return jsonify({"error": f"{rider.name} är OUT för detta race — välj om"}), 400
        if smx_allowed_ids and int(rider.id) not in smx_allowed_ids:
            return jsonify({
                "error": f"{rider.name} är inte med på entry list för detta race — välj om"
            }), 400
        if series_u == "WSX" and int(rider.id) not in wsx_allowed_ids:
            return jsonify({
                "error": f"{rider.name} är inte med i WSX 2026-rostern — välj om dina picks"
            }), 400
        if series_u == "MXGP" and mxgp_allowed_ids and int(rider.id) not in mxgp_allowed_ids:
            return jsonify({
                "error": f"{rider.name} är inte med i MXGP-rostern — välj om dina picks"
            }), 400

        # Rider-id-unikitet redan kontrollerad ovan (set-jämförelse).
        # rider_number-check hoppas över — samma nummer kan finnas i SX1 och SX2.

        if rider.class_name == "250cc" and comp.coast_250 in ("east", "west"):
            if rider.coast_250 not in (comp.coast_250, "both"):
                return jsonify({"error": "250-förare matchar inte denna coast"}), 400
        if rider.class_name in ("450cc", "wsx_sx1", "mxgp") or p.get("class") in (
            "450cc",
            "wsx_sx1",
            "mxgp",
        ):
            riders_450_ids.append(rid)

    if wc_pick and wc_pos:
        try:
            wc_pick_i = int(wc_pick)
            wc_pos_i = int(wc_pos)
            if wc_pick_i in out_ids:
                wc_rider = Rider.query.get(wc_pick_i)
                wc_name = wc_rider.name if wc_rider else "Wildcard-föraren"
                return jsonify({"error": f"{wc_name} är OUT för detta race — välj om"}), 400
            if wc_pick_i in riders_450_ids:
                return jsonify({"error": "Du kan inte välja samma förare för wildcard som i top 6"}), 400
        except Exception:
            return jsonify({"error": "Ogiltig wildcard-val"}), 400

    hs_label_450 = "MXGP" if series_u == "MXGP" else ("SX1" if series_u == "WSX" else "450cc")
    hs_label_250 = "MX2" if series_u == "MXGP" else ("SX2" if series_u == "WSX" else "250cc")

    hs450 = data.get("holeshot_450")
    if not hs450:
        return jsonify({"error": f"Du måste välja en holeshot-förare för {hs_label_450}"}), 400
    try:
        rid = int(hs450)
        if rid in out_ids:
            hs_rider = Rider.query.get(rid)
            hs_name = hs_rider.name if hs_rider else "Holeshot-föraren"
            return jsonify({"error": f"{hs_name} är OUT för detta race — välj om"}), 400
        if series_u == "WSX" and rid not in wsx_allowed_ids:
            return jsonify({"error": "Holeshot SX1 måste vara en 2026-rosterförare"}), 400
        if series_u == "MXGP" and mxgp_allowed_ids and rid not in mxgp_allowed_ids:
            return jsonify({"error": "Holeshot MXGP måste vara en rosterförare"}), 400
    except Exception:
        return jsonify({"error": f"Ogiltig holeshot-förare för {hs_label_450}"}), 400

    hs250 = data.get("holeshot_250")
    if not hs250:
        return jsonify({"error": f"Du måste välja en holeshot-förare för {hs_label_250}"}), 400
    try:
        rid = int(hs250)
        rider = Rider.query.get(rid)
        if rider and rider.id in out_ids:
            return jsonify({"error": f"{rider.name} är OUT för detta race — välj om"}), 400
        if series_u == "WSX" and rid not in wsx_allowed_ids:
            return jsonify({"error": "Holeshot SX2 måste vara en 2026-rosterförare"}), 400
        if series_u == "MXGP" and mxgp_allowed_ids and rid not in mxgp_allowed_ids:
            return jsonify({"error": "Holeshot MX2 måste vara en rosterförare"}), 400
        if rider and comp.coast_250 in ("east", "west"):
            if rider.coast_250 not in (comp.coast_250, "both"):
                return jsonify({"error": "250-holeshot matchar inte denna coast"}), 400
    except Exception:
        return jsonify({"error": f"Ogiltig holeshot-förare för {hs_label_250}"}), 400

    if not skips_wildcard:
        if not wc_pick:
            return jsonify({"error": "Du måste välja en wildcard-förare"}), 400
        if not wc_pos or str(wc_pos).strip() == "":
            return jsonify({"error": "Du måste välja en wildcard-position (rulla tärningen)"}), 400

    qual_mxgp = data.get("qualifying_mxgp") or data.get("qualifying_450")
    qual_mx2 = data.get("qualifying_mx2") or data.get("qualifying_250")
    if series_u == "MXGP":
        if not qual_mxgp:
            return jsonify({"error": "Du måste tippa kvalvinnare i MXGP"}), 400
        if not qual_mx2:
            return jsonify({"error": "Du måste tippa kvalvinnare i MX2"}), 400
        for qid, qlabel in ((qual_mxgp, "MXGP"), (qual_mx2, "MX2")):
            try:
                qrid = int(qid)
            except Exception:
                return jsonify({"error": f"Ogiltig kvalvinnare för {qlabel}"}), 400
            if qrid in out_ids:
                qr = Rider.query.get(qrid)
                return jsonify({
                    "error": f"{(qr.name if qr else 'Föraren')} (kval {qlabel}) är OUT — välj om"
                }), 400
            if mxgp_allowed_ids and qrid not in mxgp_allowed_ids:
                return jsonify({"error": f"Kvalvinnare {qlabel} måste vara rosterförare"}), 400

    # 4) All validering klar – nu radera och spara (en commit så inget delvis tillstånd)
    deleted_picks = RacePick.query.filter_by(user_id=uid, competition_id=comp_id).delete()
    deleted_holeshots = HoleshotPick.query.filter_by(user_id=uid, competition_id=comp_id).delete()
    deleted_wildcards = WildcardPick.query.filter_by(user_id=uid, competition_id=comp_id).delete()
    deleted_quals = QualifyingPick.query.filter_by(user_id=uid, competition_id=comp_id).delete()
    print(
        f"DEBUG: Deleted {deleted_picks} old picks, {deleted_holeshots} old holeshots, "
        f"{deleted_wildcards} old wildcards, {deleted_quals} old qualifying"
    )

    saved_picks = 0
    for p in picks:
        try:
            pos = int(p.get("position"))
            rid = int(p.get("rider_id"))
        except Exception:
            continue
        rider = Rider.query.get(rid)
        if not rider:
            continue
        db.session.add(
            RacePick(
                user_id=uid,
                competition_id=comp_id,
                rider_id=rid,
                predicted_position=pos
            )
        )
        saved_picks += 1
        print(f"DEBUG: Added pick - {rider.name} at position {pos}")

    if series_u == "WSX":
        hs_class_450, hs_class_250 = "wsx_sx1", "wsx_sx2"
    elif series_u == "MXGP":
        hs_class_450, hs_class_250 = "mxgp", "mx2"
    else:
        hs_class_450, hs_class_250 = "450cc", "250cc"
    rid = int(hs450)
    db.session.add(
        HoleshotPick(
            user_id=uid,
            competition_id=comp_id,
            rider_id=rid,
            class_name=hs_class_450,
        )
    )
    rid = int(hs250)
    db.session.add(
        HoleshotPick(
            user_id=uid,
            competition_id=comp_id,
            rider_id=rid,
            class_name=hs_class_250,
        )
    )

    if not skips_wildcard and wc_pick and wc_pos:
        wc_pick_i = int(wc_pick)
        wc_pos_i = int(wc_pos)
        existing_wc = WildcardPick.query.filter_by(user_id=uid, competition_id=comp_id).first()
        if not existing_wc:
            existing_wc = WildcardPick(user_id=uid, competition_id=comp_id)
            db.session.add(existing_wc)
        existing_wc.rider_id = wc_pick_i
        existing_wc.position = wc_pos_i

    if series_u == "MXGP" and qual_mxgp and qual_mx2:
        db.session.add(
            QualifyingPick(
                user_id=uid,
                competition_id=comp_id,
                rider_id=int(qual_mxgp),
                class_name="mxgp",
            )
        )
        db.session.add(
            QualifyingPick(
                user_id=uid,
                competition_id=comp_id,
                rider_id=int(qual_mx2),
                class_name="mx2",
            )
        )

    db.session.commit()
    return jsonify({"message": "Picks sparade"}), 200

@app.post("/clear_my_picks/<int:competition_id>")
def clear_my_picks(competition_id: int):
    """
    Rensa alla picks (topp 6, holeshot, wildcard) för inloggad användare i en tävling.
    Används från race_picks-sidan som en \"börja om\"-knapp.
    """
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401

    comp = Competition.query.get(competition_id)
    if not comp:
        return jsonify({"error": "competition_not_found"}), 404

    # Samma låslogik som save_picks – efter låsning får man inte rensa
    if is_picks_locked(comp):
        return jsonify({"error": "Picks är låsta! Du kan inte längre ändra eller rensa dina val."}), 403

    uid = session["user_id"]

    deleted_race = RacePick.query.filter_by(user_id=uid, competition_id=competition_id).delete()
    deleted_holo = HoleshotPick.query.filter_by(user_id=uid, competition_id=competition_id).delete()
    deleted_qual = QualifyingPick.query.filter_by(user_id=uid, competition_id=competition_id).delete()
    wc = WildcardPick.query.filter_by(user_id=uid, competition_id=competition_id).first()
    if wc:
        wc.rider_id = None
    deleted_wc = 0

    db.session.commit()

    print(
        f"DEBUG: clear_my_picks – user_id={uid}, competition_id={competition_id}, "
        f"deleted race={deleted_race}, holeshot={deleted_holo}, qualifying={deleted_qual}, "
        f"wildcard_rider_cleared={bool(wc)}"
    )

    return jsonify({"message": "Alla dina val för denna tävling har rensats."}), 200


@app.post("/clear_my_bonus_picks/<int:competition_id>")
def clear_my_bonus_picks(competition_id: int):
    """
    Rensa holeshot + wildcard-förare men behåll topp 6 och wildcard-plats.
    """
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401

    comp = Competition.query.get(competition_id)
    if not comp:
        return jsonify({"error": "competition_not_found"}), 404

    if is_picks_locked(comp):
        return jsonify({"error": "Picks är låsta! Du kan inte längre ändra eller rensa dina val."}), 403

    uid = session["user_id"]
    deleted_holo = HoleshotPick.query.filter_by(user_id=uid, competition_id=competition_id).delete()
    deleted_qual = QualifyingPick.query.filter_by(user_id=uid, competition_id=competition_id).delete()
    wc = WildcardPick.query.filter_by(user_id=uid, competition_id=competition_id).first()
    if wc:
        wc.rider_id = None

    db.session.commit()

    print(
        f"DEBUG: clear_my_bonus_picks – user_id={uid}, competition_id={competition_id}, "
        f"deleted holeshot={deleted_holo}, qualifying={deleted_qual}, wildcard_rider_cleared={bool(wc)}"
    )

    return jsonify({
        "message": "Holeshot och bonusval rensade. Topp 6 behölls.",
        "deleted_holeshot": deleted_holo,
        "deleted_qualifying": deleted_qual,
        "wildcard_position_kept": bool(wc and wc.position is not None),
    }), 200




@app.post("/lock_wildcard_pos")
def lock_wildcard_pos():
    if "user_id" not in session:
        return jsonify({"error": "not_logged_in"}), 401
    data = request.get_json(force=True)
    comp_id = int(data.get("competition_id"))
    pos = int(data.get("position"))
    uid = session["user_id"]

    wc = WildcardPick.query.filter_by(user_id=uid, competition_id=comp_id).first()
    if wc and wc.position is not None:
        return (
            jsonify(
                {
                    "error": "Wildcard-platsen är redan bestämd.",
                    "status": "already_locked",
                    "position": int(wc.position),
                }
            ),
            409,
        )

    if not wc:
        wc = WildcardPick(user_id=uid, competition_id=comp_id, position=pos)
        db.session.add(wc)
    else:
        wc.position = pos
    db.session.commit()
    return jsonify({"status": "locked", "position": pos}), 200


# holeshot_result_class_bucket / holeshot_results_by_bucket /
# holeshot_pick_class_for_result → services.scoring (imported above)



def _build_race_results_detail(
    user_id: int,
    competition_id: int,
    *,
    dedupe_picks: bool = False,
) -> dict:
    """Structured race score breakdown for detail modal."""
    comp = Competition.query.get(competition_id)
    actual = CompetitionResult.query.filter_by(competition_id=competition_id).all()
    actual_by_rider = {r.rider_id: r for r in actual}

    all_picks = RacePick.query.filter_by(user_id=user_id, competition_id=competition_id).all()
    if dedupe_picks:
        seen_picks: dict[tuple, RacePick] = {}
        for pick in all_picks:
            key = (pick.user_id, pick.competition_id, pick.rider_id)
            if key not in seen_picks or pick.pick_id > seen_picks[key].pick_id:
                seen_picks[key] = pick
        picks = list(seen_picks.values())
    else:
        picks = all_picks

    picks_450: list[dict] = []
    picks_250: list[dict] = []
    other_lines: list[dict] = []
    race_points = 0
    series_u = (getattr(comp, "series", None) or "").upper() if comp else ""
    is_wsx = series_u == "WSX"
    is_mxgp = series_u == "MXGP"

    for p in picks:
        rider = Rider.query.get(p.rider_id)
        rider_name = rider.name if rider else f"Förare #{p.rider_id}"
        cls = (rider.class_name if rider else "") or ""
        # Prefer result row class for WSX (wsx_sx1/wsx_sx2) when rider row is stale
        act = actual_by_rider.get(p.rider_id)
        result_cls = (getattr(act, "class_name", None) or "").strip() if act else ""
        bucket_cls = result_cls or cls
        if not act:
            other_lines.append(
                {
                    "kind": "note",
                    "status": "error",
                    "text": f"{rider_name} — inget resultat hittades",
                    "points": 0,
                }
            )
            continue

        points = calculate_race_pick_points(p.predicted_position, act.position)
        race_points += points
        diff = abs(int(p.predicted_position) - int(act.position)) if p.predicted_position and act.position else 0

        if points == 25:
            status = "perfect"
            hint = "Exakt rätt plats → +25p"
        elif points > 0:
            status = "close"
            hint = f"{diff} {'plats' if diff == 1 else 'platser'} fel → +{points}p"
        else:
            status = "miss"
            hint = "Utanför poängzonen → 0p"

        row = {
            "kind": "pick",
            "status": status,
            "rider_name": rider_name,
            "predicted": int(p.predicted_position),
            "actual": int(act.position),
            "points": int(points),
            "diff": int(diff),
            "hint": hint,
        }
        if bucket_cls in ("450cc", "wsx_sx1", "sx1", "mxgp"):
            picks_450.append(row)
        elif bucket_cls in ("250cc", "wsx_sx2", "sx2", "mx2"):
            picks_250.append(row)
        else:
            other_lines.append(row)

    picks_450.sort(key=lambda x: x.get("predicted", 99))
    picks_250.sort(key=lambda x: x.get("predicted", 99))

    all_holopicks = HoleshotPick.query.filter_by(user_id=user_id, competition_id=competition_id).all()
    if dedupe_picks:
        seen_holeshots: dict[tuple, HoleshotPick] = {}
        for hp in all_holopicks:
            key = (hp.user_id, hp.competition_id, hp.class_name)
            if key not in seen_holeshots or hp.id > seen_holeshots[key].id:
                seen_holeshots[key] = hp
        holopicks = list(seen_holeshots.values())
    else:
        holopicks = all_holopicks

    holos = HoleshotResult.query.filter_by(competition_id=competition_id).all()
    holo_by_class = holeshot_results_by_bucket(holos)
    holeshot_rows: list[dict] = []
    holeshot_450_correct = False
    holeshot_250_correct = False
    holeshot_450_name = ""
    holeshot_250_name = ""
    holeshot_points = 0

    for hp in holopicks:
        bucket = holeshot_pick_class_for_result(hp.class_name)
        act = holo_by_class.get(bucket)
        rider = Rider.query.get(hp.rider_id)
        rider_name = rider.name if rider else f"Förare #{hp.rider_id}"
        if is_wsx:
            label = "SX1" if bucket == "450cc" else "SX2" if bucket == "250cc" else (hp.class_name or "Holeshot")
        elif is_mxgp:
            label = "MXGP" if bucket == "450cc" else "MX2" if bucket == "250cc" else (hp.class_name or "Holeshot")
        else:
            label = "450cc" if bucket == "450cc" else "250cc" if bucket == "250cc" else (hp.class_name or "Holeshot")

        actual_rider_name = None
        if act and act.rider_id:
            actual_rider = Rider.query.get(act.rider_id)
            actual_rider_name = (
                actual_rider.name if actual_rider else f"Förare #{act.rider_id}"
            )

        if act and act.rider_id == hp.rider_id:
            if bucket == "450cc":
                holeshot_450_correct = True
                holeshot_450_name = rider_name
            elif bucket == "250cc":
                holeshot_250_correct = True
                holeshot_250_name = rider_name
            holeshot_rows.append(
                {
                    "kind": "holeshot",
                    "status": "correct",
                    "label": label,
                    "rider_name": rider_name,
                    "picked_name": rider_name,
                    "actual_name": actual_rider_name or rider_name,
                    "points": 10,
                    "hint": "Rätt holeshot → +10p",
                }
            )
        else:
            if actual_rider_name:
                hint = f"Gissade {rider_name} — holeshot: {actual_rider_name}"
            else:
                hint = f"Gissade {rider_name} — inget holeshot-resultat registrerat"
            holeshot_rows.append(
                {
                    "kind": "holeshot",
                    "status": "wrong",
                    "label": label,
                    "rider_name": rider_name,
                    "picked_name": rider_name,
                    "actual_name": actual_rider_name,
                    "points": 0,
                    "hint": hint,
                }
            )

    if holeshot_450_correct and holeshot_250_correct:
        holeshot_points = 25
        label_450 = "SX1" if is_wsx else "450cc"
        label_250 = "SX2" if is_wsx else "250cc"
        holeshot_rows = [
            {
                "kind": "holeshot",
                "status": "correct",
                "label": label_450,
                "rider_name": holeshot_450_name or "—",
                "points": 10,
                "hint": f"Rätt holeshot {label_450}",
            },
            {
                "kind": "holeshot",
                "status": "correct",
                "label": label_250,
                "rider_name": holeshot_250_name or "—",
                "points": 10,
                "hint": f"Rätt holeshot {label_250}",
            },
            {
                "kind": "bonus",
                "status": "bonus",
                "text": "Båda holeshots rätt — +5 bonus",
                "points": 5,
                "hint": "25p totalt för holeshot",
            },
        ]
    else:
        holeshot_points = sum(int(r.get("points") or 0) for r in holeshot_rows if r.get("kind") == "holeshot")

    wildcard_rows: list[dict] = []
    wildcard_points = 0
    wc = None if is_wsx else WildcardPick.query.filter_by(user_id=user_id, competition_id=competition_id).first()
    if wc:
        actual_450cc = []
        for r in actual:
            rider = Rider.query.get(r.rider_id)
            if rider and rider.class_name == "450cc":
                actual_450cc.append(r)
        target = next((r for r in actual_450cc if r.position == wc.position), None)
        rider = Rider.query.get(wc.rider_id)
        rider_name = rider.name if rider else f"Förare #{wc.rider_id}"
        pos_label = int(wc.position) if wc.position else None
        actual_at_pos_name = None
        if target and target.rider_id:
            actual_rider = Rider.query.get(target.rider_id)
            actual_at_pos_name = (
                actual_rider.name if actual_rider else f"Förare #{target.rider_id}"
            )

        if target and target.rider_id == wc.rider_id:
            wildcard_points = 15
            wildcard_rows.append(
                {
                    "kind": "wildcard",
                    "status": "correct",
                    "rider_name": rider_name,
                    "picked_name": rider_name,
                    "actual_name": actual_at_pos_name or rider_name,
                    "position": pos_label,
                    "points": 15,
                    "hint": f"Rätt på plats {wc.position} (wildcard 10–20) → +15p",
                }
            )
        else:
            if actual_at_pos_name and pos_label:
                hint = (
                    f"Gissade {rider_name} på plats {pos_label} (10–20) — där kom {actual_at_pos_name}"
                )
            elif pos_label:
                hint = (
                    f"Gissade {rider_name} på plats {pos_label} (10–20) — ingen förare registrerad"
                )
            else:
                hint = "Fel wildcard → 0p"
            wildcard_rows.append(
                {
                    "kind": "wildcard",
                    "status": "wrong",
                    "rider_name": rider_name,
                    "picked_name": rider_name,
                    "actual_name": actual_at_pos_name,
                    "position": pos_label,
                    "points": 0,
                    "hint": hint,
                }
            )

    total = race_points + holeshot_points + wildcard_points

    # Legacy pipe-delimited lines for any old clients
    breakdown: list[str] = []
    for bucket in (picks_450, picks_250):
        for row in bucket:
            if row["status"] == "perfect":
                breakdown.append(
                    f"✅|PERFEKT|{row['rider_name']}|{row['predicted']}|{row['actual']}|+{row['points']}"
                )
            elif row["status"] == "close":
                breakdown.append(
                    f"▲|{row['diff']}PLATSER|{row['rider_name']}|{row['predicted']}|{row['actual']}|+{row['points']}"
                )
            else:
                breakdown.append(
                    f"❌|MISS|{row['rider_name']}|{row['predicted']}|{row['actual']}|0"
                )

    return {
        "ok": True,
        "competition": {
            "id": int(competition_id),
            "name": comp.name if comp else None,
            "series": comp.series if comp else None,
            "event_date": comp.event_date.isoformat() if comp and comp.event_date else None,
        },
        "total": int(total),
        "summary": {
            "race_points": int(race_points),
            "holeshot_points": int(holeshot_points),
            "wildcard_points": int(wildcard_points),
        },
        "sections": {
            "picks_450": picks_450,
            "picks_250": picks_250,
            "holeshot": holeshot_rows,
            "wildcard": wildcard_rows,
            "other": other_lines,
        },
        "labels": {
            "primary": "SX1" if is_wsx else "450cc",
            "secondary": "SX2" if is_wsx else "250cc",
        },
        "breakdown": breakdown,
    }


def _completed_competitions_for_recap(limit: int | None = 8) -> list[Competition]:
    """Competitions with results (all series incl. WSX), newest first."""
    ids_with_results = [
        row[0] for row in db.session.query(CompetitionResult.competition_id).distinct().all()
    ]
    if not ids_with_results:
        return []
    q = (
        Competition.query.filter(Competition.id.in_(ids_with_results))
        .order_by(Competition.event_date.desc().nullslast(), Competition.id.desc())
    )
    if limit:
        q = q.limit(limit)
    return q.all()


def _competition_is_older_or_same(comp: Competition, anchor: Competition) -> bool:
    """True if comp is the anchor or chronologically older."""
    if int(comp.id) == int(anchor.id):
        return True
    a_date = getattr(anchor, "event_date", None)
    c_date = getattr(comp, "event_date", None)
    if a_date and c_date:
        if c_date < a_date:
            return True
        if c_date > a_date:
            return False
        return int(comp.id) <= int(anchor.id)
    return int(comp.id) <= int(anchor.id)


def _dismiss_din_kvall_for_user(
    user_id: int,
    anchor: Competition,
    *,
    include_anchor: bool = True,
) -> int:
    """
    Mark Din kväll seen for the anchor race and (by default) all older completed races.
    Prevents a queue of old popups (Millville → Southwick → …) after a reset.
    """
    existing = {
        int(r.competition_id)
        for r in UserRaceRecapDismissal.query.filter_by(user_id=int(user_id)).all()
    }
    added = 0
    for comp in _completed_competitions_for_recap(limit=40):
        if not _competition_is_older_or_same(comp, anchor):
            continue
        if not include_anchor and int(comp.id) == int(anchor.id):
            continue
        cid = int(comp.id)
        if cid in existing:
            continue
        db.session.add(UserRaceRecapDismissal(user_id=int(user_id), competition_id=cid))
        existing.add(cid)
        added += 1
    if added:
        db.session.commit()
    return added


def _competition_race_ranks(competition_id: int) -> dict[int, dict]:
    """user_id -> {rank, points, field_size, avg_points} for one race."""
    rows = (
        CompetitionScore.query.filter_by(competition_id=competition_id)
        .order_by(CompetitionScore.score_id.desc())
        .all()
    )
    best: dict[int, int] = {}
    for sc in rows:
        uid = int(sc.user_id)
        if uid in best or sc.total_points is None:
            continue
        best[uid] = int(sc.total_points)
    if not best:
        return {}
    ranked = sorted(best.items(), key=lambda x: (-x[1], x[0]))
    avg = sum(best.values()) / max(len(best), 1)
    field = len(ranked)
    return {
        uid: {"rank": i, "points": pts, "field_size": field, "avg_points": avg}
        for i, (uid, pts) in enumerate(ranked, start=1)
    }


def _personal_race_recap_highlights(user_id: int, competition_id: int) -> list[dict]:
    highlights: list[dict] = []
    try:
        detail = _build_race_results_detail(user_id, competition_id, dedupe_picks=True)
    except Exception:
        return highlights

    secs = (detail or {}).get("sections") or {}
    summary = (detail or {}).get("summary") or {}

    perfects = [
        r
        for r in (secs.get("picks_450") or []) + (secs.get("picks_250") or [])
        if r.get("status") == "perfect"
    ]
    if perfects:
        first = perfects[0].get("rider_name") or "förare"
        extra = len(perfects) - 1
        text = f"{first} P{perfects[0].get('predicted')} exakt rätt"
        if extra > 0:
            text += f" (+{extra} perfekta till)"
        highlights.append({"tone": "gold", "text": text})

    hs_pts = int(summary.get("holeshot_points") or 0)
    if hs_pts >= 20:
        highlights.append({"tone": "cyan", "text": f"Full holeshot-träff (+{hs_pts}p)"})
    elif hs_pts >= 10:
        highlights.append({"tone": "cyan", "text": f"Holeshot prickad (+{hs_pts}p)"})

    for wc in secs.get("wildcard") or []:
        if wc.get("status") == "correct":
            name = wc.get("rider_name")
            highlights.append({
                "tone": "orange",
                "text": "Wildcard rätt"
                + (f": {name}" if name else "")
                + f" (+{int(wc.get('points') or 0)}p)",
            })
            break

    if not highlights:
        close = [
            r
            for r in (secs.get("picks_450") or []) + (secs.get("picks_250") or [])
            if r.get("status") == "close" and int(r.get("points") or 0) >= 13
        ]
        if close:
            r0 = close[0]
            highlights.append({
                "tone": "cyan",
                "text": f"Nära: {r0.get('rider_name')} ({r0.get('diff')} plats fel, +{r0.get('points')}p)",
            })
    return highlights[:3]


def _build_personal_race_recap(user_id: int, competition_id: int | None = None) -> dict | None:
    """Payload for Din kväll popup. None if nothing eligible."""
    today = get_today()
    # Endast färskt race — äldre ska inte köas upp efter dismiss/reset.
    max_age_days = 12

    if competition_id:
        comp = Competition.query.get(competition_id)
        if not comp:
            return None
        if CompetitionResult.query.filter_by(competition_id=comp.id).first() is None:
            return None
        comps = [comp]
    else:
        comps = _completed_competitions_for_recap(limit=10)

    dismissed_ids = {
        int(r.competition_id)
        for r in UserRaceRecapDismissal.query.filter_by(user_id=user_id).all()
    }

    chosen = None
    my_points = None

    if competition_id is not None:
        # Explicit race (dela-kort / PNG) — tillåt även om redan dismissed.
        for comp in comps:
            pts = _user_competition_points(user_id, int(comp.id))
            if pts is None:
                continue
            chosen = comp
            my_points = pts
            break
    else:
        # Popup: endast det senaste raceet användaren tippat inom fönstret.
        # Om det redan är stängt → visa inget (köa inte Millville→Southwick→…).
        newest = None
        newest_pts = None
        for comp in comps:
            if (
                comp.event_date
                and (today - comp.event_date).days > max_age_days
            ):
                continue
            pts = _user_competition_points(user_id, int(comp.id))
            if pts is None:
                continue
            newest = comp
            newest_pts = pts
            break
        if newest is not None and int(newest.id) not in dismissed_ids:
            chosen = newest
            my_points = newest_pts

    if not chosen or my_points is None:
        return None

    # Auto-path: stäng äldre race tyst så de aldrig poppar efter denna.
    if competition_id is None:
        try:
            _dismiss_din_kvall_for_user(user_id, chosen, include_anchor=False)
        except Exception as e:
            db.session.rollback()
            print(f"din_kvall auto-dismiss older failed: {e}")

    ranks = _competition_race_ranks(int(chosen.id))
    me = ranks.get(int(user_id)) or {}
    race_rank = me.get("rank")
    field_size = me.get("field_size") or len(ranks)
    avg_pts = me.get("avg_points")

    vs_avg_label = None
    if avg_pts is not None:
        vs_avg = int(round(my_points - avg_pts))
        if vs_avg > 0:
            vs_avg_label = f"+{vs_avg} vs snitt"
        elif vs_avg < 0:
            vs_avg_label = f"{vs_avg} vs snitt"
        else:
            vs_avg_label = "På snittet"

    season_rank = None
    season_delta_label = None
    season_board_title = "Säsongstoppen"
    season_top: list[dict] = []
    board: list[dict] = []
    series = (chosen.series or "").upper() or None
    try:
        from social_recap_service import _season_top_snippet, _season_snippet_title

        season_top = _season_top_snippet(5, comp=chosen)
        season_board_title = _season_snippet_title(chosen)
        if series == "WSX":
            from models import Series as SeriesModel

            year = _active_wsx_season_year()
            try:
                if getattr(chosen, "series_id", None):
                    srow = SeriesModel.query.get(int(chosen.series_id))
                    if srow and srow.year:
                        year = int(srow.year)
            except Exception:
                pass
            board = fantasy_wsx_leaderboard_for_year(int(year))
        else:
            board = calculate_leaderboard_deltas()

        for row in board:
            if int(row.get("user_id") or 0) == int(user_id):
                season_rank = row.get("rank")
                try:
                    d = int(row.get("delta") or 0)
                    if d < 0:
                        season_delta_label = f"↑ {abs(d)} platser"
                    elif d > 0:
                        season_delta_label = f"↓ {d} platser"
                    else:
                        season_delta_label = "Oförändrad"
                except Exception:
                    pass
                break
    except Exception:
        board = []
        season_top = []

    highlights = _personal_race_recap_highlights(user_id, int(chosen.id))

    # Weekly badges for THIS user (raket / ankare / kung·queen …)
    weekly_badges: list[dict] = []
    try:
        from social_recap_service import _get_weekly_highlights, _race_leaderboard

        race_lb = _race_leaderboard(int(chosen.id), 5)
        cards = _get_weekly_highlights(int(chosen.id), race_lb)
        for card in cards or []:
            if int(card.get("user_id") or 0) != int(user_id):
                continue
            weekly_badges.append(
                {
                    "kind": card.get("kind") or card.get("icon") or "",
                    "title": card.get("title") or "",
                    "detail": card.get("detail") or "",
                    "is_queen": bool(card.get("is_queen")),
                    "icon": card.get("icon") or card.get("kind") or "",
                }
            )
    except Exception:
        weekly_badges = []

    rival_line = None
    try:
        my_idx = next(
            (i for i, r in enumerate(board) if int(r.get("user_id") or 0) == int(user_id)),
            None,
        )
        if my_idx is not None:
            for j in (my_idx - 1, my_idx + 1):
                if j < 0 or j >= len(board):
                    continue
                other = board[j]
                oid = int(other.get("user_id") or 0)
                if not oid:
                    continue
                opp_pts = _user_competition_points(oid, int(chosen.id))
                if opp_pts is None:
                    continue
                diff = my_points - opp_pts
                oname = (other.get("display_name") or other.get("username") or "rival").strip()
                if diff > 0:
                    rival_line = f"Du slog {oname} med {diff} p den här racehelgen."
                elif diff < 0:
                    rival_line = f"{oname} slog dig med {-diff} p den här racehelgen."
                break
    except Exception:
        rival_line = None

    return {
        "available": True,
        "user_id": int(user_id),
        "competition_id": int(chosen.id),
        "race_name": chosen.name or "Race",
        "series": series,
        "event_date": chosen.event_date.isoformat() if chosen.event_date else None,
        "points": int(my_points),
        "race_rank": race_rank,
        "field_size": field_size,
        "vs_avg_label": vs_avg_label,
        "season_rank": season_rank,
        "season_delta_label": season_delta_label,
        "season_board_title": season_board_title,
        "season_top": season_top,
        "weekly_badges": weekly_badges,
        "highlights": highlights,
        "rival_line": rival_line,
    }


def _ensure_race_recap_table() -> None:
    """Create dismissal table if missing (create_all alone is flaky on some deploys)."""
    try:
        db.create_all()
    except Exception as e:
        print(f"race_recap create_all: {e}")
    try:
        db.session.execute(
            db.text(
                """
                CREATE TABLE IF NOT EXISTS user_race_recap_dismissals (
                    user_id INTEGER NOT NULL,
                    competition_id INTEGER NOT NULL,
                    dismissed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (user_id, competition_id)
                )
                """
            )
        )
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"race_recap ensure table: {e}")
    _ensure_app_runtime_flags_table()
    _maybe_auto_reshow_din_kvall_once()


def _maybe_auto_reshow_din_kvall_once() -> None:
    """One-shot after share/crop fixes: clear dismissals so Din kväll can be re-tested."""
    marker = "din_kvall_auto_reshow_20260809_face_v2"
    try:
        row = db.session.execute(
            db.text("SELECT 1 FROM app_runtime_flags WHERE flag_key = :k LIMIT 1"),
            {"k": marker},
        ).first()
        if row:
            return
        _bump_din_kvall_reshow(clear_all_dismissals=True)
        db.session.execute(
            db.text(
                "INSERT INTO app_runtime_flags (flag_key, flag_value, set_at) "
                "VALUES (:k, '1', CURRENT_TIMESTAMP)"
            ),
            {"k": marker},
        )
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        print(f"auto reshow din kvall skipped: {e}")


def _ensure_app_runtime_flags_table() -> None:
    try:
        db.session.execute(
            db.text(
                """
                CREATE TABLE IF NOT EXISTS app_runtime_flags (
                    flag_key VARCHAR(120) PRIMARY KEY,
                    flag_value TEXT,
                    set_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                )
                """
            )
        )
        db.session.commit()
    except Exception:
        db.session.rollback()
    try:
        # Older installs may lack flag_value
        bind = db.session.get_bind()
        dialect = (bind.dialect.name if bind is not None else "") or ""
        if dialect == "sqlite":
            cols = {
                r[1]
                for r in db.session.execute(db.text("PRAGMA table_info(app_runtime_flags)")).fetchall()
            }
            if "flag_value" not in cols:
                db.session.execute(db.text("ALTER TABLE app_runtime_flags ADD COLUMN flag_value TEXT"))
                db.session.commit()
        else:
            db.session.execute(
                db.text("ALTER TABLE app_runtime_flags ADD COLUMN IF NOT EXISTS flag_value TEXT")
            )
            db.session.commit()
    except Exception:
        db.session.rollback()


def _get_din_kvall_reshow_token() -> str:
    _ensure_app_runtime_flags_table()
    try:
        row = db.session.execute(
            db.text(
                "SELECT flag_value, set_at FROM app_runtime_flags "
                "WHERE flag_key = 'din_kvall_reshow_token' LIMIT 1"
            )
        ).first()
        if not row:
            return "0"
        val = (row[0] or "").strip()
        if val:
            return val
        return str(row[1] or "0")
    except Exception:
        db.session.rollback()
        return "0"


def _bump_din_kvall_reshow(*, clear_all_dismissals: bool = True) -> dict:
    """Admin: force Din kväll popup to show again for everyone."""
    from datetime import datetime as _dt
    import secrets

    _ensure_app_runtime_flags_table()
    token = _dt.utcnow().strftime("%Y%m%d%H%M%S") + "-" + secrets.token_hex(3)
    deleted = 0
    if clear_all_dismissals:
        deleted = UserRaceRecapDismissal.query.delete(synchronize_session=False)
    db.session.execute(
        db.text("DELETE FROM app_runtime_flags WHERE flag_key = 'din_kvall_reshow_token'")
    )
    db.session.execute(
        db.text(
            "INSERT INTO app_runtime_flags (flag_key, flag_value, set_at) "
            "VALUES ('din_kvall_reshow_token', :v, CURRENT_TIMESTAMP)"
        ),
        {"v": token},
    )
    db.session.commit()
    return {"token": token, "cleared_dismissals": int(deleted or 0)}


