@app.post("/admin/restore_picks")
def admin_restore_picks():
    """Admin route to manually restore race picks for a user"""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    
    try:
        data = request.get_json(force=True)
        username = data.get("username")
        competition_id = int(data.get("competition_id"))
        picks_data = data.get("picks", [])  # List of {rider_id, predicted_position}
        
        if not username or not competition_id:
            return jsonify({"error": "username and competition_id are required"}), 400
        
        user = User.query.filter_by(username=username).first()
        if not user:
            return jsonify({"error": f"User '{username}' not found"}), 404
        
        comp = Competition.query.get(competition_id)
        if not comp:
            return jsonify({"error": f"Competition {competition_id} not found"}), 404
        
        # Säkerställ att vi inte bara raderar race-picks utan att lägga till några (lämnar holeshot+wildcard kvar, tokigt tillstånd)
        if not picks_data or len(picks_data) == 0:
            return jsonify({
                "error": "Kan inte återställa med tom lista – det skulle ta bort bara race-picks. Använd 'Lägg in picks (positioner)' om du vill sätta alla picks."
            }), 400
        
        # Delete existing RACE picks only (holeshot/wildcard lämnas oförändrade)
        RacePick.query.filter_by(user_id=user.id, competition_id=competition_id).delete()
        db.session.commit()
        
        # Add new picks
        restored_count = 0
        for pick_data in picks_data:
            rider_id = int(pick_data.get("rider_id"))
            predicted_position = int(pick_data.get("predicted_position"))
            
            rider = Rider.query.get(rider_id)
            if not rider:
                print(f"WARNING: Rider {rider_id} not found, skipping")
                continue
            
            db.session.add(RacePick(
                user_id=user.id,
                competition_id=competition_id,
                rider_id=rider_id,
                predicted_position=predicted_position
            ))
            restored_count += 1
            print(f"Restored pick: {rider.name} at position {predicted_position} for {username}")
        
        db.session.commit()
        
        # Recalculate scores
        calculate_scores(competition_id)
        
        return jsonify({
            "success": True,
            "message": f"Restored {restored_count} picks for {username} in {comp.name}",
            "restored_count": restored_count
        })
        
    except Exception as e:
        db.session.rollback()
        import traceback
        print(f"ERROR in admin_restore_picks: {e}")
        print(traceback.format_exc())
        return jsonify({"error": str(e), "traceback": traceback.format_exc()}), 500


@app.post("/admin/set_user_picks_full")
def admin_set_user_picks_full():
    """Admin: lägg in alla picks manuellt (race, holeshot, wildcard) och räkna poängen."""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    try:
        data = request.get_json(force=True)
        username = data.get("username")
        competition_id = int(data.get("competition_id"))
        race_picks = data.get("race_picks", [])  # [{"rider_id": int, "predicted_position": int}, ...]
        holeshot_450_rider_id = data.get("holeshot_450_rider_id")
        holeshot_250_rider_id = data.get("holeshot_250_rider_id")
        wildcard_rider_id = data.get("wildcard_rider_id")
        wildcard_position = data.get("wildcard_position")

        if not username or not competition_id:
            return jsonify({"error": "username och competition_id krävs"}), 400
        user = User.query.filter_by(username=username).first()
        if not user:
            return jsonify({"error": f"Användare '{username}' hittades inte"}), 404
        comp = Competition.query.get(competition_id)
        if not comp:
            return jsonify({"error": f"Tävling {competition_id} hittades inte"}), 404
        is_wsx = getattr(comp, "series", None) == "WSX"

        RacePick.query.filter_by(user_id=user.id, competition_id=competition_id).delete()
        HoleshotPick.query.filter_by(user_id=user.id, competition_id=competition_id).delete()
        WildcardPick.query.filter_by(user_id=user.id, competition_id=competition_id).delete()
        db.session.commit()

        for p in race_picks:
            rider_id = int(p.get("rider_id"))
            pred = int(p.get("predicted_position"))
            if Rider.query.get(rider_id):
                db.session.add(RacePick(
                    user_id=user.id,
                    competition_id=competition_id,
                    rider_id=rider_id,
                    predicted_position=pred,
                ))

        if holeshot_450_rider_id:
            r = Rider.query.get(int(holeshot_450_rider_id))
            if r:
                db.session.add(HoleshotPick(
                    user_id=user.id,
                    competition_id=competition_id,
                    rider_id=r.id,
                    class_name="450cc",
                ))
        if holeshot_250_rider_id:
            r = Rider.query.get(int(holeshot_250_rider_id))
            if r:
                db.session.add(HoleshotPick(
                    user_id=user.id,
                    competition_id=competition_id,
                    rider_id=r.id,
                    class_name="250cc",
                ))

        if not is_wsx and wildcard_rider_id and wildcard_position is not None:
            r = Rider.query.get(int(wildcard_rider_id))
            if r:
                db.session.add(WildcardPick(
                    user_id=user.id,
                    competition_id=competition_id,
                    rider_id=r.id,
                    position=int(wildcard_position),
                ))

        db.session.commit()
        calculate_scores(competition_id)

        return jsonify({
            "success": True,
            "message": f"Picks och poäng sparade för {username} i {comp.name}.",
        })
    except Exception as e:
        db.session.rollback()
        import traceback
        print(f"ERROR in admin_set_user_picks_full: {e}\n{traceback.format_exc()}")
        return jsonify({"error": str(e)}), 500


@app.get("/admin/user_picks/<string:username>/<int:competition_id>")
def admin_get_user_picks(username: str, competition_id: int):
    """Admin: visa exakt vilka picks en användare har för en tävling (för felsökning)."""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    user = User.query.filter_by(username=username).first()
    if not user:
        return jsonify({"error": "Användare hittades inte"}), 404
    comp = Competition.query.get(competition_id)
    if not comp:
        return jsonify({"error": "Tävling hittades inte"}), 404
    race = RacePick.query.filter_by(user_id=user.id, competition_id=competition_id).order_by(RacePick.predicted_position).all()
    holes = HoleshotPick.query.filter_by(user_id=user.id, competition_id=competition_id).all()
    wc = WildcardPick.query.filter_by(user_id=user.id, competition_id=competition_id).first()
    def rider_name(rid):
        r = Rider.query.get(rid)
        return r.name if r else f"rider_id={rid}"
    return jsonify({
        "username": username,
        "competition_id": competition_id,
        "competition_name": comp.name,
        "race_picks": [{"rider_id": p.rider_id, "rider_name": rider_name(p.rider_id), "predicted_position": p.predicted_position} for p in race],
        "race_picks_count": len(race),
        "holeshot_picks": [{"class_name": h.class_name, "rider_id": h.rider_id, "rider_name": rider_name(h.rider_id)} for h in holes],
        "wildcard": {"rider_id": wc.rider_id, "rider_name": rider_name(wc.rider_id), "position": wc.position} if wc else None,
    })


@app.get("/reset_season_team_points")
def reset_season_team_points():
    """Reset all season team points to 0 (admin only) - keeps teams and riders"""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    
    try:
        print("🔄 Resetting all season team points to 0...")
        
        # Get all season teams
        all_season_teams = SeasonTeam.query.all()
        reset_count = 0
        teams_reset = []
        
        for team in all_season_teams:
            old_points = team.total_points
            team.total_points = 0
            reset_count += 1
            teams_reset.append({
                "team_name": team.team_name,
                "user_id": team.user_id,
                "old_points": old_points
            })
            print(f"  Reset {team.team_name} (user {team.user_id}): {old_points} → 0 poäng")
        
        db.session.commit()
        
        print(f"✅ Reset season team points for {reset_count} teams")
        
        return jsonify({
            "message": f"Nollställde poäng för {reset_count} säsongsteam. Teamen och förarna behålls.",
            "reset_count": reset_count,
            "teams_reset": teams_reset
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"❌ Error resetting season team points: {e}")
        import traceback
        traceback.print_exc()
        return jsonify({"error": str(e)}), 500

