@app.get("/update_rider_prices")
def update_rider_prices():
    """Update rider prices based on 2025 point standings"""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    
    try:
        # Read point standings file
        with open('point standings 2025.txt', 'r', encoding='utf-8') as f:
            content = f.read()
        
        # Parse the data
        riders_data = {
            '450cc': {},
            '250cc': {}
        }
        
        sections = content.split('\n\n')
        current_class = None
        
        for section in sections:
            lines = section.strip().split('\n')
            if not lines:
                continue
                
            # Check if this is a class header (case-insensitive, flexible matching)
            header_lower = lines[0].lower()
            if '250' in header_lower and ('west' in header_lower or 'east' in header_lower):
                current_class = '250cc'
                continue
            elif '450' in header_lower and ('point' in header_lower or 'standings' in header_lower):
                current_class = '450cc'
                continue
            
            # Parse rider data
            if current_class and len(lines) > 1:
                for line in lines[1:]:  # Skip header line
                    if not line.strip():
                        continue
                        
                    # Parse format: "1	Haiden DeeganHaiden Deegan	Temecula, CAUnited States	221"
                    parts = line.split('\t')
                    if len(parts) >= 4:
                        try:
                            position = int(parts[0])
                            name_part = parts[1]
                            points = int(parts[-1]) if parts[-1].isdigit() else 0
                            
                            # Clean up name (remove duplicates like "Haiden DeeganHaiden Deegan" or "Cooper WebbCooper Webb")
                            name = name_part.strip()
                            
                            # Check if name is duplicated (exact duplicate without space)
                            name_len = len(name)
                            if name_len > 15 and name_len % 2 == 0:
                                # Try splitting in half
                                mid = name_len // 2
                                first_half = name[:mid]
                                second_half = name[mid:]
                                # Check if they're the same (handles "Haiden DeeganHaiden Deegan")
                                if first_half == second_half:
                                    name = first_half
                            
                            # Word-based approach for cases with spaces
                            if len(name) > 15:
                                words = name.split()
                                if len(words) >= 4:
                                    # Check if first half equals second half
                                    mid = len(words) // 2
                                    first_half = words[:mid]
                                    second_half = words[mid:]
                                    if first_half == second_half:
                                        name = ' '.join(first_half)
                                else:
                                    # Try character-based approach
                                    mid = len(name) // 2
                                    for i in range(max(5, mid-10), min(len(name)-5, mid+10)):
                                        if i < len(name) and i > 0:
                                            if name[i-1] == ' ' and name[i].isupper():
                                                if i > 5 and name[:i].strip() == name[i:].strip():
                                                    name = name[:i].strip()
                                                    break
                            
                            name = name.strip()
                            
                            riders_data[current_class][name] = {
                                'position': position,
                                'points': points
                            }
                        except (ValueError, IndexError):
                            continue
        
        # Calculate prices and update database using new budget-optimized pricing
        updated_riders = []
        
        def calculate_price_for_budget(position: int, points: int, class_name: str):
            """Calculate price optimized for 2M budget (4 riders: 2x450cc + 2x250cc)"""
            if class_name == '450cc':
                if position == 1:
                    return 450000
                elif position == 2:
                    return 420000
                elif position == 3:
                    return 400000
                elif position <= 5:
                    return 380000 - (position - 4) * 10000
                elif position <= 10:
                    return 350000 - (position - 6) * 14000
                elif position <= 15:
                    return 280000 - (position - 11) * 16000
                elif position <= 20:
                    return 200000 - (position - 16) * 10000
                elif points > 50:
                    return 150000
                elif points > 0:
                    return 100000
                else:
                    return 100000  # Default
            else:  # 250cc
                if position == 1:
                    return 400000
                elif position == 2:
                    return 380000
                elif position == 3:
                    return 360000
                elif position <= 5:
                    return 340000 - (position - 4) * 10000
                elif position <= 10:
                    return 300000 - (position - 6) * 16000
                elif position <= 15:
                    return 220000 - (position - 11) * 14000
                elif position <= 20:
                    return 150000 - (position - 16) * 6000
                elif points > 30:
                    return 100000
                elif points > 0:
                    return 100000
                else:
                    return 100000  # Default
        
        for class_name, riders in riders_data.items():
            for name, data in riders.items():
                position = data['position']
                points = data['points']
                
                # Calculate price using new budget-optimized function
                price = calculate_price_for_budget(position, points, class_name)
                
                # Update ALL riders with this name and class (in case of duplicates)
                riders = Rider.query.filter_by(name=name, class_name=class_name).all()
                if riders:
                    for rider in riders:
                        old_price = rider.price
                        rider.price = price
                        updated_riders.append({
                            'name': name,
                            'class': class_name,
                            'position': position,
                            'points': points,
                            'old_price': old_price,
                            'new_price': price,
                            'rider_id': rider.id
                        })
        
        db.session.commit()
        
        return jsonify({
            "message": f"Updated prices for {len(updated_riders)} riders based on 2025 standings",
            "updated_riders": updated_riders
        })
        
    except Exception as e:
        print(f"Error updating rider prices: {e}")
        return jsonify({"error": str(e)}), 500

