def repair_known_result_anomalies() -> int:
    """Repair known imported result misses that affected live standings."""
    repaired = 0

    def norm(value: str | None) -> str:
        return (value or "").replace(".", "").strip().lower()

    haiden_riders = Rider.query.filter(Rider.name.ilike("haiden deegan")).all()
    if not haiden_riders:
        return repaired

    haiden_riders.sort(key=lambda rider: 0 if rider.class_name == "250cc" else 1)
    haiden_ids = [rider.id for rider in haiden_riders]
    haiden_rider = haiden_riders[0]

    # 2026 250SX West/Showdown results for Haiden Deegan.
    # These rows were lost when his rider profile was moved forward to 450cc/WSX.
    deegan_sx_2026_positions = {
        "anaheim 1": 4,
        "san diego": 1,
        "anaheim 2": 1,
        "houston": 1,
        "glendale": 1,
        "seattle": 1,
        "birmingham": 2,
        "st louis": 1,
        "denver": 1,
        "salt lake city": 4,
    }

    competitions_by_name = {
        norm(comp.name): comp
        for comp in Competition.query.filter_by(series="SX").all()
        if comp.event_date and comp.event_date.year == 2026
    }

    for comp_name, position in deegan_sx_2026_positions.items():
        comp = competitions_by_name.get(comp_name)
        if not comp:
            continue

        existing = (
            CompetitionResult.query
            .filter(
                CompetitionResult.competition_id == comp.id,
                CompetitionResult.rider_id.in_(haiden_ids),
            )
            .first()
        )
        if existing:
            if existing.position != position or existing.class_name != "250cc":
                existing.position = position
                existing.class_name = "250cc"
                existing.rider_points = None
                repaired += 1
        else:
            occupied_at_target = (
                db.session.query(CompetitionResult)
                .join(Rider, Rider.id == CompetitionResult.rider_id)
                .filter(
                    CompetitionResult.competition_id == comp.id,
                    CompetitionResult.position == position,
                    ~CompetitionResult.rider_id.in_(haiden_ids),
                    db.func.coalesce(CompetitionResult.class_name, Rider.class_name) == "250cc",
                )
                .all()
            )
            occupied_at_next = (
                db.session.query(CompetitionResult.result_id)
                .join(Rider, Rider.id == CompetitionResult.rider_id)
                .filter(
                    CompetitionResult.competition_id == comp.id,
                    CompetitionResult.position == position + 1,
                    ~CompetitionResult.rider_id.in_(haiden_ids),
                    db.func.coalesce(CompetitionResult.class_name, Rider.class_name) == "250cc",
                )
                .first()
            )
            if occupied_at_target:
                if occupied_at_next:
                    compacted_rows = (
                        db.session.query(CompetitionResult)
                        .join(Rider, Rider.id == CompetitionResult.rider_id)
                        .filter(
                            CompetitionResult.competition_id == comp.id,
                            CompetitionResult.position >= position,
                            ~CompetitionResult.rider_id.in_(haiden_ids),
                            db.func.coalesce(CompetitionResult.class_name, Rider.class_name) == "250cc",
                        )
                        .order_by(CompetitionResult.position.desc())
                        .all()
                    )
                    for row in compacted_rows:
                        row.position += 1
                        row.class_name = "250cc"
                        repaired += 1
                else:
                    for row in occupied_at_target:
                        row.position = position + 1
                        row.class_name = "250cc"
                        repaired += 1

            db.session.add(
                CompetitionResult(
                    competition_id=comp.id,
                    rider_id=haiden_rider.id,
                    position=position,
                    class_name="250cc",
                )
            )
            repaired += 1

    if repaired:
        db.session.commit()

    return repaired


def _ensure_email_opt_out_column() -> None:
    """users.email_opt_out — avregistrering från picks/nyhetsmail."""
    try:
        if "postgresql" in str(db.engine.url):
            result = db.session.execute(
                db.text(
                    "SELECT column_name FROM information_schema.columns "
                    "WHERE table_name = 'users' AND column_name = 'email_opt_out'"
                )
            )
            if not result.fetchone():
                db.session.execute(
                    db.text(
                        "ALTER TABLE users ADD COLUMN email_opt_out BOOLEAN "
                        "NOT NULL DEFAULT FALSE"
                    )
                )
                print("Added missing column users.email_opt_out")
            db.session.commit()
        else:
            _sqlite_add_column_if_missing(
                "users", "email_opt_out", "email_opt_out BOOLEAN DEFAULT 0 NOT NULL"
            )
    except Exception as col_err:
        print(f"Warning: email_opt_out migration skipped: {col_err}")
        db.session.rollback()


# Initialize database function
def _sqlite_add_column_if_missing(table: str, column: str, ddl: str) -> None:
    """Lightweight schema patch for older local SQLite files."""
    if "sqlite" not in str(db.engine.url):
        return
    rows = db.session.execute(db.text(f"PRAGMA table_info({table})")).fetchall()
    if column in {row[1] for row in rows}:
        return
    db.session.execute(db.text(f"ALTER TABLE {table} ADD COLUMN {ddl}"))
    db.session.commit()
    print(f'Added missing column {table}.{column}')


def _ensure_racerx_bio_skip_column() -> None:
    """racerx_bio_skip — batch hoppar över namn som saknas på RacerX."""
    try:
        if "postgresql" in str(db.engine.url):
            result = db.session.execute(
                db.text(
                    "SELECT column_name FROM information_schema.columns "
                    "WHERE table_name = 'riders' AND column_name = 'racerx_bio_skip'"
                )
            )
            if not result.fetchone():
                db.session.execute(
                    db.text("ALTER TABLE riders ADD COLUMN racerx_bio_skip VARCHAR(200)")
                )
                print("Added missing column riders.racerx_bio_skip")
            db.session.commit()
        else:
            _sqlite_add_column_if_missing(
                "riders", "racerx_bio_skip", "racerx_bio_skip VARCHAR(200)"
            )
    except Exception as col_err:
        db.session.rollback()
        print(f"Warning: racerx_bio_skip column patch skipped: {col_err}")


def _ensure_rider_bio_sv_columns() -> None:
    """bio_sv / achievements_sv — svensk översättningscache på riders."""
    try:
        if "postgresql" in str(db.engine.url):
            for col in ("bio_sv", "achievements_sv"):
                result = db.session.execute(
                    db.text(
                        "SELECT column_name FROM information_schema.columns "
                        "WHERE table_name = 'riders' AND column_name = :col"
                    ),
                    {"col": col},
                )
                if not result.fetchone():
                    db.session.execute(db.text(f"ALTER TABLE riders ADD COLUMN {col} TEXT"))
                    print(f"Added missing column riders.{col}")
            db.session.commit()
        else:
            _sqlite_add_column_if_missing("riders", "bio_sv", "bio_sv TEXT")
            _sqlite_add_column_if_missing("riders", "achievements_sv", "achievements_sv TEXT")
    except Exception as col_err:
        db.session.rollback()
        print(f"Warning: riders bio_sv column patch skipped: {col_err}")


def init_database():
    """Initialize database with tables and test data"""
    try:
        with app.app_context():
            print("Starting database initialization...")
            
            # Create tables only if they don't exist
            try:
                db.create_all()
                print("Database tables created successfully")
                try:
                    _sqlite_add_column_if_missing("riders", "rider_image_data", "rider_image_data TEXT")
                    _sqlite_add_column_if_missing(
                        "users", "password_reset_token", "password_reset_token VARCHAR(64)"
                    )
                    _sqlite_add_column_if_missing(
                        "users", "password_reset_expires", "password_reset_expires TIMESTAMP"
                    )
                except Exception as col_err:
                    print(f"Warning: SQLite column patch skipped: {col_err}")
                    db.session.rollback()
                try:
                    _ensure_rider_bio_sv_columns()
                except Exception as bio_col_err:
                    print(f"Warning: bio_sv migration skipped: {bio_col_err}")
                try:
                    _ensure_racerx_bio_skip_column()
                except Exception as skip_col_err:
                    print(f"Warning: racerx_bio_skip migration skipped: {skip_col_err}")
                try:
                    _ensure_email_opt_out_column()
                except Exception as opt_col_err:
                    print(f"Warning: email_opt_out migration skipped: {opt_col_err}")
                try:
                    _ensure_google_oauth_columns()
                except Exception as g_col_err:
                    print(f"Warning: google_sub migration skipped: {g_col_err}")
                try:
                    _ensure_league_membership_unique()
                except Exception as league_mem_err:
                    print(f"Warning: league_membership unique fix skipped: {league_mem_err}")
                try:
                    _ensure_season_team_archives_table()
                except Exception as st_arch_err:
                    print(f"Warning: season_team_archives ensure skipped: {st_arch_err}")
                # Auto-seed WSX so calendar exists for the UI (2025 history + 2026 season)
                try:
                    ensure_wsx_series_and_competitions()
                except Exception as seed_err:
                    print(f"Warning: WSX 2025 seed failed: {seed_err}")
                try:
                    run_ama_smx_boot_seeds(get_timezone_for_track=get_track_timezone)
                except Exception as seed_err:
                    print(f"Warning: AMA/SMX boot seed chain failed: {seed_err}")
                try:
                    ensure_wsx_2026(deactivate_2025=True)
                except Exception as seed_err:
                    print(f"Warning: WSX 2026 series seed failed: {seed_err}")
                try:
                    ensure_wsx_2026_roster()
                except Exception as seed_err:
                    print(f"Warning: WSX 2026 roster seed failed: {seed_err}")
                try:
                    sync_wsx_canadian_gp_entry_list()
                except Exception as seed_err:
                    print(f"Warning: WSX Canadian GP entry sync failed: {seed_err}")
                try:
                    sync_wsx_round_only_wildcards()
                except Exception as seed_err:
                    print(f"Warning: WSX round-only wildcard sync failed: {seed_err}")
                try:
                    from mxon_fantasy import ensure_mxon_2026

                    ensure_mxon_2026(attach_track_image=True)
                    global _SERIES_STATUS_CACHE
                    _SERIES_STATUS_CACHE = None
                except Exception as seed_err:
                    print(f"Warning: MXON 2026 seed failed: {seed_err}")
                try:
                    from mxgp_fantasy import ensure_mxgp_scaffold

                    ensure_mxgp_scaffold()
                    _SERIES_STATUS_CACHE = None
                except Exception as seed_err:
                    print(f"Warning: MXGP scaffold seed failed: {seed_err}")
            except Exception as e:
                print(f"Warning: Could not create tables (they may already exist): {e}")
            
            # Handle timezone column migration for existing competitions
            try:
                # Check if timezone column exists, if not add it (PostgreSQL compatible)
                if 'postgresql' in str(db.engine.url):
                    # PostgreSQL syntax
                    result = db.session.execute(db.text("""
                        SELECT column_name 
                        FROM information_schema.columns 
                        WHERE table_name = 'competitions' AND column_name = 'timezone'
                    """))
                    columns = [row[0] for row in result.fetchall()]
                    
                    if not columns:  # timezone column doesn't exist
                        print("Adding timezone column to competitions table...")
                        db.session.execute(db.text("ALTER TABLE competitions ADD COLUMN timezone VARCHAR(50)"))
                        db.session.commit()
                        print("Timezone column added successfully")
                else:
                    # SQLite syntax (fallback)
                    result = db.session.execute(db.text("PRAGMA table_info(competitions)"))
                    columns = [row[1] for row in result.fetchall()]
                    
                    if 'timezone' not in columns:
                        print("Adding timezone column to competitions table...")
                        db.session.execute(db.text("ALTER TABLE competitions ADD COLUMN timezone VARCHAR(50)"))
                        db.session.commit()
                        print("Timezone column added successfully")
                    
                    # Keep mapped venues in sync; only default when timezone is blank
                    competitions = Competition.query.all()
                    touched = 0
                    explicit_names = {
                        'Anaheim 1', 'Anaheim 2', 'San Diego', 'San Francisco', 'Seattle',
                        'Denver', 'Salt Lake City', 'Glendale', 'Houston', 'Arlington',
                        'St. Louis', 'Nashville', 'Birmingham', 'Daytona', 'Tampa',
                        'Indianapolis', 'Detroit', 'Cleveland', 'Philadelphia',
                        'East Rutherford', 'Foxborough', 'Minneapolis', 'Atlanta', 'Las Vegas',
                        # Pro Motocross
                        'Fox Raceway National', 'Hangtown Classic', 'Thunder Valley National',
                        'High Point National', 'RedBud National', 'Southwick National',
                        'Spring Creek National', 'Washougal National', 'Unadilla National',
                        'Budds Creek National', 'Ironman National',
                        # WSX
                        'Canadian GP', 'British GP', 'Buenos Aires City GP', 'Australian GP',
                        'South African GP', 'New Zealand GP', 'Swedish GP',
                    }
                    for comp in competitions:
                        if comp.name in explicit_names:
                            mapped = get_track_timezone(comp.name)
                            if comp.timezone != mapped:
                                comp.timezone = mapped
                                touched += 1
                        elif not (comp.timezone or "").strip():
                            comp.timezone = get_track_timezone(comp.name)
                            touched += 1
                    db.session.commit()
                    print(f"Updated timezone on {touched}/{len(competitions)} competitions")
            except Exception as e:
                print(f"Warning: Could not migrate timezone column: {e}")
                # Continue anyway, the column will be added when creating new competitions

            # Soft-cancel flag for competitions (e.g. cancelled WSX British GP)
            try:
                db.session.execute(db.text("SELECT is_cancelled FROM competitions LIMIT 1"))
            except Exception:
                db.session.rollback()
                try:
                    print("Adding is_cancelled column to competitions table...")
                    db.session.execute(
                        db.text(
                            "ALTER TABLE competitions ADD COLUMN is_cancelled BOOLEAN DEFAULT FALSE NOT NULL"
                        )
                    )
                    db.session.commit()
                    print("is_cancelled column added successfully")
                except Exception as cancel_err:
                    db.session.rollback()
                    print(f"Warning: Could not migrate is_cancelled column: {cancel_err}")

            # Snapshot rider class on CompetitionResult rows so class switches don't rewrite history
            try:
                if 'postgresql' in str(db.engine.url):
                    # Ensure column exists
                    result = db.session.execute(db.text("""
                        SELECT column_name
                        FROM information_schema.columns
                        WHERE table_name = 'competition_results' AND column_name = 'class'
                    """))
                    has_col = bool(result.fetchall())
                    if not has_col:
                        print('Adding "class" column to competition_results table...')
                        db.session.execute(db.text('ALTER TABLE competition_results ADD COLUMN IF NOT EXISTS "class" VARCHAR(10)'))
                        db.session.commit()
                    # Backfill: riders.class is the real column name (not class_name).
                    db.session.execute(db.text("""
                        UPDATE competition_results cr
                        SET "class" = r."class"
                        FROM riders r
                        WHERE cr.rider_id = r.id
                          AND cr."class" IS NULL
                    """))
                    db.session.commit()
                else:
                    # SQLite fallback
                    result = db.session.execute(db.text("PRAGMA table_info(competition_results)"))
                    columns = [row[1] for row in result.fetchall()]
                    if "class" not in columns:
                        print('Adding "class" column to competition_results table...')
                        db.session.execute(db.text('ALTER TABLE competition_results ADD COLUMN "class" VARCHAR(10)'))
                        db.session.commit()
                    db.session.execute(db.text("""
                        UPDATE competition_results
                        SET "class" = (SELECT "class" FROM riders WHERE riders.id = competition_results.rider_id)
                        WHERE "class" IS NULL
                    """))
                    db.session.commit()
            except Exception as e:
                print(f'Warning: Could not migrate competition_results."class": {e}')
                db.session.rollback()

            # MX moto splits (RacerX import: 1-1 → 25+25 seriepoäng)
            try:
                if "sqlite" in str(db.engine.url):
                    _sqlite_add_column_if_missing(
                        "competition_results", "moto_1_position", "moto_1_position INTEGER"
                    )
                    _sqlite_add_column_if_missing(
                        "competition_results", "moto_2_position", "moto_2_position INTEGER"
                    )
                else:
                    db.session.execute(
                        db.text("ALTER TABLE competition_results ADD COLUMN IF NOT EXISTS moto_1_position INTEGER")
                    )
                    db.session.execute(
                        db.text("ALTER TABLE competition_results ADD COLUMN IF NOT EXISTS moto_2_position INTEGER")
                    )
                    db.session.commit()
                print("Ensured moto_1_position / moto_2_position on competition_results")
            except Exception as e:
                print(f"Warning: Could not add MX moto columns: {e}")
                db.session.rollback()

            try:
                repaired = repair_known_result_anomalies()
                if repaired:
                    print(f"Repaired {repaired} known race-result anomaly rows")
            except Exception as e:
                print(f"Warning: Could not repair known race-result anomalies: {e}")
                db.session.rollback()

            try:
                _ensure_race_recap_table()
            except Exception as e:
                print(f"Warning: race_recap ensure/reset failed: {e}")
                db.session.rollback()
            
            # Only create test data if database is completely empty AND we're in development
            try:
                user_count = User.query.count()
                competition_count = Competition.query.count()
                
                # Only create test data if both users and competitions are empty
                if user_count == 0 and competition_count == 0:
                    print("Database is empty, creating test data...")
                    create_test_data()
                    print("Test data created successfully")
                else:
                    print(f"Database has {user_count} users and {competition_count} competitions, skipping test data creation")
            except Exception as e:
                print(f"Warning: Could not create test data: {e}")
                # Don't try to create test data if there's an error
                pass
            
            print("Database initialized successfully")
            return True
    except Exception as e:
        print(f"Database initialization error: {e}")
        import traceback
        traceback.print_exc()
        return False

