@app.route("/admin/delete_user/<int:user_id>", methods=['DELETE'])
def delete_user(user_id):
    """Delete a user and all related data - admin only"""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403
    
    try:
        user = User.query.get_or_404(user_id)
        
        # Don't allow deleting admin users
        if user.is_admin:
            return jsonify({"error": "Cannot delete admin users"}), 400
        
        username = user.username
        
        # Delete all related data first to avoid foreign key constraint violations
        # This needs to be done in the correct order
        
        # 1. Delete leaderboard history
        LeaderboardHistory.query.filter_by(user_id=user_id).delete()
        
        # 2. Delete competition scores
        CompetitionScore.query.filter_by(user_id=user_id).delete()
        
        # 3. Delete race picks
        RacePick.query.filter_by(user_id=user_id).delete()
        
        # 4. Delete holeshot picks
        HoleshotPick.query.filter_by(user_id=user_id).delete()
        
        # 5. Delete wildcard picks
        WildcardPick.query.filter_by(user_id=user_id).delete()
        
        # 6. Delete bulletin reactions (must be before bulletin posts if they have foreign keys)
        BulletinReaction.query.filter_by(user_id=user_id).delete()
        
        # 7. Delete bulletin posts (user's own posts)
        BulletinPost.query.filter_by(user_id=user_id).delete()
        
        # 8. Delete league requests
        LeagueRequest.query.filter_by(user_id=user_id).delete()
        
        # 9. Delete league memberships
        LeagueMembership.query.filter_by(user_id=user_id).delete()
        
        # 10. Delete leagues where user is creator (handle carefully - might want to transfer ownership)
        # For now, we'll delete them but you might want to handle this differently
        League.query.filter_by(creator_id=user_id).delete()
        
        # 11. Delete season team (cascade should handle riders, but let's be explicit)
        SeasonTeam.query.filter_by(user_id=user_id).delete()
        
        # 12. Delete high scores - CrossDinoHighScore uses player_name, not user_id
        # Match by username since player_name is used instead of user_id
        CrossDinoHighScore.query.filter_by(player_name=username).delete()
        
        # 13. Finally, delete the user
        db.session.delete(user)
        db.session.commit()
        
        return jsonify({
            "message": f"User '{username}' and all related data deleted successfully"
        })
        
    except Exception as e:
        db.session.rollback()
        print(f"Error deleting user: {e}")
        return jsonify({"error": str(e)}), 500


@app.post("/admin/reset_season_team/<int:user_id>")
def admin_reset_season_team(user_id: int):
    """Delete one user's season team + transfer penalties so they can rebuild from scratch."""
    if not is_admin_user():
        return jsonify({"error": "admin_only"}), 403

    try:
        user = User.query.get(user_id)
        if not user:
            return jsonify({"error": "user_not_found"}), 404

        team = SeasonTeam.query.filter_by(user_id=user_id).first()
        deleted_riders = 0
        deleted_team = 0
        if team:
            deleted_riders = SeasonTeamRider.query.filter_by(season_team_id=team.id).delete(
                synchronize_session=False
            )
            db.session.delete(team)
            deleted_team = 1

        deleted_penalties = CompetitionScore.query.filter(
            CompetitionScore.user_id == user_id,
            CompetitionScore.competition_id.is_(None),
        ).delete(synchronize_session=False)

        db.session.commit()
        return jsonify({
            "success": True,
            "message": (
                f"Återställde säsongsteam för '{user.username}': "
                f"tog bort lag={deleted_team}, förare={deleted_riders}, "
                f"transfer-straff={deleted_penalties}. Racepoäng orörda."
            ),
            "deleted_team": deleted_team,
            "deleted_riders": deleted_riders,
            "deleted_penalties": deleted_penalties,
        })
    except Exception as e:
        db.session.rollback()
        print(f"Error resetting season team for user {user_id}: {e}")
        return jsonify({"error": str(e)}), 500

@app.route("/cleanup_duplicate_users")
def cleanup_duplicate_users():
    """Remove duplicate test users - keep only the first one"""
    if session.get('username') != 'test':
        return jsonify({"error": "admin_only"}), 403
    
    try:
        # Find all test users
        test_users = User.query.filter_by(username='test').all()
        
        if len(test_users) <= 1:
            return jsonify({
                "message": "No duplicate test users found",
                "count": len(test_users)
            })
        
        # Keep the first one (oldest), delete the rest
        first_user = test_users[0]
        duplicates = test_users[1:]
        
        deleted_count = 0
        for user in duplicates:
            db.session.delete(user)
            deleted_count += 1
        
        db.session.commit()
        
        return jsonify({
            "message": f"Cleaned up {deleted_count} duplicate test users",
            "kept_user_id": first_user.id,
            "deleted_count": deleted_count
        })
        
    except Exception as e:
        print(f"Error cleaning up duplicate users: {e}")
        return jsonify({"error": str(e)}), 500

