def _race_hero_meta(comp, schedule: dict) -> dict:
    """Structured labels for homepage race hero (date, time, location, flag)."""
    import re

    try:
        from track_weather import resolve_track_geo

        geo = resolve_track_geo(getattr(comp, "name", "") or "") or {}
    except Exception:
        geo = {}

    event_date = getattr(comp, "event_date", None)
    date_label = ""
    if event_date:
        m = _SV_MONTHS[event_date.month]
        date_label = f"{event_date.day} {m.upper()} {event_date.year}"

    time_label = ""
    rsd = schedule.get("race_start_display") or ""
    m_time = re.search(r"kl (\d{1,2}:\d{2}) \(([^)]+)\)", rsd)
    if m_time:
        time_label = f"{m_time.group(1)} ({m_time.group(2)})"

    tz = schedule.get("timezone") or ""
    flag = "🇺🇸"
    if "Argentina" in tz:
        flag = "🇦🇷"
    elif "Australia" in tz or "Brisbane" in tz:
        flag = "🇦🇺"
    elif "Stockholm" in tz:
        flag = "🇸🇪"
    elif "Africa" in tz:
        flag = "🇿🇦"
    elif "Toronto" in tz or "Canada" in tz or "Vancouver" in (geo.get("city") or ""):
        flag = "🇨🇦"

    return {
        "date_label": date_label,
        "time_label": time_label,
        "location": geo.get("city") or "",
        "flag": flag,
    }


@app.route("/race_countdown")
def race_countdown():
    """Countdown for main page - supports both real and test modes"""
    try:
        mode = request.args.get('mode', 'real')
        # Guard: this endpoint can be hit frequently; avoid DB writes in hot path.
        global _RACE_COUNTDOWN_SELF_HEAL_DONE  # type: ignore
        if "_RACE_COUNTDOWN_SELF_HEAL_DONE" not in globals():
            _RACE_COUNTDOWN_SELF_HEAL_DONE = False  # type: ignore
        
        if mode == 'test':
            # Test mode - use simulated time from GlobalSimulation
            simulation = GlobalSimulation.query.filter_by(active=True).first()
            if simulation and simulation.scenario:
                # Use simulated time for test mode - calculate fresh each time
                current_simulated_time = get_current_time()
                
                # Calculate race time based on scenario - use initial simulated time for fixed race times
                # Get the initial simulated time when simulation started
                initial_simulated_time = datetime.fromisoformat(simulation.simulated_time)
                
                if simulation.scenario == 'active_race_1':
                    # Simulate race in 3 hours for testing
                    race_datetime = initial_simulated_time + timedelta(hours=3)
                    deadline_datetime = initial_simulated_time + timedelta(hours=1)
                    race_name = "Test Race (Anaheim 1)"
                elif simulation.scenario == 'race_in_3h':
                    # Simulate race in 3 hours for testing
                    race_datetime = initial_simulated_time + timedelta(hours=3)
                    deadline_datetime = initial_simulated_time + timedelta(hours=1)
                    race_name = "Test Race (3h)"
                elif simulation.scenario == 'race_in_1h':
                    # Simulate race in 1 hour for testing
                    race_datetime = initial_simulated_time + timedelta(hours=1)
                    deadline_datetime = initial_simulated_time - timedelta(hours=1)  # Already passed
                    race_name = "Test Race (1h)"
                elif simulation.scenario == 'race_in_30m':
                    # Simulate race in 30 minutes for testing
                    race_datetime = initial_simulated_time + timedelta(minutes=30)
                    deadline_datetime = initial_simulated_time - timedelta(hours=1, minutes=30)  # Already passed
                    race_name = "Test Race (30m)"
                elif simulation.scenario == 'race_tomorrow':
                    # Simulate race tomorrow
                    race_datetime = initial_simulated_time + timedelta(days=1)
                    deadline_datetime = initial_simulated_time + timedelta(hours=22)  # 2 hours before tomorrow
                    race_name = "Test Race (Tomorrow)"
                else:
                    return jsonify({"error": f"Unknown test scenario: {simulation.scenario}"})
                
                next_race = {
                    "name": race_name,
                    "event_date": race_datetime.isoformat()
                }
                
                # Calculate countdown using simulated time - this will change each call
                race_diff = race_datetime - current_simulated_time
                deadline_diff = deadline_datetime - current_simulated_time
                
                def format_countdown(td):
                    total_seconds = int(td.total_seconds())
                    if total_seconds <= 0:
                        return {
                            "total_seconds": 0,
                            "days": 0,
                            "hours": 0,
                            "minutes": 0,
                            "seconds": 0
                        }
                    
                    days = total_seconds // 86400
                    hours = (total_seconds % 86400) // 3600
                    minutes = (total_seconds % 3600) // 60
                    seconds = total_seconds % 60
                    
                    return {
                        "total_seconds": total_seconds,
                        "days": days,
                        "hours": hours,
                        "minutes": minutes,
                        "seconds": seconds
                    }
                
                # Use is_picks_locked for consistency
                # Create a dummy competition object for the test race
                class TestCompetition:
                    def __init__(self, name, event_date):
                        self.name = name
                        self.event_date = event_date
                        self.id = 999  # Dummy ID for test race
                
                test_comp = TestCompetition(race_name, race_datetime.date())
                picks_locked = is_picks_locked(test_comp)
                
                return jsonify({
                    "next_race": next_race,
                    "countdown": {
                        "race_start": format_countdown(race_diff),
                        "pick_deadline": format_countdown(deadline_diff)
                    },
                    "picks_locked": picks_locked
                })
            else:
                return jsonify({"error": "No active test simulation"})
        else:
            # Real mode - use actual race dates
            # Skip competitions that already have results (completed races)
            today = get_today()
            series_filter = _normalize_countdown_series(request.args.get("series"))
            if series_filter is None:
                # Homepage default: AMA chain, never auto-hijack to WSX
                series_filter = _home_default_countdown_series()

            all_upcoming = (
                Competition.query
                .filter(Competition.event_date >= today)
                .filter(Competition.series == series_filter)
                .order_by(Competition.event_date.asc())
                .all()
            )
            
            next_race_obj = None
            for comp in all_upcoming:
                if getattr(comp, "is_cancelled", False):
                    continue
                # Check if this competition has results (is completed)
                has_results = CompetitionResult.query.filter_by(competition_id=comp.id).first() is not None
                if not has_results:
                    next_race_obj = comp
                    break
            
            if not next_race_obj:
                return jsonify({
                    "error": "No upcoming races",
                    "series": series_filter,
                })
            
            # Expire the object so properties (like start_time) are re-read from database
            db.session.expire(next_race_obj)

            # Self-heal and autoset were causing DB writes on a hot endpoint.
            # Keep behavior read-only; any fixes should be done via admin tools/migrations.
            
            # Calculate countdown to race start using start_time + timezone
            schedule = _competition_race_schedule(next_race_obj)
            race_datetime = schedule["race_utc"]
            deadline_datetime = schedule["deadline_utc"]
            hero_meta = _race_hero_meta(next_race_obj, schedule)

            bg_url = None
            try:
                from trackmap_utils import race_background_static_url
                bg_path = race_background_static_url(next_race_obj)
                if bg_path:
                    bg_url = f"/static/{bg_path}"
            except Exception:
                bg_url = None
            
            next_race = {
                "id": next_race_obj.id,
                "name": next_race_obj.name,
                "series": getattr(next_race_obj, "series", None) or series_filter,
                "event_date": next_race_obj.event_date.isoformat(),
                "race_start_display": schedule["race_start_display"],
                "pick_deadline_display": schedule["pick_deadline_display"],
                "stockholm_display": schedule.get("stockholm_display"),
                "timezone": schedule["timezone"],
                "date_label": hero_meta.get("date_label"),
                "time_label": hero_meta.get("time_label"),
                "location": hero_meta.get("location"),
                "flag": hero_meta.get("flag"),
                "bg_url": bg_url,
            }
        
        now = datetime.utcnow()
        
        # Calculate time differences
        race_diff = race_datetime - now
        deadline_diff = deadline_datetime - now
        
        def format_countdown(timedelta_obj):
            total_seconds = int(timedelta_obj.total_seconds())
            if total_seconds <= 0:
                return {
                    "total_seconds": 0,
                    "days": 0,
                    "hours": 0,
                    "minutes": 0,
                    "seconds": 0
                }
            
            days = total_seconds // 86400
            hours = (total_seconds % 86400) // 3600
            minutes = (total_seconds % 3600) // 60
            seconds = total_seconds % 60
            
            return {
                "total_seconds": total_seconds,
                "days": days,
                "hours": hours,
                "minutes": minutes,
                "seconds": seconds
            }
        
        # Use is_picks_locked for consistency against the selected countdown race
        upcoming_race = next_race_obj
        picks_locked = is_picks_locked(upcoming_race) if upcoming_race else False
        
        # Check if race has results (is completed)
        series_u = (getattr(next_race_obj, "series", None) or "").upper()
        if series_u == "MXON":
            try:
                from mxon_fantasy import mxon_has_official_results

                has_results = mxon_has_official_results(int(next_race_obj.id))
            except Exception:
                has_results = False
        else:
            has_results = (
                CompetitionResult.query.filter_by(competition_id=next_race_obj.id).first()
                is not None
            )

        view_picks_race = next_race_obj
        can_view_other_picks = (
            _can_view_other_users_picks(view_picks_race) if view_picks_race else False
        )

        weather = {"available": False}
        if mode == "real" and next_race_obj is not None:
            try:
                from track_weather import get_weather_for_competition
                weather = get_weather_for_competition(next_race_obj)
            except Exception as _we:
                print(f"race_countdown weather: {_we}")

        payload = {
            "series": getattr(next_race_obj, "series", None) or series_filter,
            "next_race": next_race,
            "countdown": {
                "race_start": format_countdown(race_diff),
                "pick_deadline": format_countdown(deadline_diff)
            },
            "picks_locked": picks_locked,
            "has_results": has_results,
            "can_view_other_picks": can_view_other_picks,
            "view_picks_competition_id": view_picks_race.id if view_picks_race else None,
            "view_picks_race_name": view_picks_race.name if view_picks_race else None,
            "weather": weather,
        }

        # User-specific picks status (homepage CTA / sidebar) — never cache publicly
        uid = session.get("user_id")
        status_comp = upcoming_race or next_race_obj
        if uid and status_comp is not None:
            payload["picks_status"] = _user_picks_status_code(int(uid), status_comp)
            payload["picks_competition_id"] = int(status_comp.id)

        # Auto-freeze picks when deadline passes (homepage syncs ~every 60s).
        if picks_locked:
            snap_comp = upcoming_race or next_race_obj
            snap_id = int(getattr(snap_comp, "id", 0) or 0)
            if snap_comp is not None and snap_id > 0 and snap_id != 999:
                _auto_ensure_picks_snapshots_if_locked(snap_comp)

        # Cache for a short time to cut bandwidth if clients still poll.
        # ETag rotates each minute to keep countdown reasonably fresh.
        from flask import make_response
        from datetime import datetime as _dt
        minute_tag = _dt.utcnow().strftime("%Y%m%d%H%M")
        user_tag = f"u{uid}" if uid else "anon"
        etag = f"\"racecd:{mode}:{series_filter}:{minute_tag}:{user_tag}\""
        if request.headers.get("If-None-Match") == etag:
            resp = make_response("", 304)
        else:
            resp = make_response(jsonify(payload))
        resp.headers["ETag"] = etag
        if uid:
            resp.headers["Cache-Control"] = "private, max-age=15"
        else:
            resp.headers["Cache-Control"] = "public, max-age=60"
        return resp
        
    except Exception as e:
        print(f"Error in race_countdown: {e}")
        return jsonify({"error": str(e)}), 500

