@app.route("/api/series_leaders")
def get_series_leaders():
    """Get current leaders for each series and SMX overview"""
    try:
        _ensure_competition_result_moto_columns()
        leaders = get_series_leaders()
        mx_leaders = get_mx_series_leaders()
        smx_qualification = calculate_smx_qualification_points(limit=30)

        def format_leaders_block(block):
            formatted = {}
            for series, data in block.items():
                if data["leader"]:
                    rider = data["leader"]
                    formatted[series] = {
                        "leader": {
                            "rider_name": rider.name,
                            "rider_number": rider.rider_number,
                            "bike_brand": rider.bike_brand,
                            "points": data["points"],
                        },
                        "top_5": [
                            {
                                "rider_name": item["rider"].name,
                                "rider_number": item["rider"].rider_number,
                                "bike_brand": item["rider"].bike_brand,
                                "points": item["points"],
                            }
                            for item in data["top_5"]
                        ],
                    }
                else:
                    formatted[series] = None
            return formatted

        leaders_data = format_leaders_block(leaders)
        mx_leaders_data = format_leaders_block(mx_leaders)

        smx_450cc = smx_qualification.get("450") or []
        smx_250cc = smx_qualification.get("250") or []
        smx_250cc_east = [
            item for item in smx_250cc
            if (item[1].get("coast_250") or item[1]["rider"].coast_250 or "").strip().lower() == "east"
        ]
        smx_250cc_west = [
            item for item in smx_250cc
            if (item[1].get("coast_250") or item[1]["rider"].coast_250 or "").strip().lower() == "west"
        ]
        
        smx_overview = {
            'total_qualified': min(20, len(smx_450cc)) + min(20, len(smx_250cc)),
            'seeded_450': min(20, len(smx_450cc)),
            'lcq_450': max(0, min(10, len(smx_450cc) - 20)),
            'seeded_250': min(20, len(smx_250cc)),
            'lcq_250': max(0, min(10, len(smx_250cc) - 20)),
            '450cc_top_5': [],
            '250cc_top_5': [],
            '250cc_east_top_5': [],
            '250cc_west_top_5': []
        }
        
        # 450cc Top 5
        for i, (rider_id, data) in enumerate(smx_450cc[:5], 1):
            rider = data['rider']
            smx_overview['450cc_top_5'].append({
                'position': i,
                'rider_name': rider.name,
                'rider_number': rider.rider_number,
                'class_name': data.get('class_name'),
                'total_points': data['total_points'],
                'sx_points': data['sx_points'],
                'mx_points': data['mx_points']
            })
        
        def append_250cc_top_5(target_key, rows):
            for i, (rider_id, data) in enumerate(rows[:5], 1):
                rider = data['rider']
                smx_overview[target_key].append({
                    'position': i,
                    'rider_name': rider.name,
                    'rider_number': rider.rider_number,
                    'class_name': data.get('class_name'),
                    'coast_250': data.get('coast_250') or rider.coast_250,
                    'total_points': data['total_points'],
                    'sx_points': data['sx_points'],
                    'mx_points': data['mx_points']
                })

        append_250cc_top_5('250cc_top_5', smx_250cc)
        append_250cc_top_5('250cc_east_top_5', smx_250cc_east)
        append_250cc_top_5('250cc_west_top_5', smx_250cc_west)
        
        return jsonify({
            'success': True,
            'leaders': leaders_data,
            'mx_leaders': mx_leaders_data,
            'smx_overview': smx_overview,
            'sections': {
                'sx': {'collapsed': _is_mx_season_started()},
            },
        })
        
    except Exception as e:
        print(f"ERROR in get_series_leaders: {e}")
        return jsonify({'error': str(e)}), 500

