@app.route("/clear_all_data")
def clear_all_data():
    """Clear all picks and results - full reset"""
    try:
        if not is_admin_user():
            return jsonify({"error": "admin_only"}), 403
        
        print("🧹 Starting full reset - clearing all data...")
        
        # Clear all picks and results
        deleted_race_picks = RacePick.query.delete()
        deleted_holeshot_picks = HoleshotPick.query.delete()
        deleted_wildcard_picks = WildcardPick.query.delete()
        deleted_results = CompetitionResult.query.delete()
        deleted_holeshot_results = HoleshotResult.query.delete()
        # Wildcard results are calculated automatically from user picks vs race results
        deleted_scores = CompetitionScore.query.delete()
        deleted_out_status = CompetitionRiderStatus.query.delete()
        
        # Clear season team riders and reset team points
        deleted_season_team_riders = SeasonTeamRider.query.delete()
        season_teams = SeasonTeam.query.all()
        for team in season_teams:
            team.total_points = 0
        deleted_season_teams = 0  # Keep the teams but clear riders
        
        # Clear league points and scores
        try:
            # Reset league total_points to 0
            db.session.execute(db.text("UPDATE leagues SET total_points = 0"))
        except Exception as e:
            print(f"Warning: Could not reset league points: {e}")
        
        db.session.commit()
        
        print(f"✅ Full reset complete - deleted: {deleted_race_picks} race picks, {deleted_holeshot_picks} holeshot picks, {deleted_wildcard_picks} wildcard picks, {deleted_results} results, {deleted_holeshot_results} holeshot results, {deleted_scores} scores, {deleted_out_status} out status, {deleted_season_team_riders} season team riders, {deleted_season_teams} season teams")
        
        return jsonify({
            "message": "All data cleared successfully - full reset complete",
            "cleared": {
                "race_picks": deleted_race_picks,
                "holeshot_picks": deleted_holeshot_picks,
                "wildcard_picks": deleted_wildcard_picks,
                "results": deleted_results,
                "holeshot_results": deleted_holeshot_results,
                "scores": deleted_scores,
                "out_status": deleted_out_status,
                "season_team_riders": deleted_season_team_riders,
                "season_teams": deleted_season_teams
            }
        })
        
    except Exception as e:
        print(f"Error clearing all data: {e}")
        db.session.rollback()
        return jsonify({"error": str(e)}), 500

# get_current_time → services.picks_lock (skiva 3)


# _normalize_result_class → services.results_import (skiva 4)


def _mx_moto_championship_points(m1: int | None, m2: int | None) -> int:
    """AMA Pro Motocross: each moto awards AMA points; round total = moto1 + moto2 (1-1 → 50)."""
    total = 0
    for pos in (m1, m2):
        if pos is not None and pos >= 1:
            total += get_smx_qualification_points(pos)
    return total


def _round_championship_points_preview(
    competition: Competition | None,
    *,
    position: int | None,
    moto_1: int | None = None,
    moto_2: int | None = None,
) -> int | None:
    """Seriepoäng shown in admin bulk preview — must match standings logic."""
    if not competition:
        return None
    series = (getattr(competition, "series", None) or "").strip().upper()
    if series == "SMX":
        if not position:
            return None
        mult = float(getattr(competition, "point_multiplier", None) or 1.0)
        return int(get_smx_qualification_points(int(position)) * mult)
    if series == "MX":
        if moto_1 is not None or moto_2 is not None:
            return _mx_moto_championship_points(moto_1, moto_2)
        if position:
            return int(get_smx_qualification_points(int(position)))
        return None
    # SX / default: overall AMA points
    if position:
        return int(get_smx_qualification_points(int(position)))
    return None


def _result_points_for_standing(
    result: CompetitionResult,
    competition: Competition | None = None,
) -> int:
    series = (getattr(competition, "series", None) or "").strip().upper()
    if series == "WSX":
        if getattr(result, "rider_points", None) is not None:
            return int(result.rider_points)
        if result.position:
            return get_smx_qualification_points(result.position)
        return 0
    if series == "SMX":
        if result.position:
            mult = float(getattr(competition, "point_multiplier", None) or 1.0)
            return int(get_smx_qualification_points(result.position) * mult)
        return 0
    if series == "MX":
        m1 = getattr(result, "moto_1_position", None)
        m2 = getattr(result, "moto_2_position", None)
        if m1 is not None or m2 is not None:
            return _mx_moto_championship_points(m1, m2)
    if result.position and result.position <= 20:
        return get_smx_qualification_points(result.position)
    return 0


def _sync_smx_rider_points_for_competition(competition: Competition) -> int:
    """Persist SMX rider_points = AMA position points × round multiplier (1×/2×/3×)."""
    if (getattr(competition, "series", None) or "").strip().upper() != "SMX":
        return 0
    mult = float(getattr(competition, "point_multiplier", None) or 1.0)
    updated = 0
    for result in CompetitionResult.query.filter_by(competition_id=competition.id).all():
        if not result.position:
            continue
        pts = int(get_smx_qualification_points(result.position) * mult)
        if result.rider_points != pts:
            result.rider_points = pts
            updated += 1
    return updated


def _promoted_250_coast_by_name() -> dict[str, str]:
    """Names that moved 250 -> 450, with their historical 250 SX coast."""
    promoted: dict[str, str] = {
        # Fallback for deployments where the original 250 row was edited instead of kept.
        "haiden deegan": "west",
    }

    try:
        from models import SeasonTeamClassPromotion

        rows = SeasonTeamClassPromotion.query.filter_by(is_active=True).all()
        for row in rows:
            from_rider = getattr(row, "from_rider", None)
            to_rider = getattr(row, "to_rider", None)
            name = (getattr(to_rider, "name", None) or getattr(from_rider, "name", None) or "").strip().lower()
            coast = (getattr(from_rider, "coast_250", None) or "").strip().lower()
            if name and coast in {"east", "west"}:
                promoted[name] = coast
    except Exception:
        pass

    return promoted


def _standing_class_and_coast(
    result: CompetitionResult,
    competition: Competition,
    rider: Rider,
    promoted_250_coasts: dict[str, str],
) -> tuple[str | None, str | None]:
    rider_class = getattr(rider, "class_name", None) or getattr(rider, "rider_current_class", None)
    rider_name = getattr(rider, "name", None) or getattr(rider, "rider_name", "")
    class_name = _normalize_result_class(getattr(result, "class_name", None), rider_class)
    comp_coast = (competition.coast_250 or "").strip().lower()

    # If a rider was later moved to 450, older SX rows may have been backfilled to 450.
    # SX 250 history is identified by the promoted rider name + the SX coast calendar.
    promoted_coast = promoted_250_coasts.get((rider_name or "").strip().lower())
    if competition.series == "SX" and promoted_coast and comp_coast in {"east", "west", "both", "showdown"}:
        class_name = "250cc"
        if comp_coast in {"east", "west"}:
            return class_name, comp_coast
        return class_name, promoted_coast

    if class_name == "250cc":
        rider_coast = (getattr(rider, "coast_250", None) or "").strip().lower()
        if comp_coast in {"east", "west"}:
            return class_name, comp_coast
        if rider_coast in {"east", "west"}:
            return class_name, rider_coast

    return class_name, None


def calculate_smx_qualification_points(*, limit: int = 30) -> dict[str, list[tuple[str, dict]]]:
    """SMX Combined (SX+MX) rankings per class — top `limit` for seed/LCQ bubble (official: 20+10)."""
    standings: dict[str, dict] = {}
    promoted_250_coasts = _promoted_250_coast_by_name()
    season_year = _current_racing_season_year()
    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(Competition.series.in_(["SX", "MX"]))
        .all()
    )
    rows = _dedupe_championship_query_rows(rows)

    for result, competition, rider in rows:
        if not competition.event_date or int(competition.event_date.year) != season_year:
            continue

        class_name, coast_250 = _standing_class_and_coast(
            result, competition, rider, promoted_250_coasts
        )
        if class_name not in {"450cc", "250cc"}:
            continue

        points = _result_points_for_standing(result, competition)
        if points <= 0:
            continue

        key = f"{rider.id}:{class_name}"
        if key not in standings:
            standings[key] = {
                "rider": rider,
                "class_name": class_name,
                "coast_250": coast_250 or rider.coast_250,
                "total_points": 0,
                "sx_points": 0,
                "mx_points": 0,
            }

        if class_name == "250cc" and coast_250 in {"east", "west"}:
            standings[key]["coast_250"] = coast_250

        if competition.series == "SX":
            standings[key]["sx_points"] += points
        elif competition.series == "MX":
            standings[key]["mx_points"] += points
        standings[key]["total_points"] += points

    riders_450 = [(key, data) for key, data in standings.items() if data["class_name"] == "450cc"]
    riders_250 = [(key, data) for key, data in standings.items() if data["class_name"] == "250cc"]

    # Ensure official 2026 Combined names exist in the pool even with sparse/local results.
    # Otherwise pre-truncation / missing imports drop LCQ riders (e.g. Fredrik Noren #30).
    if season_year == 2026:
        try:
            from official_smx_2026 import (
                OFFICIAL_SMX_450_2026,
                OFFICIAL_SMX_250_2026,
                _norm_name,
            )

            by_norm_450 = {
                _norm_name(d["rider"].name): (k, d)
                for k, d in riders_450
            }
            by_norm_250 = {
                _norm_name(d["rider"].name): (k, d)
                for k, d in riders_250
            }
            db_450 = {
                _norm_name(r.name): r
                for r in Rider.query.filter_by(class_name="450cc").all()
            }
            db_250 = {
                _norm_name(r.name): r
                for r in Rider.query.filter_by(class_name="250cc").all()
            }
            for name, _sx, _mx in OFFICIAL_SMX_450_2026:
                norm = _norm_name(name)
                if norm in by_norm_450:
                    continue
                rider = db_450.get(norm)
                if not rider:
                    continue
                key = f"{rider.id}:450cc"
                standings[key] = {
                    "rider": rider,
                    "class_name": "450cc",
                    "coast_250": None,
                    "total_points": 0,
                    "sx_points": 0,
                    "mx_points": 0,
                }
            for name, _sx, _mx in OFFICIAL_SMX_250_2026:
                norm = _norm_name(name)
                if norm in by_norm_250:
                    continue
                rider = db_250.get(norm)
                if not rider:
                    continue
                key = f"{rider.id}:250cc"
                standings[key] = {
                    "rider": rider,
                    "class_name": "250cc",
                    "coast_250": rider.coast_250,
                    "total_points": 0,
                    "sx_points": 0,
                    "mx_points": 0,
                }
            riders_450 = [
                (key, data) for key, data in standings.items() if data["class_name"] == "450cc"
            ]
            riders_250 = [
                (key, data) for key, data in standings.items() if data["class_name"] == "250cc"
            ]
        except Exception as exc:
            print(f"WARNING inject official SMX riders into standings: {exc}")

    riders_450_sorted = sorted(riders_450, key=lambda x: (-x[1]["total_points"], x[0]))
    riders_250_sorted = sorted(riders_250, key=lambda x: (-x[1]["total_points"], x[0]))

    cap = max(1, int(limit))
    # Do NOT truncate before official overlay — live top-30 can omit LCQ names
    # (Noren/Bloss) whose imported SX+MX sum ranks outside the bubble.
    result = {
        "450": riders_450_sorted,
        "250": riders_250_sorted,
    }
    # 2026 only: overlay official SMX Combined (seed 1–20, LCQ 21–30).
    # Next season: drop this and trust live SX+MX sums.
    try:
        from official_smx_2026 import apply_official_smx_2026_to_qualification

        result = apply_official_smx_2026_to_qualification(
            result, season_year=season_year
        )
        for class_key in ("450", "250"):
            result[class_key] = result.get(class_key, [])[:cap]
    except Exception as exc:
        print(f"WARNING apply_official_smx_2026_to_qualification: {exc}")
        for class_key in ("450", "250"):
            result[class_key] = result.get(class_key, [])[:cap]
    return result


def smx_playoff_field_meta(
    *, limit: int = 30, competition: Competition | None = None
) -> dict[str, dict[int, dict]]:
    """
    SMX tipp-fält per klass: rider_id → {rank, zone}.
    Topp 20 = seeded, 21–30 = lcq. 450-promoted (t.ex. Deegan) tas bort från 250.
    Om competition har provisional entry: unionera in entry-only fill-ins (zone=entry).
    """
    empty: dict[str, dict[int, dict]] = {"450": {}, "250": {}}
    try:
        rankings = calculate_smx_qualification_points(limit=limit)
    except Exception as exc:
        print(f"WARNING smx_playoff_field_meta: {exc}")
        return empty

    meta_450: dict[int, dict] = {}
    meta_250: dict[int, dict] = {}
    for rank, (_key, data) in enumerate(rankings.get("450") or [], start=1):
        rider = data.get("rider")
        rid = getattr(rider, "id", None)
        if not rid:
            continue
        meta_450[int(rid)] = {
            "rank": rank,
            "zone": _smx_qualification_zone(rank),
        }
    for rank, (_key, data) in enumerate(rankings.get("250") or [], start=1):
        rider = data.get("rider")
        rid = getattr(rider, "id", None)
        if not rid:
            continue
        rid_i = int(rid)
        if rid_i in meta_450:
            continue  # races 450 SMX
        meta_250[rid_i] = {
            "rank": rank,
            "zone": _smx_qualification_zone(rank),
        }

    # When provisional entry exists: tippa = entry list only (fill-ins in, absentees out)
    try:
        entry_ids = _smx_resolve_entry_rider_ids(competition)
        has_entry = bool(entry_ids.get("450") or entry_ids.get("250"))
        if has_entry:
            e450 = set(entry_ids.get("450") or ())
            e250 = set(entry_ids.get("250") or ())
            meta_450 = {
                rid: info for rid, info in meta_450.items() if rid in e450
            }
            meta_250 = {
                rid: info for rid, info in meta_250.items() if rid in e250
            }
            for rid in e450:
                if rid not in meta_450:
                    meta_450[int(rid)] = {"rank": 100, "zone": "entry"}
            for rid in e250:
                if rid in meta_450:
                    continue
                if rid not in meta_250:
                    meta_250[int(rid)] = {"rank": 100, "zone": "entry"}
    except Exception as exc:
        print(f"WARNING smx entry field filter: {exc}")

    return {"450": meta_450, "250": meta_250}


def smx_playoff_field_ids(
    *, limit: int = 30, competition: Competition | None = None
) -> dict[str, set[int]]:
    """SMX tipp-fält: topp 20 seed + LCQ-bubbla 21–30 (+ entry fill-ins)."""
    meta = smx_playoff_field_meta(limit=limit, competition=competition)
    return {
        "450": set(meta.get("450") or {}),
        "250": set(meta.get("250") or {}),
    }


def _restrict_riders_to_smx_field(
    riders: list, class_key: str, *, competition: Competition | None = None
) -> list:
    """Keep only SMX playoff-field riders, sorted by Combined seed rank. Empty → unchanged."""
    key = "450" if class_key == "450" else "250"
    meta = smx_playoff_field_meta(competition=competition).get(key) or {}
    if not meta:
        return riders
    filtered = [r for r in riders if getattr(r, "id", None) in meta]
    filtered.sort(
        key=lambda r: (
            int((meta.get(r.id) or {}).get("rank") or 999),
            int(getattr(r, "rider_number", None) or 999),
        )
    )
    return filtered


def prune_off_roster_smx_picks(competition_id: int) -> dict[str, int]:
    """Ta bort tippa/holeshot/wildcard utanför SMX-fältet eller markerade OUT."""
    comp = Competition.query.get(int(competition_id))
    if not comp or (getattr(comp, "series", None) or "").upper() != "SMX":
        return {"deleted_race": 0, "deleted_hs": 0, "deleted_wc": 0, "skipped": 1}

    field = smx_playoff_field_ids(competition=comp)
    allowed = set(field.get("450") or ()) | set(field.get("250") or ())
    if not allowed:
        return {"deleted_race": 0, "deleted_hs": 0, "deleted_wc": 0, "skipped": 1}

    out_ids = {
        int(rid)
        for (rid,) in db.session.query(CompetitionRiderStatus.rider_id)
        .filter(
            CompetitionRiderStatus.competition_id == int(competition_id),
            CompetitionRiderStatus.status == "OUT",
        )
        .all()
    }

    def _purge(model):
        q_out = 0
        q_field = (
            model.query.filter(
                model.competition_id == int(competition_id),
                ~model.rider_id.in_(allowed),
            ).delete(synchronize_session=False)
            or 0
        )
        if out_ids:
            q_out = (
                model.query.filter(
                    model.competition_id == int(competition_id),
                    model.rider_id.in_(out_ids),
                ).delete(synchronize_session=False)
                or 0
            )
        return int(q_field) + int(q_out)

    deleted_race = _purge(RacePick)
    deleted_hs = _purge(HoleshotPick)
    deleted_wc = _purge(WildcardPick)
    if deleted_race or deleted_hs or deleted_wc:
        db.session.commit()
    return {
        "deleted_race": int(deleted_race),
        "deleted_hs": int(deleted_hs),
        "deleted_wc": int(deleted_wc),
        "skipped": 0,
    }


def _smx_qualification_zone(position: int) -> str:
    if position <= 20:
        return "seeded"
    if position <= 30:
        return "lcq"
    return "out"


def _format_smx_qualification_rows(
    entries: list[tuple[str, dict]],
    *,
    class_name: str,
) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for position, (_key, data) in enumerate(entries, start=1):
        rider = data["rider"]
        zone = _smx_qualification_zone(position)
        # Playoff start: AMA-skala för seed 1–20; LCQ (21–30) börjar på 0
        seed_points = int(get_smx_qualification_points(position)) if position <= 20 else 0
        rows.append(
            {
                "position": position,
                "rider_id": rider.id,
                "rider_name": rider.name,
                "rider_number": rider.rider_number,
                "bike_brand": rider.bike_brand or "",
                "rider_class": class_name,
                "coast_250": data.get("coast_250") or rider.coast_250,
                "total_points": int(data["total_points"])
                if abs(data["total_points"] - round(data["total_points"])) < 0.001
                else round(data["total_points"], 1),
                "sx_points": int(data["sx_points"])
                if abs(data["sx_points"] - round(data["sx_points"])) < 0.001
                else round(data["sx_points"], 1),
                "mx_points": int(data["mx_points"])
                if abs(data["mx_points"] - round(data["mx_points"])) < 0.001
                else round(data["mx_points"], 1),
                "seed_points": seed_points,
                "qualified": position <= 20,
                "zone": zone,
                "zone_label": "Direktkval" if zone == "seeded" else ("LCQ" if zone == "lcq" else "Utanför"),
            }
        )
    return rows

def get_series_leaders():
    """Get current leaders for each series (450cc, 250cc East, 250cc West)"""
    leaders = {
        '450cc': {'leader': None, 'points': 0, 'top_5': []},
        '250cc_east': {'leader': None, 'points': 0, 'top_5': []},
        '250cc_west': {'leader': None, 'points': 0, 'top_5': []}
    }

    standings = {key: {} for key in leaders}
    promoted_250_coasts = _promoted_250_coast_by_name()
    rows = (
        db.session.query(CompetitionResult, Competition, Rider)
        .join(Competition, Competition.id == CompetitionResult.competition_id)
        .join(Rider, Rider.id == CompetitionResult.rider_id)
        .filter(Competition.series == "SX")
        .all()
    )

    for result, competition, rider in rows:
        class_name, coast_250 = _standing_class_and_coast(
            result, competition, rider, promoted_250_coasts
        )
        points = _result_points_for_standing(result)
        if points <= 0:
            continue

        series_key = None
        if class_name == "450cc":
            series_key = "450cc"
        elif class_name == "250cc":
            if coast_250 in {"east", "west"}:
                series_key = f"250cc_{coast_250}"

        if not series_key:
            continue

        rider_key = rider.id
        row = standings[series_key].setdefault(rider_key, {"rider": rider, "points": 0})
        row["points"] += points

    for series_key, rows_by_rider in standings.items():
        top_rows = sorted(rows_by_rider.values(), key=lambda x: x["points"], reverse=True)
        leaders[series_key]["top_5"] = top_rows[:5]
        if top_rows:
            leaders[series_key]["leader"] = top_rows[0]["rider"]
            leaders[series_key]["points"] = top_rows[0]["points"]

    return leaders


